import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-b1-001","clusterId":"B","werkstueckRef":"B.1","stufe":1,"question":"Eine Kollegin ist überzeugt, ihr neuer Kollege sei unzuverlässig. Seit Wochen sammelt sie jede seiner Verspätungen und erzählt davon. Dass er gestern ein Projekt pünktlich und sauber abgeliefert hat, nennt sie „reinen Zufall“. Was ist an ihrem Vorgehen am ehesten fehlerhaft?","options":["Sie verallgemeinert vorschnell: Aus einigen Verspätungen in wenigen Wochen schließt sie auf seine ganze Arbeitsweise, obwohl die Zeit dafür zu kurz ist.","Sie schreibt die Verspätungen allein seinem Charakter zu, statt zu fragen, ob äußere Umstände dahinterstecken, die er selbst kaum beeinflussen kann.","Sie sucht, deutet und behält Informationen so, dass sie ihr bestehendes Urteil über ihn stützen, und wertet Gegenteiliges wie das pünktliche Projekt als Zufall ab.","Sie erzählt die Verspätungen weiter, statt sie mit ihm selbst zu besprechen; ihr Urteil über ihn ist dagegen durch das wiederholte Muster seiner Verspätungen gut gedeckt."],"correctIndex":2,"explanation":"Die Kollegin prüft ihr Urteil nicht, sie dekoriert es. Sie sammelt gezielt, was passt (einseitige Suche), und erklärt den Gegenbeleg zum „Zufall“ (einseitige Deutung). Auch die Erinnerung läuft bei diesem Muster typischerweise einseitig: Gründe für die eigene Seite werden eher gefunden und behalten. Das ist der Bestätigungsfehler: keine bloße Sturheit, sondern ein Verarbeitungsmuster auf diesen drei Ebenen. Es fehlt vor allem eines: der ernsthafte Versuch, das eigene Urteil zu widerlegen. Die Übernahme der Teammeinung klingt nach Mitläufertum, doch die Verspätungen hat sie selbst gesammelt. Die Berufung auf eine Vorgesetzte wäre ein Autoritätsfehler, doch es kommt keine Vorgesetzte vor. Verspätungen als Ursache von Unruhe im Team wären eine Verwechslung von Zeitlichem und Ursächlichem, doch von Unruhe im Team ist keine Rede.","coreRule":"⚡ Suche zuerst nach dem stärksten Beleg gegen deine Position, nicht nach dem nächsten dafür.","quote":"Er hat nicht ermittelt. Er hat nur seine anfängliche Vermutung dekoriert.","quoteLabel":"Merksatz:","beleg":"Werkstück B.1 (Der Detektiv und der Gärtner; Kernidee; Kontext & Tiefe, drei Ebenen)","status":"entwurf","scenario":"","kurz":"Sie prüft ihr Urteil nicht, sondern stützt es: Passendes wird gesammelt und erinnert, der Gegenbeleg gilt als „Zufall“. Das ist der Bestätigungsfehler. Es fehlt der ernsthafte Versuch, das eigene Urteil zu widerlegen.","prueffrage":"Was müsste der Kollege tun, damit sie ihr Urteil über ihn ändern würde?","rueckmeldung":[{"option":0,"text":"Ein Urteil nach wenigen Wochen kann tatsächlich voreilig sein. Das erklärt aber nicht, warum sie das pünktliche, saubere Projekt als „reinen Zufall“ abtut. Dort liegt der Fehler: Sie bewertet Belege je nach Urteil unterschiedlich."},{"option":1,"text":"Die Frage nach äußeren Umständen ist bei Verspätungen berechtigt. Doch der Text zeigt etwas anderes: Sie sammelt gezielt, was passt, und tut Gegenteiliges als Zufall ab. Das ist der Fehler, auch wenn sie die Umstände außer Acht lässt."},{"option":3,"text":"Mit ihm direkt zu sprechen wäre klüger als das Weitererzählen. Ihr Urteil ist dagegen nicht gut gedeckt: Das Muster hat sie selbst zusammengetragen und den Gegenbeleg abgewertet. Ein so ausgewähltes Muster trägt den Schluss nicht."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175, 178","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nickerson (1998), Verlagsfassung APA","oeffentlich":false,"doi":"10.1037/1089-2680.2.2.175"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"dfd9343a8cdd8b5f"}},{"id":"qx-b1-002","clusterId":"B","werkstueckRef":"B.1","stufe":2,"question":"Was ist an diesem Vorgehen das Hauptproblem?","scenario":"Du willst einen Staubsaugerroboter kaufen und hast dich schon in ein Modell verliebt. Abends gibst du in die Suchmaschine „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ ein.","options":["Du suchst mit „Vorteile“ und „begeisterte Erfahrungsberichte“ nur nach Zustimmung, sodass das Ergebnis feststeht, bevor du etwas gelesen hast.","Du suchst nur nach einem einzigen Modell, sodass dir andere Geräte, die vielleicht besser oder günstiger wären, gar nicht erst begegnen.","Du verlässt dich auf Erfahrungsberichte im Netz, sodass du nur Einzelerlebnisse liest, statt unabhängige Tests mit Messwerten heranzuziehen.","Du lässt dich von deiner Verliebtheit leiten, statt vorher nüchtern festzulegen, welche Eigenschaften dir an einem solchen Gerät wichtig sind."],"correctIndex":0,"explanation":"Wer „Modell X Vorteile“ und „Modell X begeisterte Erfahrungsberichte“ eingibt, fragt nicht nach Belegen gegen das Modell, sondern nach Argumenten dafür. Das ist die tendenziöse Suche: Wir googeln nicht „Beweise gegen meine Position“, sondern „Argumente für meine Position“. Das Problem liegt hier auf der Ebene der Suche, noch bevor Deutung oder Erinnerung ins Spiel kommen. Eine Suche, die die Entscheidung wirklich prüft, würde gezielt auch nach „Kritik“, „Probleme mit“ oder „Gegenargumenten“ fragen.","coreRule":"⚡ Schon die Wahl der Suchbegriffe kann das Ergebnis vorwegnehmen: Wer nur nach Bestätigung fragt, findet nur Bestätigung.","beleg":"Werkstück B.1 (Kontext & Tiefe, Ebene „Suche“; Werkbank-Frage)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"64cdbb3175c78c11","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Wer „Vorteile“ und „begeisterte Erfahrungsberichte“ eingibt, bestellt Zustimmung und bekommt sie auch. Der Fehler liegt schon in der Suche: Eine echte Prüfung würde gezielt auch nach „Kritik“ oder „Probleme mit“ fragen.","prueffrage":"Welche Wörter stehen in den beiden Suchanfragen, und nach welchen Wörtern wird dort gar nicht gesucht?","rueckmeldung":[{"option":1,"text":"Die Beschränkung auf ein Modell verengt tatsächlich die Auswahl. Das eigentliche Problem liegt aber in den Suchbegriffen: Auch bei mehreren Modellen würden „Vorteile“ und „begeisterte Berichte“ nur Zustimmung liefern."},{"option":2,"text":"Einzelerlebnisse sind weniger belastbar als unabhängige Tests, das stimmt grundsätzlich. Entscheidend ist hier aber die Fragerichtung: Auch bei Testberichten würde „Vorteile“ nur das Positive herausfiltern."},{"option":3,"text":"Vorher Kriterien festzulegen, ist sinnvoll, und die Verliebtheit erklärt, warum du so suchst. Das Hauptproblem bleibt aber die Suche selbst: Auch mit klaren Kriterien würden diese Suchbegriffe nur Zustimmung abrufen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"64cdbb3175c78c11"}},{"id":"qx-b1-003","clusterId":"B","werkstueckRef":"B.1","stufe":3,"question":"Ein Freund investiert seit Jahren in ein Finanzsystem, das hohe Renditen garantiert. Mehrere Bekannte haben ihr Geld verloren, eine Verbraucherzentrale warnt, und die Auszahlungen stocken. Er sagt trotzdem: „Das sind alles Neider, mein System funktioniert.“ Warum ist sein Festhalten hier ein ernstes Problem und nicht nur eine harmlose Eigenart?","options":["Weil ihm schlicht die Informationen über das System fehlen und wer zu wenig weiß, mit seinen Entscheidungen leicht Schaden anrichtet.","Weil er sich nur unter Gleichgesinnten bewegt, die ihn bestärken, und der Gruppendruck dieses Umfelds ihn vom Umdenken abhält.","Weil es hier um ein wichtiges Thema geht und er trotz deutlicher Gegenbeweise nicht umdenkt, weil ihm sein Weltbild wichtiger ist.","Weil er seine Überzeugung auf ein einzelnes Erlebnis stützt und aus diesem Einzelfall auf die Wirksamkeit des ganzen Systems schließt."],"correctIndex":2,"explanation":"Einseitige Informationsverarbeitung ist an sich oft harmlos: Wer glaubt, die eigene Fußballmannschaft sei die beste, richtet damit kaum Schaden an. Gefährlich wird es, wenn zwei Dinge zusammenkommen: Es geht um ein wichtiges Thema, und überwältigende Gegenbeweise ändern nichts mehr an der Meinung. Dann wird der Schutz des eigenen Weltbildes wichtiger als die Anerkennung der Realität, und Menschen bleiben in betrügerischen Finanzsystemen, folgen gefährlichen Kulten oder lehnen medizinisch notwendige Behandlungen ab. Entscheidend sind das wichtige Thema und die Unbeweglichkeit gegenüber überwältigenden Gegenbeweisen. Fehlende Information ist hier nicht das Problem, denn die Warnungen und die stockenden Auszahlungen kennt er und schlägt sie trotzdem in den Wind. Von einem bestärkenden Umfeld oder von Gruppendruck ist im Fall keine Rede. Von einem einzelnen Erlebnis als Grundlage ebenso wenig; gegen sein System sprechen vielmehr mehrere unabhängige Hinweise.","coreRule":"⚡ Kritisch wird es bei wichtigen Themen, wenn Gegenbeweise nichts mehr bewegen.","beleg":"Werkstück B.1 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Entscheidend ist nicht die einseitige Sicht an sich, sondern die Kombination: ein folgenreiches Thema und mehrere unabhängige Gegenhinweise, die ihn nicht bewegen. Dann schützt er sein Weltbild statt sein Geld.","prueffrage":"Welche Warnzeichen liegen ihm schon vor, und wie erklärt er sie sich?","rueckmeldung":[{"option":0,"text":"Fehlendes Wissen kann tatsächlich zu schlechten Entscheidungen führen. Hier kennt er aber die Verluste der Bekannten, die Warnung und die stockenden Auszahlungen und wertet sie ab. Es mangelt nicht an Information, sondern am Umgang mit ihr."},{"option":1,"text":"Ein bestärkendes Umfeld kann Festhalten verstärken. Davon steht im Fall aber nichts: Von Gleichgesinnten oder Gruppendruck ist keine Rede. Entscheidend ist, dass er sich trotz deutlicher Gegenbeweise bei einem wichtigen Thema nicht bewegt."},{"option":3,"text":"Aus einem Einzelfall auf das Ganze zu schließen, wäre ein eigener Denkfehler. Hier fehlt aber ein solches Einzelerlebnis: Gegen das System sprechen mehrere unabhängige Hinweise, die er alle beiseiteschiebt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"175","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"b37453d19d07877f"}},{"id":"qx-b1-004","clusterId":"B","werkstueckRef":"B.1","stufe":4,"question":"Welche Einschätzung dieser Reaktion trifft zu?","scenario":"Du erzählst einem Bekannten, dass eine Behörde seine Behauptung über eine geheime Absprache geprüft und widerlegt hat. Er antwortet: „Genau das würden sie ja sagen – das beweist es erst recht!“","options":["Er greift die Behörde als Quelle an, statt auf ihre Prüfung einzugehen, sodass er ihre Glaubwürdigkeit bestreitet statt ihrer Begründung.","Er deutet auch die Widerlegung durch die Behörde als weiteren Beleg um, sodass nichts mehr gegen seine Überzeugung von der Absprache sprechen kann.","Er bleibt der Behörde gegenüber skeptisch, wie es kritisches Denken verlangt, sodass er ihr Ergebnis hinterfragt, statt es ungeprüft zu übernehmen.","Er schließt nachvollziehbar, weil bei einer echten Absprache ein Dementi zu erwarten wäre, sodass die Antwort der Behörde gut zu seiner Annahme passt."],"correctIndex":1,"explanation":"Wenn auch die Widerlegung als Beweis gilt, wird der Glaube zur „sich selbst versiegelnden Schleife“: Jedes Ereignis, egal wie unzusammenhängend, wird als weiterer Beweis gedeutet. Das ist der Bestätigungsfehler, die Neigung, Informationen so zu deuten, dass sie die eigene Überzeugung stützen. Eine hilfreiche Gegenfrage lautet: Welches Ergebnis würde er überhaupt als Widerlegung gelten lassen? Ein Strohmann klingt naheliegend, doch er gibt die Aussage der Behörde nicht verzerrt wieder, er deutet sie um. Eine Berufung auf Fachleute wäre ein Autoritätsargument, doch er nennt keine, sondern lehnt gerade die Behörde ab. Der Mitläufereffekt setzt voraus, dass er die Meinung anderer übernimmt, doch von anderen ist im Gespräch keine Rede.","coreRule":"⚡ Wenn selbst die Widerlegung als Bestätigung zählt, kann nichts mehr gegen die Überzeugung sprechen.","beleg":"Werkstück B.1 (Anwendung & Relevanz: Bei Verschwörungsmythen)","status":"entwurf","kurz":"Wer auch die Widerlegung als Beweis wertet, sodass nichts mehr gegen die eigene Überzeugung sprechen kann, hat sie gegen Prüfung abgeschottet. Das ist Bestätigungsfehler: Jedes Ergebnis wird so gedeutet, dass es die Annahme stützt.","prueffrage":"Welche neue Information über die Absprache bringt der Bekannte vor, nachdem er von der Prüfung gehört hat?","rueckmeldung":[{"option":0,"text":"Er zweifelt tatsächlich die Behörde an, statt auf ihre Begründung einzugehen. Das Entscheidende ist aber, dass auch die Widerlegung zum Beleg umgedeutet wird und nichts mehr gegen seine Annahme sprechen kann."},{"option":2,"text":"Skepsis gegenüber Behörden ist grundsätzlich berechtigt. Sie bleibt aber nur dann offen, wenn ein Ergebnis ihn umstimmen könnte. Hier gilt jedes Ergebnis als Bestätigung, also wird nichts mehr hinterfragt."},{"option":3,"text":"Ein Dementi wäre bei einer echten Absprache zu erwarten, das stimmt. Es käme aber genauso, wenn es keine Absprache gibt, und kann deshalb nichts beweisen. Ein Beleg muss bei Wahrheit und Irrtum unterschiedlich ausfallen."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Confirmation Bias“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"Nickerson, R. S. (1998): Confirmation Bias: A Ubiquitous Phenomenon in Many Guises. Review of General Psychology 2(2), 175–220","oeffentlich":true,"url":"https://pages.ucsd.edu/~mckenzie/nickersonConfirmationBias.pdf","seite":"178","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"df5af6cc43820d6d"}},{"id":"qx-b1-005","clusterId":"B","werkstueckRef":"B.2","stufe":1,"question":"Eine Kollegin stellt nach drei Wochen Einarbeitung fest: „Ich habe die Fehler in meinem Bericht gar nicht bemerkt. Ich hielt ihn für einwandfrei, dabei war er voller Mängel.“ Welche Erklärung für diese Lage ist am sparsamsten?","options":["Sie hat schwach gearbeitet und besitzt zugleich noch nicht die Fähigkeiten, die nötig wären, um Mängel im eigenen Bericht zu bemerken.","Sie hat schwach gearbeitet und stand beim Gegenlesen unter hohem Zeitdruck, sodass sie Fehler übersah, die sie sonst bemerkt hätte.","Sie hat schwach gearbeitet und ahnt die Mängel im Bericht, redet sich die Qualität aber schön, um ihr Selbstbild zu schützen.","Sie hat schwach gearbeitet und beim Prüfen nur nach Hinweisen gesucht, die ihre gute Meinung stützen, sodass ein Bestätigungsfehler wirkte."],"correctIndex":0,"explanation":"Hier greifen zwei Probleme ineinander: Die Leistung ist schlecht, und zugleich fehlt der Maßstab, um das zu merken. Die Fähigkeiten, die man für einen guten Bericht braucht, sind dieselben, die man braucht, um die Qualität eines Berichts zu beurteilen. Wer sie noch nicht hat, kann seine Fehler also nicht erkennen, und die Selbstsicherheit bleibt hoch. So beschreiben es Dunning und Kruger; wie viel davon echte metakognitive Blindheit und wie viel ein statistischer Effekt ist, ist in der Fachliteratur umstritten. In der Studie von Kruger und Dunning (1999) lag das schwächste Viertel beim 12. Perzentil und hielt sich für das 68., während das beste Viertel beim 86. lag und sich für das 74. hielt; das Problem trifft also die Schwächsten am härtesten. Zeitdruck klingt naheliegend, wäre aber eine zusätzliche Annahme, die der Fall nicht hergibt, und bei Hast würde sie die Mängel eher ahnen. Schönreden zum Schutz des Selbstbilds setzt voraus, dass sie die Mängel ahnt, doch sie sagt, sie habe sie nicht bemerkt. Ein Bestätigungsfehler müsste erst vorausgesetzt werden, während die fehlende Beurteilungsfähigkeit allein schon alles erklärt.","coreRule":"⚡ Wem das Können fehlt, dem fehlt oft auch der Maßstab, um das zu bemerken.","beleg":"Werkstück B.2 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Schwache Leistung und fehlender Maßstab greifen ineinander: Wer die Fähigkeiten für einen guten Bericht noch nicht hat, kann auch dessen Mängel kaum erkennen. Zeitdruck, Schönreden oder Bestätigungsfehler wären zusätzliche Annahmen, die der Fall nicht hergibt.","prueffrage":"Welche Annahmen musst du über die Kollegin treffen, die der Fall selbst gar nicht erwähnt?","rueckmeldung":[{"option":1,"text":"Zeitdruck klingt plausibel, ist aber eine Zusatzannahme, die der Fall nicht nennt. Außerdem setzt er voraus, dass sie die Fehler sonst erkannt hätte, und gerade das ist hier fraglich. Bei Hast würde man Mängel eher ahnen."},{"option":2,"text":"Schönreden zum Schutz des Selbstbilds kommt im Alltag oft vor. Es setzt aber voraus, dass sie die Mängel ahnt. Sie sagt jedoch, sie habe sie nicht bemerkt und den Bericht für einwandfrei gehalten."},{"option":3,"text":"Beim Prüfen sucht man tatsächlich gern Bestätigung. Dieser Fehler müsste hier aber erst unterstellt werden, und auch er braucht einen Maßstab, um Mängel zu erkennen. Fehlt dieser Maßstab, ist die Erklärung bereits vollständig."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"},{"typ":"doi","kurz":"Magnus, J. R.; Peresetsky, A. A. (2022): A Statistical Explanation of the Dunning–Kruger Effect. Frontiers in Psychology 13","oeffentlich":true,"doi":"10.3389/fpsyg.2022.840180","abruf":"2026-10-12"},{"typ":"doi","kurz":"Nuhfer, E. u. a. (2016): Random Number Simulations Reveal How Random Noise Affects the Measurements and Graphical Portrayals of Self-Assessed Competency. Numeracy 9(1), Art. 4","oeffentlich":true,"doi":"10.5038/1936-4660.9.1.4","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"fe0134046d669c15"}},{"id":"qx-b1-007","clusterId":"B","werkstueckRef":"B.2","stufe":2,"question":"Was verrät diese Szene über die Verlässlichkeit der Einschätzung deines Nachbarn?","scenario":"Dein Nachbar hat sich zwei Wochen lang Videos zur Gebäudestatik angesehen. Beim Hausbau erklärt er dem Bauingenieur, dessen Berechnungen seien „unnötig kompliziert“, und Experten seien ohnehin „alle gekauft“. Auf die Nachfrage, wie die Lasten im Dachstuhl verteilt werden, weicht er aus und wiederholt nur, er sehe das „ganz klar“.","options":["Seine große Gewissheit nach zwei Wochen Videos und die Abwertung der Fachleute sprechen eher für Selbstüberschätzung, denn Anfängern bleiben Lücken im eigenen Wissen oft verborgen.","Dass sich Bauingenieure gelegentlich irren, macht seine Skepsis gegenüber den Berechnungen für den Dachstuhl berechtigt, denn auch ein Fachmann sollte nicht ungeprüft recht bekommen.","Dass ihm die Berechnungen des Ingenieurs unnötig kompliziert erscheinen, spricht dafür, dass sie überladen sind, denn gute technische Lösungen sind meist einfach.","Weil es um sein eigenes Haus geht, hat er ein starkes Eigeninteresse an einem guten Ergebnis, und das spricht dafür, dass er seine Aussagen sorgfältig geprüft hat."],"correctIndex":0,"explanation":"Wer nur kurz in ein komplexes Feld hineingeschaut hat, dem fehlen oft genau die Fähigkeiten, um die Lücken im eigenen Wissen zu erkennen; dann fühlt sich das wenige Gelernte wie ein vollständiges Bild an. Typische Anzeichen sind große Gewissheit nach kurzer Beschäftigung und das pauschale Abwerten von Fachleuten („alle gekauft“). Dazu passt, dass er der konkreten Sachfrage ausweicht: Echte Prüfung würde die Gegenargumente verstehen wollen, statt die Berechnungen als „unnötig kompliziert“ abzutun. Sicherheit allein sagt wenig darüber aus, ob jemand recht hat, und hier spricht die Konstellation eher für Selbstüberschätzung. Ob er im Einzelfall trotzdem etwas Richtiges sagt, bleibt offen und ließe sich nur an der Sache selbst prüfen.","coreRule":"⚡ Große Sicherheit nach kurzer Beschäftigung ist ein Warnzeichen, kein Qualitätsmerkmal.","beleg":"Werkstück B.2 (Red Flags; Anwendung & Relevanz: Das Betriebssystem der „Selber-Denker“)","status":"entwurf","kurz":"Große Gewissheit nach nur zwei Wochen Videos, pauschales Abwerten der Fachleute und Ausweichen vor der Sachfrage passen eher zu Selbstüberschätzung. Wer wenig weiß, sieht die eigenen Lücken oft nicht und hält das Gelernte für ein vollständiges Bild.","prueffrage":"Was antwortet dein Nachbar, wenn man ihn bittet, seine Einschätzung an einem konkreten Bauteil zu erklären?","rueckmeldung":[{"option":1,"text":"Dass sich auch Fachleute irren, stimmt, und blindes Vertrauen wäre falsch. Doch solche Skepsis ist erst berechtigt, wenn sich ein konkreter Fehler benennen lässt, und genau dem weicht der Nachbar aus."},{"option":2,"text":"Gute Lösungen sind oft tatsächlich einfach. Ob eine Berechnung unnötig kompliziert ist, kann aber nur beurteilen, wer sie versteht. Der Eindruck des Nachbarn zeigt eher eine Lücke im eigenen Verständnis als einen Mangel der Rechnung."},{"option":3,"text":"Beim eigenen Haus steht für ihn viel auf dem Spiel, das stimmt. Eigeninteresse sichert aber keine Sorgfalt: Wer auf die Sachfrage keine Antwort hat, hat vermutlich nicht geprüft, so groß der Wunsch nach einem guten Ergebnis auch ist."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Light, N. u. a. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"},{"typ":"doi","kurz":"Kruger, J.; Dunning, D. (1999): Unskilled and Unaware of It. Journal of Personality and Social Psychology 77(6), 1121–1134","oeffentlich":false,"doi":"10.1037/0022-3514.77.6.1121"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be22d8c8392d8510"}},{"id":"qx-b1-008","clusterId":"B","werkstueckRef":"B.2","stufe":4,"question":"Welche Rückmeldung an deine Kollegin trifft am genauesten, was die Daten tragen?","scenario":"Eine Pressemitteilung fasst eine Untersuchung aus den USA zusammen: In fünf Befragungen zu sieben Themen mit wissenschaftlichem Konsens, darunter Impfungen, Gentechnik, Evolution und Klimawandel, schätzten diejenigen, die dem Konsens am stärksten widersprachen, ihr eigenes Wissen am höchsten ein, schnitten in einem Wissenstest im Mittel aber am schlechtesten ab. Beim Klimawandel war dieser Zusammenhang schwächer. Die Teilnehmenden wurden nur befragt und getestet, niemand wurde einer Bedingung zugeteilt. Deine Kollegin will in einem Vortrag in Deutschland sagen: „Selbstüberschätzung macht Menschen zu Gegnern des Konsenses, und zwar bei jedem Wissenschaftsthema.“","options":["Der Satz ist belegt, weil fünf getrennte Befragungen dasselbe Muster zeigten; offen ist nur, ob er sich auf Deutschland übertragen lässt.","Der Satz geht zu weit: Selbstüberschätzung führt zwar zur Ablehnung des Konsenses, beim Klimawandel aber schwächer; zu streichen ist nur „bei jedem Thema“.","Der Satz geht zu weit: Die Befragungen zeigen nur, dass beides zusammen auftritt, nicht was woraus folgt, und beim Klimawandel war es schwächer.","Der Satz ist belegt, weil die Konsensgegner im Wissenstest messbar schlechter abschnitten; ein objektives Testergebnis zeigt mehr als bloße Meinung."],"correctIndex":2,"explanation":"Deine Kollegin springt von einem Zusammenhang auf eine Ursache und dehnt ihn zugleich auf jedes Thema aus. Eine Befragung misst, welche Merkmale gemeinsam auftreten, nicht was woraus folgt: Denkbar ist, dass Selbstüberschätzung zur Ablehnung führt, dass die Ablehnung das Gefühl von Besserwissen verstärkt oder dass ein dritter Faktor beides erzeugt. Dazu kommt die Reichweite: Der beschriebene Befund stammt aus fünf Studien in den USA (Light u. a. 2022, Science Advances) zu sieben Themen mit wissenschaftlichem Konsens, und bei stark politisierten Themen, vor allem beim Klimawandel, war der Zusammenhang schwächer. Ein „verursacht“ und ein „bei jedem Thema“ gehen also weiter, als die Daten tragen; als Waffe gegen Andersdenkende taugt der Befund nicht. Fünf Befragungen wiederholen denselben Zusammenhang, machen ihn aber nicht zur Ursache, solange niemand einer Bedingung zugeteilt wurde. Auch ein objektiver Wissenstest misst nur eines der gemeinsam auftretenden Merkmale genauer und klärt die Richtung nicht.","coreRule":"⚡ Ein Zusammenhang aus Befragungen zeigt, was zusammen auftritt, nicht was woraus folgt.","beleg":"Werkstück B.2 (Anwendung & Relevanz); Fn. gl-b-light (Light u. a. 2022, Science Advances 8(29), eabo0038)","status":"entwurf","kurz":"Befragungen zeigen, welche Merkmale gemeinsam auftreten, nicht was woraus folgt. Die Ablehnung könnte das Besserwisser-Gefühl auch verstärken oder ein dritter Faktor beides erzeugen. Beim Klimawandel war der Zusammenhang zudem schwächer.","prueffrage":"Wurde irgendjemand einer Bedingung zugeteilt, und welche Themen deckt die Untersuchung überhaupt ab?","rueckmeldung":[{"option":0,"text":"Ob sich US-Daten auf Deutschland übertragen lassen, ist wirklich offen. Doch mehrere Befragungen mit demselben Muster wiederholen nur den Zusammenhang und machen ihn nicht zur Ursache, und beim Klimawandel war er sogar schwächer."},{"option":1,"text":"Dass „bei jedem Thema“ zu weit geht, stimmt: Beim Klimawandel war der Zusammenhang schwächer. Der Satz sagt aber weiter „führt zur Ablehnung“, und welche Richtung gilt, klärt eine reine Befragung nicht."},{"option":3,"text":"Ein Wissenstest ist ein genaueres Maß als eine bloße Meinung, und die Konsensgegner schnitten darin schlechter ab. Er verbessert aber nur die Messung eines der gemeinsam auftretenden Merkmale und klärt nicht, was woraus folgt oder ob das für jedes Thema gilt."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Light, N.; Fernbach, P. M.; Rabb, N.; Geana, M. V.; Sloman, S. A. (2022): Knowledge overconfidence is associated with anti-consensus views on controversial scientific issues. Science Advances 8(29), eabo0038 (frei über PMC9299547)","oeffentlich":true,"doi":"10.1126/sciadv.abo0038","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"db8250a1345ef432"}},{"id":"qx-b1-009","clusterId":"B","werkstueckRef":"B.3","stufe":1,"question":"Welche Einschätzung ist hier am ehesten ein Fehlschluss und warum?","options":["Sie schätzt das Hai-Risiko nach den lebhaften Nachrichtenbildern der letzten Woche ein, die ihr leicht einfallen, nicht nach der tatsächlichen Häufigkeit von Haiangriffen und Autounfällen.","Sie schätzt das Hai-Risiko zutreffend ein, unterschätzt aber die Autofahrt zum Supermarkt, weil sie dabei selbst am Steuer sitzt und die Gefahr deshalb für gut beherrschbar hält.","Sie schätzt das Hai-Risiko vertretbar ein, und der Vorwurf des Freundes ist voreilig, weil sie auf das Baden am Küstenort leicht verzichten kann, auf die Fahrt zum Supermarkt dagegen kaum.","Sie schätzt das Hai-Risiko nach einem einzigen Angriff in der letzten Woche ein und schließt daraus auf eine dauerhafte Gefahr am Küstenort, obwohl ein einzelner Vorfall wenig über die Lage dort aussagt."],"correctIndex":0,"explanation":"Mara beurteilt die Wahrscheinlichkeit danach, wie leicht ihr Beispiele einfallen. Ein dramatischer, frisch gesehener Fall mit starken Bildern ist mental sehr präsent, die Gefahr der Autofahrt dagegen nur eine blasse, abstrakte Statistik. Das Risiko, auf der Fahrt tödlich zu verunglücken, ist statistisch um ein Vielfaches höher als das, von einem Hai getötet zu werden. Leichtigkeit des Abrufs hängt von Emotionalität, Lebhaftigkeit, zeitlicher Nähe und medialer Wiederholung ab, nicht nur von der tatsächlichen Häufigkeit (Tversky und Kahneman, 1974). Hier liegt die Verfügbarkeitsheuristik vor.","coreRule":"⚡ Was mir leicht einfällt, erscheint mir wahrscheinlicher und wichtiger, auch wenn die Statistik etwas anderes sagt.","beleg":"Werkstück B.3 (Kernidee; Kontext & Tiefe); Fn. gl-b-verfuegbarkeit (Tversky/Kahneman 1974, Science 185(4157), S. 1127); Fn. gl-b-hai-auto (International Shark Attack File; NHTSA 2024, Overview of Motor Vehicle Traffic Crashes in 2022)","status":"entwurf","scenario":"Nach einer Woche voller Nachrichten über einen Hai-Angriff an einem Küstenort sagt Mara: „Ich gehe dort nicht mehr ins Wasser, das ist mir zu gefährlich.“ Am selben Tag fährt sie ohne zu zögern mit dem Auto zum Supermarkt. Ein Freund hält ihr vor, ihre Risikoeinschätzung sei verzerrt.","kurz":"Mara urteilt danach, wie leicht ihr Beispiele einfallen: Der Hai-Angriff ist frisch und bildstark, die Autogefahr nur eine blasse Zahl. Tatsächlich ist das Unfallrisiko auf der Straße um ein Vielfaches höher als das, von einem Hai getötet zu werden.","prueffrage":"Was genau hat Mara in dieser Woche erfahren: eine Zahl, die Meinung von Bekannten oder Berichte über einen Fall?","rueckmeldung":[{"option":1,"text":"Dass man sich am Steuer sicherer fühlt, kommt vor, erklärt aber Maras Haltung nicht: Ihr Hai-Risiko ist gerade nicht zutreffend, sondern überschätzt, weil die Bilder der letzten Woche so präsent sind."},{"option":2,"text":"Auf das Baden kann sie leichter verzichten als auf das Auto, das ist ein vernünftiger Gedanke bei der Entscheidung. Der Freund bemängelt aber die Einschätzung der Gefahr selbst, und die fällt bei ihr nach der Präsenz der Bilder aus, nicht nach der Häufigkeit."},{"option":3,"text":"Ein einzelner Vorfall sagt in der Tat wenig über die Lage vor Ort aus. Mara schließt aber nicht aus Zahlen oder auf eine dauerhafte Gefahr, sondern lässt sich von der Fülle der Bilder und Berichte der letzten Woche leiten."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"cea0fc59db914ff6"}},{"id":"qx-b1-010","clusterId":"B","werkstueckRef":"B.3","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Kollegin fehlerhaft, und wie schätzt du dein Risiko stattdessen sinnvoll ein?","scenario":"Seit drei Tagen berichtet die Lokalpresse täglich über Wohnungseinbrüche in deiner Stadt, mit Fotos aufgebrochener Türen. Du merkst, dass du dich abends plötzlich unsicher fühlst. Eine Kollegin sagt: „Wenn ständig darüber berichtet wird, muss es ja wirklich häufiger geworden sein.“","options":["Sie schließt aus der Menge der Berichte auf die Häufigkeit der Fälle, obwohl Berichte nur zeigen, was die Redaktion aufgreift; du prüfst deshalb die langfristigen Zahlen für deinen Wohnort.","Sie schließt aus nur drei Tagen Berichterstattung auf eine dauerhafte Entwicklung, die sich in so kurzer Zeit kaum zeigen kann; du wartest deshalb ab, ob die Berichte über mehrere Wochen anhalten.","Sie verlässt sich auf den bloßen Eindruck der Berichte statt auf Zahlen; du zählst deshalb die in den Artikeln genannten Einbrüche zusammen und setzt sie ins Verhältnis zur Einwohnerzahl.","Sie stützt sich auf fremde Berichte statt auf eigenes Erleben; du nimmst deshalb dein Unsicherheitsgefühl am Abend als ersten Anhaltspunkt dafür, wie hoch dein Risiko tatsächlich ist."],"correctIndex":0,"explanation":"Wie viel über ein Thema berichtet wird, sagt zunächst etwas über die Berichterstattung, nicht über die Häufigkeit des Ereignisses selbst. Wiederholung und eindrückliche Bilder machen Fälle im Kopf leicht abrufbar, und was uns leicht einfällt, halten wir gern für häufig oder wahrscheinlich: die Verfügbarkeitsheuristik. Diese Faustregel ist im Alltag oft brauchbar, führt bei statistischen Risiken aber leicht in die Irre; ständige Berichte über Kriminalität können das Gefühl einer gefährlichen Welt erzeugen, selbst wenn die Kriminalitätsstatistiken sinken. Die passende Gegenfrage lautet: Was sagen die langfristigen, nüchternen Zahlen zur tatsächlichen Häufigkeit? Das Unsicherheitsgefühl ist dabei real, ersetzt aber keine Messung.","coreRule":"⚡ Wenn die Nachrichten laut sind, frag die langweilige Statistik.","quote":"Was sagen die langfristigen, langweiligen Statistiken über die tatsächliche Häufigkeit dieses Ereignisses?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.3 (Kontext & Tiefe: Mediale Wiederholung; Das Adaptive Talent; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wie viel berichtet wird, sagt etwas über die Berichterstattung, nicht über die Häufigkeit der Einbrüche. Eindrückliche Bilder machen Fälle im Kopf leicht abrufbar und damit scheinbar häufig; nüchterne Langzeitzahlen für deinen Wohnort zeigen das Risiko.","prueffrage":"Über wie viele Einbrüche wurde in den drei Tagen berichtet, und woran erkennst du, ob das mehr sind als sonst?","rueckmeldung":[{"option":1,"text":"Drei Tage reichen tatsächlich nicht für einen Trend. Aber auch Wochen anhaltender Berichte würden nur zeigen, dass die Redaktion das Thema aufgreift, nicht, dass Einbrüche zunehmen. Dafür braucht es Zahlen statt Abwarten."},{"option":2,"text":"Zahlen statt Eindruck und ein Bezug zur Einwohnerzahl sind der richtige Instinkt. Die in den Artikeln genannten Fälle sind aber selbst eine Auswahl der Redaktion, und ohne den Vergleich mit früheren Jahren sagt die Zahl nichts über eine Zunahme."},{"option":3,"text":"Das Unsicherheitsgefühl ist real, es ist aber gerade das Ergebnis der eindrücklichen Berichte und damit kein unabhängiger Maßstab. Ein Gefühl, das durch Berichte entsteht, ersetzt keine Messung des tatsächlichen Risikos."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Pew Research Center (2016): Voters' perceptions of crime continue to conflict with reality","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2016/11/16/voters-perceptions-of-crime-continue-to-conflict-with-reality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Eintrag „Availability Heuristic“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"99134fef37e6b4ad"}},{"id":"qx-b1-011","clusterId":"B","werkstueckRef":"B.3","stufe":3,"question":"Welche Schlussfolgerung zieht diese Auswertung am besten, ohne mehr in sie hineinzulesen, als sie hergibt?","options":["Das Risiko, im Meer zu ertrinken, und das Risiko im Straßenverkehr sind beide höher als das Risiko, von einem Hai getötet zu werden.","Das Risiko im Straßenverkehr ist höher als das Risiko, im Meer zu ertrinken, deshalb ist die Fahrt zum Strand gefährlicher als das Baden.","Das Hai-Risiko an bewachten Stränden ist gleich null, denn bei 264 Millionen Besuchen starb niemand; Warnungen sind dort überflüssig.","Ertrinken ist am Strand die häufigste Todesursache überhaupt, denn die Auswertung zeigt mehr Ertrunkene als Hai-Opfer."],"correctIndex":0,"explanation":"Bei rund 264 Millionen Strandbesuchen starb niemand durch einen Hai, ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern. Die Bezugsgrößen passen nicht genau zusammen: Die meisten Ertrunkenen starben außerhalb der bewachten Abschnitte, und die Verkehrszahl bezieht sich auf gefahrene Meilen statt auf Strandbesuche. Genau verrechnen lassen sich die Zahlen deshalb nicht; die Rangfolge trägt trotzdem, weil in den Daten kein einziger Hai-Todesfall vorkommt, während Ertrinken und Straßenverkehr messbar Todesopfer fordern. Das Risiko mit dem lebhaftesten Bild ist also nicht das größte. Eine Gefahr zu relativieren heißt aber nicht, sie zu leugnen. Verkehr und Ertrinken haben verschiedene Bezugsgrößen, sodass sich nicht sagen lässt, welches von beiden gefährlicher ist. Kein beobachteter Todesfall ist noch kein Risiko von null, und die Zahlen betreffen ohnehin nur bewachte Strände. Dass mehr Menschen ertrinken als von Haien getötet werden, sagt nichts über alle anderen Todesursachen am Strand.","coreRule":"⚡ Das Risiko mit dem dramatischsten Bild ist selten das mit den meisten Opfern.","beleg":"Werkstück B.3 (Die Angst vor dem Hai); Fn. gl-b-hai-auto (USLA-Daten, Stand Februar 2001; NHTSA 2024, S. 1)","status":"entwurf","scenario":"Nach einem Hai-Angriff in den Nachrichten meiden viele Urlauber das tiefe Wasser. Eine Auswertung von Strandbesuchen in den USA zeigt: Bei rund 264 Millionen Besuchen an bewachten Ozeanstränden starb kein einziger Mensch durch einen Hai. Ertrunken ist dagegen etwa einer von 3,5 Millionen Besuchern, die meisten außerhalb der bewachten Abschnitte. Im US-Straßenverkehr starben 2022 rund 1,33 Menschen je 100 Millionen gefahrene Meilen.","kurz":"Kein Hai-Todesfall bei 264 Millionen Besuchen, aber messbar Ertrunkene und Verkehrstote: Die Rangfolge trägt. Der naheliegende Fehler ist, das Risiko mit dem eindrucksvollsten Bild zu verwechseln, obwohl sich Verkehr und Ertrinken nicht genau verrechnen lassen.","prueffrage":"Wie viele Todesfälle durch Haie nennt die Auswertung, und welche anderen Todesursachen beziffert sie?","rueckmeldung":[{"option":1,"text":"Der Verkehr fordert tatsächlich Todesopfer, ebenso das Ertrinken. Eine Rangfolge der beiden ergibt sich aber nicht, denn die eine Zahl bezieht sich auf gefahrene Meilen, die andere auf Strandbesuche; dazu kommt die unbekannte Länge der Anfahrt."},{"option":2,"text":"Ein sehr kleines Risiko lässt sich so gut belegen. Kein beobachteter Todesfall ist aber kein Beweis für ein Risiko von null, und die Zahlen betreffen nur bewachte Strände. Eine Gefahr zu relativieren heißt nicht, sie zu streichen."},{"option":3,"text":"Dass mehr Menschen ertrinken als von Haien getötet werden, stimmt nach diesen Zahlen. Daraus folgt aber keine Rangfolge unter allen Todesursachen am Strand, denn andere Ursachen kommen in der Auswertung gar nicht vor."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Florida Museum of Natural History, International Shark Attack File: Beach Injuries & Fatalities (Daten USLA, Stand Februar 2001)","oeffentlich":true,"url":"https://www.floridamuseum.ufl.edu/shark-attacks/odds/compare-risk/beach-injuries-fatalities/","abruf":"2026-10-12"},{"typ":"url","kurz":"NHTSA (2024): Overview of Motor Vehicle Traffic Crashes in 2022. DOT HS 813 560","oeffentlich":true,"url":"https://crashstats.nhtsa.dot.gov/Api/Public/ViewPublication/813560","seite":"1","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"4f8e1c91cef29d12"}},{"id":"qx-b1-012","clusterId":"B","werkstueckRef":"B.3","stufe":4,"question":"Warum ist dein Eindruck, dass das Ritual funktioniert, so überzeugend, und was folgt daraus für die Bewertung?","scenario":"Du hast einmal im Stillen „um einen Parkplatz gebeten“ und sofort einen gefunden. Seitdem bist du überzeugt, dass das Ritual funktioniert. Auf Nachfrage räumst du ein, dass es in den allermeisten anderen Fällen nicht geklappt hat, du dich daran aber kaum erinnerst.","options":["Der Treffer ist lebhaft und leicht abrufbar, die Fehlschläge nicht; das Gefühl der Wirksamkeit sagt nichts über die Trefferquote aus.","Der Treffer kam sofort nach der Bitte; ein so enger zeitlicher Abstand spricht für einen Zusammenhang, der weitere Versuche lohnt.","Der Treffer ist selbst erlebt, nicht nur erzählt; eigene Erfahrung wiegt schwerer als Berichte anderer und verdient daher Vertrauen.","Der Treffer zeigt, dass es klappen kann; die Fehlschläge sprechen nur gegen Zuverlässigkeit, nicht gegen eine schwache Wirkung des Rituals."],"correctIndex":0,"explanation":"Ein einzelner Zufallstreffer ist emotional und bildhaft, er fällt dir leicht wieder ein. Die vielen Fehlschläge sind unauffällig und verblassen. Weil uns leicht Abrufbares wichtig und häufig erscheint, entsteht der Eindruck von Wirksamkeit, ohne dass sich an der tatsächlichen Trefferquote etwas ändert. Man erinnert sich lebhaft an den einen Treffer und vergisst die hundert Male, bei denen es nicht funktioniert hat. Beurteilen lässt sich das Ritual deshalb nur an allen Versuchen, nicht an dem Treffer, der dir am lebhaftesten einfällt.","coreRule":"⚡ Bewerte ein Ritual nach allen Versuchen, nicht nach dem Treffer, der dir am lebhaftesten einfällt.","beleg":"Werkstück B.3 (Anwendung & Relevanz: Bei Esoterik & Aberglaube)","status":"entwurf","kurz":"Der eine Treffer bleibt lebhaft im Gedächtnis, die vielen Fehlschläge verblassen. Daraus entsteht der Eindruck von Wirksamkeit, obwohl sich an der Trefferquote nichts ändert; beurteilen lässt sich das Ritual nur an allen Versuchen.","prueffrage":"Wie viele Versuche gab es insgesamt, und bei wie vielen davon klappte es?","rueckmeldung":[{"option":1,"text":"Dass der Treffer direkt auf die Bitte folgte, macht ihn eindrucksvoll. Ein einzelner knapper Abstand belegt aber keinen Zusammenhang, denn Parkplätze werden auch ohne Ritual ständig frei. Entscheidend ist, wie oft es bei allen Versuchen klappt."},{"option":2,"text":"Eigenes Erleben wirkt unmittelbar und überzeugend. Erinnerung ist aber selektiv: Den lebhaften Treffer behältst du, die Fehlschläge nicht. Selbst erlebt oder erzählt, entscheidend ist, ob der Treffer unter allen Versuchen mehr als zufällig auftritt."},{"option":3,"text":"Dass es klappen kann, stimmt, doch das gilt auch ohne Ritual, denn Parkplätze werden von allein frei. Die Fehlschläge sind keine Randnotiz zur Zuverlässigkeit, sondern gehören zur Trefferquote. Wer sie ausklammert, macht das Ritual unwiderlegbar, aber nicht wirksam."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B. H.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Availability Heuristic“, „Misleading Vividness“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Tversky, A.; Kahneman, D. (1974): Judgment under Uncertainty: Heuristics and Biases. Science 185(4157), 1124–1131","oeffentlich":false,"doi":"10.1126/science.185.4157.1124"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"72c2370d92a861f9"}},{"id":"qx-b1-013","clusterId":"B","werkstueckRef":"B.4","stufe":2,"question":"Was ist an deiner Argumentation fehlerhaft?","scenario":"Nach einem Derby sagst du: „Die Fans des anderen Vereins sind doch alle gleich – grölen, pöbeln, werfen mit Bechern.“ Auf den Einwand, dass auch in deiner eigenen Fankurve ein paar Leute Becher werfen, antwortest du: „Ja, aber unsere Leute sind ganz verschieden: Familien, Rentner, Studenten, Ultras. Da kann man nicht pauschal urteilen.“","options":["Du misst mit zweierlei Maß: Die gegnerischen Fans siehst du als gleichförmige Masse, deine eigene Kurve dagegen als Vielfalt einzelner Menschen.","Du verallgemeinerst vorschnell: Vom Verhalten einiger gegnerischer Fans an diesem Derbytag schließt du auf die Anhänger des ganzen Vereins.","Du weichst dem Einwand aus: Statt auf die Becherwerfer in deiner Kurve einzugehen, lenkst du mit der Vielfalt deiner Fans auf etwas anderes.","Du urteilst direkt nach dem Derby als Beteiligter: So kurz nach dem Spiel fällt dein Urteil über die Fans des Rivalen härter aus, als es mit Abstand wäre."],"correctIndex":0,"explanation":"Dieses Muster heißt Outgroup-Homogenität: Wir sehen die Mitglieder einer fremden Gruppe als stereotype, homogene Masse („Die sind doch alle gleich“), die Mitglieder der eigenen Gruppe dagegen als vielfältige, einzigartige Individuen. Genau das passiert in deiner Argumentation: Die gegnerischen Fans fasst du zu einem einheitlichen Typus zusammen, bei deiner eigenen Kurve differenzierst du sofort. Ob dein Urteil trägt, prüfst du mit der Frage: Wie würde ich diese Aussage bewerten, wenn sie von einem Mitglied meiner eigenen Gruppe käme?","coreRule":"⚡ Frag dich bei jeder Gruppe: Würde ich sie auch als „alle gleich“ beschreiben, wenn es meine eigene wäre? Wenn nicht, sprichst du über ein Klischee, nicht über Menschen.","quote":"„Die sind doch alle gleich.“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.4 (Kontext & Tiefe: Outgroup-Homogenität)","status":"entwurf","kurz":"Die Fans des Rivalen siehst du als gleichförmige Masse, deine eigene Kurve sofort als Vielfalt einzelner Menschen. Der Fehler liegt im ungleichen Maß, nicht in einer einzelnen Pauschalisierung oder im Ausweichen.","prueffrage":"Wer steht an einem Spieltag alles in der gegnerischen Kurve?","rueckmeldung":[{"option":1,"text":"Pauschal ist die Aussage, ja. Entscheidend ist aber, dass du bei der eigenen Kurve sofort differenzierst: Erst dieser Kontrast zeigt, dass mit zweierlei Maß gemessen wird."},{"option":2,"text":"Auf den Becherwurf in der eigenen Kurve gehst du nicht direkt ein, das wirkt wie Ausweichen. Du antwortest aber durchaus auf den Einwand und differenzierst, nur eben bei den eigenen Leuten anders als bei den fremden."},{"option":3,"text":"Nähe zum Spiel kann ein Urteil färben. Davon steht im Szenario aber nichts, und auch mit Abstand bliebe das Muster: Die eine Gruppe gilt als einheitlich, die andere als vielfältig."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Castano, E.; Yzerbyt, V. Y. (1998): The highs and lows of group homogeneity. Behavioural Processes 42 (Kopie auf der Seite von V. Yzerbyt, UCLouvain)","oeffentlich":true,"url":"https://perso.uclouvain.be/vincent.yzerbyt/Castano%20&%20Yzerbyt%20BP%201998.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Quattrone, G. A.; Jones, E. E. (1980): The perception of variability within in-groups and out-groups. JPSP 38(1)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d625e954f5369673"}},{"id":"qx-b1-014","clusterId":"B","werkstueckRef":"B.4","stufe":1,"question":"Eine Schlagzeile erklärt das so: „Offenbar waren die Jungen schon vorher voller Vorurteile.“ Wie beurteilst du diese Erklärung im Licht des Ablaufs?","options":["Die Schlagzeile trifft zu: Dass sich beide Gruppen gleich eigene Namen und Flaggen gaben, verrät eine mitgebrachte Neigung zur Abgrenzung.","Die Schlagzeile greift zu kurz: Die Jungen waren vorher unauffällig und einander fremd; die Feindseligkeit kam erst mit dem Wettkampf der Leiter.","Die Schlagzeile trifft zu: Flaggen zu verbrennen und handgreiflich zu werden ist so heftig, dass es nur aus länger gewachsener Abneigung entsteht.","Die Schlagzeile greift zu kurz: Schon die getrennte Unterbringung machte die Gruppen zu Feinden; der Wettkampf brachte das nur noch zum Vorschein."],"correctIndex":1,"explanation":"Die Erklärung „Vorurteile waren schon vorher da“ lässt sich an der zeitlichen Abfolge prüfen: Die Jungen waren vor dem Lager unauffällige Kinder und kannten einander nicht. Erst mit der Gruppenbildung und dem eigens inszenierten Wettkampf entstanden Abwertung, Flaggenverbrennung und Handgreiflichkeiten. Wenn sich ein Verhalten erst einstellt, nachdem die Umstände verändert wurden, liegt die Veränderung der Umstände als Ursache näher als eine verborgene Vorbelastung. Zugleich gilt: Der Wettstreit wurde von den Versuchsleitern gezielt konstruiert, und ein früherer Versuch (1953) scheiterte und wurde abgebrochen; nach Perrys Archivrecherche weigerten sich die Jungen dort, Feindseligkeit gegeneinander zu entwickeln. Das bekannte Lager war der dritte von drei Versuchen. Namen und Flaggen entstanden erst im Lager, als die Gruppen getrennt untergebracht waren; sie gehören zur Gruppenbildung und belegen nichts Mitgebrachtes. Länger gewachsene Abneigung setzt voraus, dass man sich kennt, doch die Gruppen waren einander nie begegnet.","coreRule":"⚡ Passt eine Erklärung nicht zum zeitlichen Ablauf, prüfe zuerst, was sich unmittelbar vor der Wirkung verändert hat – und ob die Situation inszeniert wurde.","beleg":"Werkstück B.4 (Das Ferienlager-Experiment); Fn. gl-b-sherif (Sherif u. a. 1961, S. 18 und 96; Perry 2018)","status":"entwurf","scenario":"Zwei Gruppen unauffälliger elfjähriger Jungen, die sich vorher nie begegnet waren, verbringen Zeit in einem Ferienlager. Zuerst leben sie getrennt voneinander und geben sich eigene Namen und Flaggen. Dann lassen die Versuchsleiter sie in einem eigens entworfenen Wettkampf gegeneinander antreten. Im Verlauf dieses Wettkampfs beleidigen sich die Gruppen, verbrennen gegenseitig ihre Flaggen und werden handgreiflich.","kurz":"Vorher waren die Jungen unauffällig und kannten einander nicht; Abwertung und Gewalt traten erst auf, nachdem die Umstände verändert wurden. Wo ein Verhalten erst nach einer Veränderung auftaucht, liegt diese näher als eine verborgene Vorbelastung.","prueffrage":"Was war mit den Jungen vor dem Lager, und was wurde im Lager erst von außen verändert?","rueckmeldung":[{"option":0,"text":"Eigene Namen und Flaggen wirken wie ein Hang zur Abgrenzung. Sie entstanden aber erst im Lager, nachdem die Gruppen getrennt untergebracht waren, und gehören damit zur Gruppenbildung, nicht zu etwas Mitgebrachtem."},{"option":2,"text":"Wie heftig die Gewalt war, beeindruckt, sagt aber nichts über ihre Herkunft. Gewachsene Abneigung setzt voraus, dass man sich kennt, und die Gruppen waren einander vorher nie begegnet."},{"option":3,"text":"Richtig ist, dass die Schlagzeile zu kurz greift und die Gruppenbildung zum Ablauf gehört. Feindschaft entstand laut Ablauf aber erst im Wettkampf, nicht schon durch die getrennte Unterbringung allein."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): Intergroup Conflict and Cooperation: The Robbers Cave Experiment, Vorwort 1954 (Classics in the History of Psychology, York University)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/preface1954.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Sherif, M. u. a. (1954/1961): The Robbers Cave Experiment, Kap. 3: Role of Staff, Subject Selection, Experimental Site (Classics in the History of Psychology)","oeffentlich":true,"url":"https://psychclassics.yorku.ca/Sherif/chap3.htm","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Perry, G. (2018): The Lost Boys: Inside Muzafer Sherif's Robbers Cave Experiment. Melbourne: Scribe","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0266c6518d5e6e11"}},{"id":"qx-b1-015","clusterId":"B","werkstueckRef":"B.4","stufe":3,"question":"Wie beurteilst du die Lage und die Behauptung des Stadtrats am besten?","options":["Kein Grund zur Sorge: Die Fans zeigten bisher kaum Abneigung, also bleibt ihre Vorliebe harmlos, auch wenn Aufstiegskampf und Rundmails hinzukommen.","Der Stadtrat hat recht: Schon dass die Fans bevorzugt bei Sponsoren des eigenen Vereins kaufen, ist eine Abwertung des anderen, die auf Gelegenheit wartet.","Grund zur Sorge erst später: Rundmails sind nur Worte; solange die Fans nicht feindselig handeln, ist aus ihrer Vorliebe noch keine Abneigung geworden.","Grund zur Sorge jetzt: Die Vorliebe bestand bisher ohne Abneigung; kippen kann sie durch den Kampf um denselben Platz und die Rundmails des Vorsitzenden."],"correctIndex":3,"explanation":"Der Stadtrat setzt zwei Dinge gleich, die sich trennen lassen: Bevorzugung der eigenen Gruppe und Abwertung der fremden. Die Forschung (Brewer 1999) zeigt, dass Benachteiligung anderer allein aus der Vorliebe für die eigene Gruppe entstehen kann, ohne negative Gefühle oder feindselige Absicht gegenüber den anderen. Genau das zeigt die Umfrage: Die Fans bevorzugen ihren Verein, ohne den anderen abzulehnen. Wer „automatisch“ sagt, behauptet eine Notwendigkeit, wo es nur eine Möglichkeit gibt, und dagegen genügt ein einziges Gegenbeispiel. In Feindschaft kippt die Bindung erst unter zusätzlichen Bedingungen: wahrgenommene Bedrohung, Konkurrenz oder gezielte Aufhetzung durch Anführer. Mit dem Kampf um denselben Aufstiegsplatz und den Rundmails, die eine Bedrohung behaupten, kommen solche Bedingungen jetzt hinzu. Entwarnung übersieht deshalb, dass sich die Umstände gerade ändern. Der Einkauf bei den eigenen Sponsoren ist Bevorzugung, keine Abwertung.","coreRule":"⚡ Gruppenliebe ist nicht dasselbe wie Fremdenhass; sie kippt unter Bedrohung, Konkurrenz und Aufhetzung. Wer „zwangsläufig“ behauptet, muss zeigen, dass es keine Ausnahme gibt.","beleg":"Werkstück B.4 (Das Adaptive Talent); Fn. gl-b-brewer-kipp (Brewer 1999, Journal of Social Issues 55(3), S. 431, 434–438)","status":"entwurf","scenario":"In einer Kleinstadt gibt es zwei Fußballvereine. Eine Umfrage unter den Fans des einen zeigt: Sie halten ihren Verein für den besseren und kaufen bevorzugt bei seinen Sponsoren, Abneigung gegen den anderen Verein oder dessen Fans äußert aber kaum jemand. In der neuen Saison kämpfen beide Vereine erstmals um denselben Aufstiegsplatz, und der Vorsitzende des Fanclubs schreibt in Rundmails, die anderen wollten „uns alles wegnehmen“. Ein Stadtrat meint: „Wer seinen Verein liebt, hasst die anderen automatisch; Liebe zur eigenen Gruppe und Hass auf die fremde sind dasselbe.“","kurz":"Die Umfrage zeigt Vorliebe ohne Abneigung, also sind beide nicht dasselbe. Doch Konkurrenz um denselben Platz und Rundmails, die eine Bedrohung behaupten, können die Vorliebe in Feindschaft kippen lassen.","prueffrage":"Was äußern die befragten Fans tatsächlich über den anderen Verein, und was hat sich seitdem in der Lage verändert?","rueckmeldung":[{"option":0,"text":"Dass bisher kaum Abneigung geäußert wird, stimmt laut Umfrage. Daraus folgt aber nicht, dass es so bleibt: Mit Aufstiegskampf und Rundmails kommen gerade Umstände hinzu, unter denen Vorliebe in Abneigung kippen kann."},{"option":1,"text":"Dass Vorliebe in Abwertung umschlagen kann, ist richtig. Der Einkauf bei den eigenen Sponsoren ist aber Bevorzugung, keine Abwertung, und genau die Umfrage zeigt Vorliebe ohne Abneigung. Der Stadtrat macht aus einer Möglichkeit ein „automatisch“."},{"option":2,"text":"Dass Worte noch keine feindseligen Taten sind, stimmt. Das Abwarten übersieht aber, dass die Rundmails eine Bedrohung behaupten und mit dem Kampf um denselben Platz Bedingungen schaffen, unter denen die Vorliebe kippen kann. Dann wäre Warten zu spät."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3) (inoffizielle Kopie auf Server des Bard College)","oeffentlich":true,"url":"https://bcsh.bard.edu/files/2019/06/Brewer-ingroup-love-or-outgroup-hate.pdf","seite":"431, 434–437","abruf":"2026-10-12"},{"typ":"doi","kurz":"Brewer, M. B. (1999): The Psychology of Prejudice: Ingroup Love or Outgroup Hate? Journal of Social Issues 55(3), Verlagsfassung","oeffentlich":false,"doi":"10.1111/0022-4537.00126"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8f2c3f370867ae6b"}},{"id":"qx-b1-016","clusterId":"B","werkstueckRef":"B.4","stufe":4,"question":"Welche Prüffrage setzt am Kern dieses Musters an?","scenario":"Ein Skandal in der Partei, die du wählst, ist für dich eine „Kampagne der Gegner“. Derselbe Skandal bei der anderen Partei ist für dich ein Beweis ihrer moralischen Verkommenheit.","options":["Welche der beiden Parteien hat in den vergangenen Jahren mehr solcher Skandale gehabt, und wie schwer wogen sie jeweils?","Wie verlässlich sind die Medien, die über beide Skandale berichten, und welche der beiden Parteien behandeln sie schonender?","Gibt es für den Vorwurf im jeweiligen Skandal belastbare Belege, und lässt er sich unabhängig von beiden Parteien überprüfen?","Würde ich denselben Vorgang genauso bewerten, wenn die Rollen vertauscht wären und er bei der anderen Partei geschehen wäre?"],"correctIndex":3,"explanation":"Das Muster ist ein doppelter Maßstab: Derselbe Vorgang gilt als „Kampagne“, wenn er die eigene Seite trifft, und als Beweis für „moralische Verkommenheit“, wenn er die andere trifft. Dahinter steckt die Gruppenzugehörigkeits-Verzerrung: Statt zu fragen, ob etwas wahr ist, fragt man, ob es der eigenen Seite nützt. Am Kern setzt an, wer seinen Maßstab auf die Probe stellt, indem er sich vorstellt, derselbe Vorgang geschehe bei der anderen Partei, und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Asymmetrie in der Bewertung und nicht im Vorgang. Die anderen Fragen sind für sich sinnvoll, passen aber nicht zu diesem Muster: Ein Vergleich der Skandalbilanz klärt Fakten, ändert aber nichts daran, dass derselbe Vorgang je nach Lager unterschiedlich gewogen wird. Auch die Medienlage zu prüfen betrifft die Berichterstattung und nicht das eigene Urteil. Und selbst wenn ein Vorwurf belegt ist, bleibt offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt.","coreRule":"⚡ Vertausche die Rollen: Gilt mein Maßstab auch, wenn es um meine eigene Seite geht?","quote":"Ist das gut für uns oder für die?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.4 (Anwendung & Relevanz: Bei politischer Polarisierung; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Hier wird mit zweierlei Maß gemessen: Derselbe Vorgang gilt als Kampagne oder als Beweis, je nachdem, wen er trifft. Das zeigt sich, wenn man die Rollen vertauscht und prüft, ob das Urteil gleich bliebe. Fällt es anders aus, liegt die Schieflage im Urteil.","prueffrage":"Worin unterscheiden sich die beiden Skandale in der Sache, abgesehen davon, welche Partei betroffen ist?","rueckmeldung":[{"option":0,"text":"Ein Vergleich der Skandale klärt Fakten und ist für sich sinnvoll. Er erklärt aber nicht, warum derselbe Vorgang je nach Lager einmal als Kampagne und einmal als Beweis gilt. Die Schieflage im Urteil bleibt bestehen."},{"option":1,"text":"Die Verlässlichkeit der Medien zu prüfen ist grundsätzlich klug. Sie betrifft aber die Berichterstattung und nicht dein eigenes Urteil. Das Muster entsteht auch bei sauberer Berichterstattung, wenn der Maßstab je nach Lager wechselt."},{"option":2,"text":"Belege und unabhängige Überprüfbarkeit sind wichtig, damit prüfst du aber den Vorwurf. Selbst bei einem klar belegten Vorwurf bliebe offen, warum er bei der eigenen Partei als Kampagne und bei der anderen als Beweis gilt."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Ditto, P. H. u. a. (2019): At Least Bias Is Bipartisan. Perspectives on Psychological Science 14(2) (Kopie auf der Seite des Ditto-Labors, UC Irvine)","oeffentlich":true,"url":"https://sites.uci.edu/peterdittolab/files/2018/06/Ditto-et-al.-2018-At-Least-Bias-is-Bipartisan-A-Meta-Analytic-Comparison-of-Partisan-Bias-in-Liberals-Conservatives.pdf","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"defc9471b9f06fc4"}},{"id":"qx-b1-017","clusterId":"B","werkstueckRef":"B.5","stufe":1,"question":"Eine Wirtschaftsjournalistin sagt: „Dass die Firma so erfolgreich wurde, ist doch klar: Der Gründer war ein Visionär, jede seiner Entscheidungen führte zwangsläufig zum Erfolg. Man sieht es an seiner Biografie.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Sie verwechselt die im Rückblick stimmige Erzählung vom Garagengründer mit einer Erklärung, die den Erfolg schon vorher verlässlich vorhergesagt hätte.","Sie schreibt den Erfolg der ganzen Firma allein der Person des Gründers zu und übersieht, welchen Anteil andere Menschen daran gehabt haben dürften.","Sie übertreibt nur mit dem Wort „zwangsläufig“, denn auch kluge Entscheidungen führen nicht sicher zum Erfolg; dass er ein Visionär war, zeigt seine Biografie.","Sie erklärt den Erfolg mit dem dehnbaren Wort „Visionär“, das wenig Bestimmtes besagt, sodass sich ihre Erklärung weder prüfen noch widerlegen lässt."],"correctIndex":0,"explanation":"Im Rückblick lassen sich unzusammenhängende Ereignisse leicht zu einer stimmigen Ursache-Wirkungs-Geschichte verbinden, die zwingend wirkt, weil man das Ergebnis schon kennt. Vorher hätte sie aber niemand verlässlich erzählen können: Zufall, Glück, Timing und Konkurrenten mit ähnlichen Ideen, die nur Pech hatten, fehlen in der glatten Erzählung. Eine gute Erklärung im Nachhinein ist deshalb noch keine gute Vorhersage. Der Test: Welche unzusammenhängenden Fakten bleiben übrig, wenn du die erzählerischen Verbindungslinien weglässt?","coreRule":"⚡ Eine glatte Geschichte im Rückblick ist noch keine Vorhersage.","beleg":"Werkstück B.5 (Kernidee; Kontext & Tiefe; Die Legende des Star-CEOs; Anti-Denkmuster)","status":"entwurf","scenario":"Ein Zeitschriftenporträt über den Gründer eines Tech-Konzerns erzählt eine runde Geschichte: der rebellische College-Abbrecher, die Garage, der Kampf gegen die trägen Riesen. Jede Entscheidung erscheint im Rückblick wie ein kluger, folgerichtiger Schritt zum Gipfel.","kurz":"Im Rückblick wirkt jede Entscheidung folgerichtig, weil das Ergebnis schon bekannt ist. Vorab hätte das niemand verlässlich erzählen können: Zufall, Timing und Konkurrenten mit ähnlichen Ideen fehlen in der glatten Geschichte. Gute Nacherzählung ist noch keine Vorhersage.","prueffrage":"Welche Entscheidungen des Gründers hätten genauso gut schiefgehen können?","rueckmeldung":[{"option":1,"text":"Dass an einem Konzern viele Menschen mitwirken, ist realistisch. Der Schluss der Journalistin krankt aber woanders: Auch eine Erzählung, die nur den Gründer zeigt, würde nicht dadurch tragfähig, dass man weitere Personen ergänzt, solange Zufall und Timing fehlen."},{"option":2,"text":"Daran stimmt: Auch kluge Entscheidungen führen nicht sicher zum Erfolg, „zwangsläufig“ ist also übertrieben. Doch der Fehler liegt tiefer: Gerade die glatte Biografie kann „Visionär“ nicht belegen, weil man den Ausgang schon kennt und danach passend erzählt."},{"option":3,"text":"Ein dehnbares Wort wie „Visionär“ erschwert tatsächlich jede Prüfung. Das ist aber ein anderer Denkfehler. Selbst mit klar definiertem Begriff bliebe das Problem, dass die Rückschau einzelne Ereignisse zu einer scheinbar zwingenden Geschichte verbindet."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Roese, N. J.; Vohs, K. D. (2012): Hindsight Bias. Perspectives on Psychological Science 7(5)","oeffentlich":false,"doi":"10.1177/1745691612454303"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"441b204793c3c3cd"}},{"id":"qx-b1-018","clusterId":"B","werkstueckRef":"B.5","stufe":2,"question":"Welche Prüfung hilft am besten, um zu klären, ob die Reportage mehr ist als eine gute Geschichte?","scenario":"Du liest eine Reportage über den Aufstieg einer Firma: klar, spannend, jede Wendung begründet. Du willst prüfen, ob die Erzählung die Fakten trägt oder nur gut klingt.","options":["Die Verbindungen zwischen den Wendungen gedanklich löschen und fragen, welche Einzelfakten bleiben und welche Rolle Zufall und Glück spielten.","Die Interessen der Autorin klären, etwa ob die Firma die Reportage bezahlt hat, und die geschilderten Wendungen danach entsprechend vorsichtig bewerten.","Die Wendungen nacheinander auf innere Widersprüche durchsehen und fragen, ob eine behauptete Ursache an anderer Stelle der Reportage widerlegt wird.","Die Wendungen einer Person ohne Branchenwissen erklären und fragen, ob sie jede Ursache für den Aufstieg nachvollziehen und begründen kann."],"correctIndex":0,"explanation":"Eine kohärente Erzählung entsteht oft erst im Rückblick: Das Gehirn verbindet Einzelereignisse zu einer Ursache-Wirkungs-Kette und blendet Zufall, Glück und gescheiterte Konkurrenz aus. Wer die Verbindungslinien gedanklich entfernt, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt. Die anderen Prüfungen klingen vernünftig, treffen aber nicht den Punkt: Die Interessen der Autorin zu klären ist sinnvoll, sagt aber nichts darüber, ob die Ursachenkette trägt. Dass die Reportage keine Widersprüche enthält, gehört zu einer gut gebauten Geschichte und belegt nicht, dass sie wahr ist. Und dass auch Leser ohne Branchenwissen jede Ursache nachvollziehen können, spricht für gutes Erzählen und nicht für Wahrheit: Eine Geschichte kann klar sein und trotzdem Zufall und Glück ausblenden.","coreRule":"⚡ Streich die Verbindungslinien und sieh nach, welche Fakten übrig bleiben.","beleg":"Werkstück B.5 (Das Anti-Denkmuster; Werkbank-Frage)","status":"entwurf","kurz":"Gerade die glatte Verknüpfung der Wendungen entsteht oft erst im Rückblick und blendet Zufall und Glück aus. Wer die Verbindungen gedanklich streicht, sieht, welche belegbaren Fakten übrig bleiben und wo die Geschichte nur Lücken füllt.","prueffrage":"Woher stammen die einzelnen Angaben der Reportage, und wo ließen sie sich unabhängig von ihr nachprüfen?","rueckmeldung":[{"option":1,"text":"Zu wissen, wer hinter einem Text steht, ist sinnvoll. Es sagt aber nichts darüber, ob die Ursachenkette trägt: Auch eine bezahlte Reportage kann stimmen, eine unabhängige kann trotzdem nur gut klingen."},{"option":2,"text":"Eine Geschichte ohne innere Widersprüche wirkt solide. Widerspruchsfreiheit gehört aber zu einer gut gebauten Erzählung und belegt nicht, dass sie wahr ist; Zufall und Glück bleiben auch dann unsichtbar."},{"option":3,"text":"Wenn Laien jede Ursache nachvollziehen können, ist die Reportage gut erzählt. Das sagt aber nichts über die Fakten: Eine klare Geschichte kann Zufall und Glück trotzdem ausblenden."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"936eace452d13680"}},{"id":"qx-b1-019","clusterId":"B","werkstueckRef":"B.5","stufe":4,"question":"Nach einem Börsencrash behauptet ein Bekannter: „Das war von langer Hand geplant. Eine kleine Gruppe von Großinvestoren hat gezielt auf den Absturz gewettet und alle anderen ins Verderben geschickt.“ Er hat viele Details parat, die zusammen eine stimmige Geschichte ergeben. Was ist an seiner Argumentation das Kernproblem?","options":["Sie macht aus Zufall, Fehlern und vielen Einzelentscheidungen eine runde Geschichte mit Bösewicht und Plan; dass sie stimmig klingt, belegt nicht ihre Wahrheit.","Sie hat eher keines: Je mehr Einzelheiten zusammen ein stimmiges Bild ergeben, desto eher spricht das für gründliche Recherche statt für eine ausgedachte Geschichte.","Sie schließt aus Wetten auf fallende Kurse, dass die Wettenden den Absturz auch herbeigeführt haben, obwohl am Absturz zu verdienen nicht heißt, ihn verursacht zu haben.","Sie deutet den Crash erst im Rückblick, wenn der Ausgang feststeht, und hält ihn deshalb für planbarer und vorhersehbarer, als er vor dem Absturz tatsächlich war."],"correctIndex":0,"explanation":"Große, chaotische Ereignisse wie Wirtschaftskrisen, Pandemien oder Kriege entstehen meist aus einer Mischung von Inkompetenz, Zufall und systemischen Kräften. Die Behauptung macht daraus eine runde Geschichte mit einem allmächtigen Bösewicht, einem geheimen Plan und einem klaren Gut-Böse-Schema. Solche Geschichten sind psychologisch befriedigender als die komplizierte Realität, und genau deshalb wirken sie überzeugend. Dass die Erzählung stimmig klingt, sagt aber nichts darüber, ob sie wahr ist: Der Erzählfehler macht die Qualität der Geschichte zum Maßstab ihrer Glaubwürdigkeit statt die Qualität der Fakten. Prüfen lässt sich die Behauptung nur anhand der harten Einzelfakten, die übrig bleiben, wenn man die Verbindungslinien der Erzählung wegdenkt.","coreRule":"⚡ Je runder die Geschichte, desto genauer solltest du nach Zufall und banaler Erklärung fragen.","beleg":"Werkstück B.5 (Anwendung & Relevanz: Bei Verschwörungsmythen; Anti-Denkmuster: Aktivierungs-Frage)","status":"entwurf","scenario":"","kurz":"Der Bekannte macht aus Zufall, Fehlern und vielen Einzelentscheidungen eine runde Geschichte mit Plan und Bösewicht. Dass sie stimmig klingt, belegt nicht, dass sie stimmt; geprüft werden können nur die einzelnen Fakten.","prueffrage":"Welche der vielen Details lassen sich einzeln belegen, wenn du die Verbindungen dazwischen weglässt?","rueckmeldung":[{"option":1,"text":"Viele Details zeigen zwar Fleiß beim Sammeln. Ob sie zusammenpassen, ist aber etwas anderes als ob jedes einzelne stimmt, und eine Geschichte lässt sich auch aus lauter echten Details zu einer falschen Gesamtdeutung formen."},{"option":2,"text":"Wer an fallenden Kursen verdient, hat den Fall nicht automatisch verursacht, das stimmt. Das ist aber nur ein Einzelschluss. Das Kernproblem liegt weiter vorn: Aus Zufall und vielen Entscheidungen entsteht eine Geschichte mit Plan und Bösewicht."},{"option":3,"text":"Im Nachhinein wirken Ereignisse oft vorhersehbarer, als sie waren. Der Bekannte behauptet aber mehr: nicht, dass man es hätte wissen können, sondern dass jemand den Absturz geplant und herbeigeführt hat."}],"familie":"deutung-von-fakten-trennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Douglas, K. M.; Sutton, R. M.; Cichocka, A. (2017): The Psychology of Conspiracy Theories. Current Directions in Psychological Science 26(6) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5724570/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Taleb, N. N. (2007): The Black Swan: The Impact of the Highly Improbable. New York: Random House","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"ecce0125584df2ca"}},{"id":"qx-b1-020","clusterId":"B","werkstueckRef":"B.6","stufe":1,"question":"Was ist an Jonas' Überlegung fehlerhaft?","options":["Er rechnet die 3.000 Euro, die nicht mehr zurückzuholen sind, in eine Entscheidung ein, die nur von künftigen Kosten und Nutzen abhängen sollte.","Er übersieht, dass er mit der Reparatur insgesamt 4.800 Euro für ein Motorrad ausgäbe, für das es ein zuverlässiges Gegenstück schon für 2.500 Euro gibt.","Er denkt im Grunde richtig, denn wer jetzt aufgibt, macht den Verlust der 3.000 Euro endgültig, während eine Reparatur die Chance lässt, ihn wettzumachen.","Er zieht den falschen Schluss: Gerade weil schon 3.000 Euro verloren sind, sollte er kein weiteres Geld hinterherwerfen und das Motorrad besser aufgeben."],"correctIndex":0,"explanation":"Die 3.000 Euro sind weg, egal ob Jonas weiterrepariert oder aufgibt; sie verändern keine der beiden Möglichkeiten. Vernünftig ist ein Vergleich dessen, was noch kommt: weitere 1.800 Euro für ein Motorrad mit unsicherem Zustand gegen 2.500 Euro für ein zuverlässiges, abzüglich dessen, was das alte beim Verkauf noch einbringt. Dieser Vergleich kann durchaus für die Reparatur ausgehen; fehlerhaft ist die Begründung, denn wer die Vergangenheit mitrechnet, weil sonst alles „umsonst“ gewesen wäre, hält leicht an einer schlechten Investition fest. Diese Falle heißt Versunkene-Kosten-Falle (Sunk Cost Fallacy). Eine hilfreiche Prüffrage: Würdest du das Motorrad in diesem Zustand heute zu diesem Preis neu kaufen?","coreRule":"⚡ Entscheide nach dem, was kommt, nicht nach dem, was schon weg ist.","beleg":"Werkstück B.6 (Kernidee; Kontext & Tiefe); Fn. gl-b-sunk-cost (Arkes/Blumer 1985, OBHDP 35(1), S. 124)","status":"entwurf","scenario":"Jonas hat vor einem Jahr 3.000 Euro in ein gebrauchtes Motorrad gesteckt. Seitdem war er viermal in der Werkstatt, der Motor macht weiter Probleme, und der Mechaniker schätzt die nächste Reparatur auf weitere 1.800 Euro. Ein vergleichbares, zuverlässiges Motorrad gäbe es für 2.500 Euro. Jonas sagt: „Ich habe schon 3.000 Euro hineingesteckt. Wenn ich jetzt aufgebe, war das alles umsonst. Ich repariere weiter.“","quote":"","quoteLabel":"","kurz":"Die 3.000 Euro sind weg, egal wie Jonas entscheidet, und dürfen die Wahl nicht lenken. Maßgeblich ist nur, was künftig kostet und nützt. Wer weitermacht, damit das Bisherige nicht „umsonst“ war, hält leicht an Schlechtem fest.","prueffrage":"Was spricht nach vier Werkstattbesuchen dafür, dass die nächste Reparatur die letzte ist?","rueckmeldung":[{"option":1,"text":"Die Summe von 4.800 Euro wirkt wie ein klarer Preisvergleich. Sie enthält aber die 3.000 Euro, die in beiden Fällen schon ausgegeben sind. Verglichen werden müssten nur die künftigen Posten, und dieser Vergleich kann trotzdem für die Reparatur ausgehen."},{"option":2,"text":"Der Gedanke, einen Verlust nicht „endgültig“ werden zu lassen, hat Gewicht. Die 3.000 Euro sind aber auch bei einer Reparatur nicht zurückgeholt: Sie sind in beiden Fällen weg, und Weiterreparieren gleicht sie nicht aus. Wer so rechnet, hält leicht an einer schlechten Investition fest."},{"option":3,"text":"Hier wird die Vergangenheit nur mit umgekehrtem Vorzeichen zum Maßstab gemacht. Die früheren 3.000 Euro sprechen weder fürs Weitermachen noch fürs Aufgeben. Entscheidend sind die künftigen Kosten, und der Vergleich kann auch für die Reparatur ausfallen."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"35b812d6822c4ba3"}},{"id":"qx-b1-021","clusterId":"B","werkstueckRef":"B.6","stufe":2,"question":"Welche Prüffrage setzt genau am Fehler in der Begründung der Leitung an?","scenario":"In deiner Firma läuft seit vier Jahren ein Softwareprojekt, das nach Einschätzung des Teams nie fertig wird. In der Sitzung sagt die Leitung: „Wir haben schon so viel investiert – jetzt aufzugeben wäre Verschwendung.“ Du darfst eine einzige Prüffrage stellen.","options":["„Wie viel haben wir in den vier Jahren tatsächlich investiert, und ist es wirklich so viel, wie die Leitung meint?“","„Würden wir dieses Projekt heute, im jetzigen Zustand und mit dem heutigen Wissen, noch einmal beginnen?“","„Wie viel müssten wir noch hineinstecken, damit sich die bisherigen vier Jahre am Ende doch noch auszahlen?“","„Wäre ein Abbruch wirklich Verschwendung, wenn wir die vier Jahre als lehrreiche Erfahrung verbuchen können?“"],"correctIndex":1,"explanation":"Der Fehler liegt darin, dass bereits ausgegebenes Geld und vergangene Mühe zum Grund für die Fortsetzung gemacht werden. Diese Kosten sind unwiederbringlich weg, egal ob das Projekt weiterläuft oder nicht; für die Entscheidung zählen nur künftige Kosten und künftiger Nutzen. Die Frage, ob man das Vorhaben heute im jetzigen Zustand neu beginnen würde, blendet die Vergangenheit aus und zwingt dazu, nur die Zukunft zu bewerten.","coreRule":"⚡ Frag nicht, wie viel du schon investiert hast, sondern ob du heute noch einsteigen würdest.","quote":"Würde ich einsteigen?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.6 (Das Anti-Denkmuster; Verbindungen: Null-Basis-Check A.14)","status":"entwurf","kurz":"Entscheidend ist, was ab jetzt noch kosten und nutzen wird. Die vier Jahre sind unwiederbringlich weg, egal ob das Projekt weiterläuft. Der Denkfehler: Die Leitung macht Vergangenes zum Grund für die Fortsetzung.","prueffrage":"Welchen Grund nennt die Leitung in der Sitzung dafür, das Projekt weiterzuführen?","rueckmeldung":[{"option":0,"text":"Die genaue Summe zu kennen ist sinnvoll. Der Fehler liegt aber nicht in der Höhe: Auch eine korrekt bezifferte Investition ist ausgegeben und wäre kein Grund, weiterzumachen. Die Frage bleibt in der Vergangenheit."},{"option":2,"text":"Der Blick auf künftige Kosten ist richtig. Gemessen wird hier aber daran, ob sich die vier Jahre noch auszahlen, und das bindet die Entscheidung weiter an Vergangenes. Es zählen künftige Kosten und künftiger Nutzen für sich."},{"option":3,"text":"Die Erfahrung der vier Jahre mag wertvoll sein. Das ändert aber nichts an der Logik der Leitung: Die Vergangenheit bleibt Maßstab, ob das Projekt künftig etwas taugt, wird nicht geprüft."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"fced6d31ecf90370"}},{"id":"qx-b1-022","clusterId":"B","werkstueckRef":"B.6","stufe":3,"question":"Welche Beobachtung zeigt am deutlichsten, dass aus gesunder Ausdauer irrationale Sturheit geworden ist?","options":["Die Gründerin macht weiter, obwohl der Markttest eindeutig negativ ausfiel, und verweist auf die zwei Jahre, die sie schon investiert hat.","Der Doktorand wiederholt sein Experiment, obwohl der erste Versuch ein Jahr Arbeit kostete und scheiterte, und verweist auf den gefundenen Messfehler.","Der Mann hält an der Fernbeziehung fest, obwohl der Alltag nach Jahren des Pendelns anstrengend bleibt, und verweist auf den vereinbarten Umzug.","Die Frau behält ihre Aktien, obwohl der Kurs im letzten Monat fiel und sie im Minus liegt, und verweist auf die unveränderten Geschäftszahlen."],"correctIndex":0,"explanation":"Ausdauer ist oft nötig und nützlich: Wer nach dem ersten Rückschlag aufgibt, erreicht langfristige Ziele nie. Der Kipppunkt zur Sturheit liegt dort, wo neue, negative Informationen ignoriert werden, um die ursprüngliche Entscheidung zu schützen. Entscheidend ist also, wie jemand mit neuer Information umgeht und wonach er seine Entscheidung begründet. Nur die Gründerin stützt sich auf bereits Investiertes und übergeht die eindeutig negative Information. Die zwei Jahre sind unwiederbringlich verloren, gleich wie sie sich entscheidet, und dürfen deshalb die Entscheidung über die Zukunft nicht lenken. Prüffrage: Würde ich heute, mit dem aktuellen Wissen, noch einmal einsteigen?","coreRule":"⚡ Ausdauer hält durch, trotz Schwierigkeiten – Sturheit hält fest, trotz Gegenbeweisen.","beleg":"Werkstück B.6 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","scenario":"Vier Menschen halten an einem Vorhaben fest, das nicht richtig läuft: eine Gründerin mit ihrem Start-up, ein Doktorand mit seinem Experiment, ein Mann mit seiner Fernbeziehung und eine Frau mit ihrer Aktienposition.","kurz":"Entscheidend ist, wonach jemand sich richtet: Die gescheiterte Gründerin beruft sich auf bereits investierte Jahre und übergeht ein eindeutig negatives Ergebnis. Diese Jahre sind verloren, so oder so, und dürfen die Entscheidung über die Zukunft nicht lenken.","prueffrage":"Worauf stützt sich jede der vier Personen, wenn sie begründet, warum sie weitermacht?","rueckmeldung":[{"option":1,"text":"Ein Jahr verlorene Arbeit und ein gescheiterter Versuch lassen an Sturheit denken. Der Doktorand nennt aber einen konkreten Messfehler, den er beim nächsten Versuch ausschließen kann; sein Grund zeigt also nach vorn."},{"option":2,"text":"Jahre des Pendelns und ein weiterhin anstrengender Alltag wirken wie ein Zeichen für Sturheit. Der vereinbarte Umzug ist jedoch ein Grund, der in die Zukunft weist und den Alltag ändern wird; Anstrengung allein zeigt noch nichts."},{"option":3,"text":"Ein gefallener Kurs und ein Minus klingen nach einem Fehler, an dem man nicht festhalten sollte. Ein Verlust auf dem Papier sagt aber wenig, und die Frau stützt sich auf unveränderte Geschäftszahlen, also auf einen Grund für die Zukunft."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"70f5a8d617144fac"}},{"id":"qx-b1-023","clusterId":"B","werkstueckRef":"B.6","stufe":4,"question":"Welche Rückfrage der Freundin würde ihr am besten helfen, ihre Entscheidung neu zu prüfen?","scenario":"Eine Frau engagiert sich seit zehn Jahren in einer Gemeinschaft, die eine bestimmte Lehre vertritt. Inzwischen hat sie ernste Zweifel an deren Aussagen. Eine Freundin fragt sie, warum sie trotzdem bleibt. Sie antwortet: „Ich habe zehn Jahre, meine Freundschaften und mein Geld hineingesteckt. Wenn ich jetzt gehe, war das alles umsonst.“","options":["„Würdest du heute, so wie du die Lehre jetzt einschätzt, neu einsteigen?“","„Wie viel Geld und Zeit hast du investiert, und was davon ist noch zu retten?“","„Wann sind deine Zweifel zum ersten Mal aufgekommen, und was hat sie ausgelöst?“","„Gab es in den zehn Jahren auch gute Momente, und was haben sie dir bedeutet?“"],"correctIndex":0,"explanation":"Die zehn Jahre und das Geld sind ausgegeben und kommen nicht zurück, egal ob sie bleibt oder geht; solche versunkenen Kosten sollten die künftige Entscheidung nicht lenken. Zählen darf, was von nun an für oder gegen das Bleiben spricht, und dazu gehört auch, welche Freundschaften ein Austritt gefährden würde; über die Lehre selbst sagt aber auch das nichts. Die Frage nach dem Neueinstieg richtet den Blick genau darauf und zwingt, die Lehre so zu bewerten, wie sie heute dasteht. Genau diese Bindung ans Investierte hält Menschen oft in Kulten und Glaubenssystemen fest, selbst wenn Zweifel aufkommen. Den Aufwand zu überblicken ist verständlich, doch das Investierte lässt sich nicht zurückholen und ändert nichts an der künftigen Lage. Zu wissen, wann die Zweifel begannen, kann beim Verstehen helfen, prüft aber die Lehre nicht. Und die guten Momente gehören zur Vergangenheit, sie sagen nichts darüber, was die Lehre heute wert ist.","coreRule":"⚡ Bereits Verlorenes darf die Entscheidung nicht lenken: Frag, ob du heute noch einsteigen würdest.","beleg":"Werkstück B.6 (Anwendung & Relevanz: Bei irrationalen Glaubenssystemen; Kontext & Tiefe)","status":"entwurf","kurz":"Die zehn Jahre und das Geld sind weg, egal ob sie bleibt oder geht, und sollten daher nicht lenken. Die Frage nach dem Neueinstieg bewertet die Lehre so, wie sie heute dasteht, und löst damit die Bindung ans Investierte.","prueffrage":"Was genau an den Aussagen der Gemeinschaft bezweifelt sie, und seit wann?","rueckmeldung":[{"option":1,"text":"Sich den Aufwand klarzumachen ist verständlich und wirkt wie eine nüchterne Bilanz. Zurückholen lässt sich davon aber nichts, und für das Weitere ändert es nichts. Wer fragt, was noch zu retten ist, hält den Blick auf der Vergangenheit."},{"option":2,"text":"Zu wissen, wann und wodurch die Zweifel begannen, kann helfen, sie zu verstehen. Ob die Lehre heute trägt, prüft das jedoch nicht, denn es beleuchtet nur, wie die Zweifel entstanden sind."},{"option":3,"text":"Gute Erfahrungen zählen für ihr Leben durchaus. Sie liegen aber hinter ihr und sagen nichts darüber, was die Lehre heute wert ist. Genau das müsste sie für ihre Entscheidung klären."}],"familie":"versunkene-kosten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Arkes, H. R.; Blumer, C. (1985): The Psychology of Sunk Cost (inoffizielle Kopie, Universität Klagenfurt)","oeffentlich":true,"url":"https://cognition.aau.at/bg/BA/Arkes%20%26%20Blumer%201985.pdf","seite":"124","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"afb025096b34e889"}},{"id":"qx-b1-024","clusterId":"B","werkstueckRef":"B.7","stufe":1,"question":"Was ist an der Aussage der Kollegin das Hauptproblem?","scenario":"Am Tag nach einer Wahl, bei der Kandidat A überraschend deutlich gewonnen hat, hörst du in der Kantine drei Sätze: (a) „Das musste ja so kommen.“ (b) „Ich habe doch gesagt, dass er gewinnt“ – dabei hatte sich der Sprecher vor der Wahl auf keinen Sieger festgelegt. (c) Eine Kollegin: „Das hätte man doch sehen müssen!“ Du weißt, dass vor der Wahl selbst Fachleute uneins waren und die Umfragen knapp standen.","options":["Sie misst die Vorhersehbarkeit am Ergebnis und blendet aus, dass Fachleute vorher uneins waren und die Umfragen knapp standen.","Sie wertet den Sieg von A ab, weil sie ihn politisch ablehnt, und urteilt parteiisch (Gruppenzugehörigkeits-Verzerrung).","Sie führt den überraschend deutlichen Sieg von A allein auf dessen Persönlichkeit zurück, nicht auf die Umstände (Attributionsfehler).","Sie stützt sich auf einprägsame Bilder aus dem Wahlkampf von A statt auf nüchterne Umfragezahlen und Prognosen (Verfügbarkeitsheuristik)."],"correctIndex":0,"explanation":"Wer den Ausgang kennt, sortiert die damaligen Informationen neu: Was zum Ergebnis passt, wirkt im Rückblick wichtig, was auf andere Ausgänge hindeutete, verliert an Gewicht. Vor der Wahl waren selbst Fachleute uneins und die Umfragen knapp, die Lage war also offen; der Satz „Das hätte man doch sehen müssen!“ misst sie am Wissen von heute und urteilt dadurch unfair. Die drei Sätze aus der Kantine zeigen drei Spielarten des Rückschaufehlers: „Das musste ja so kommen“ ist das Gefühl der Unvermeidbarkeit, „Ich habe doch gesagt, dass er gewinnt“ die Gedächtnisverzerrung (die eigene frühere Einschätzung rutscht in Richtung des Ergebnisses), „Das hätte man doch sehen müssen!“ das Gefühl der Vorhersehbarkeit. Hilfreich ist die Frage: Welche Informationen, die ich jetzt habe, hatte damals noch niemand?","coreRule":"⚡ Rückblickend wirkt alles zwingend, vorhersehbar und längst gewusst – dabei war es damals offen. Prüfe, was man zum Zeitpunkt der Entscheidung wissen konnte.","beleg":"Werkstück B.7 (Kontext & Tiefe, drei Ebenen); Fn. gl-b-rueckschau-ebenen (Roese/Vohs 2012, Perspectives on Psychological Science 7(5), S. 412–413)","status":"entwurf","kurz":"Wer das Ergebnis kennt, misst die damalige Lage daran und findet es im Rückblick offensichtlich. Dabei waren Fachleute uneins und die Umfragen knapp: Vorher war die Lage offen, und genau das blendet der Satz aus.","prueffrage":"Welche Tipps gaben die Leute in der Kantine vor der Wahl ab, und wie sicher waren sie sich damals?","rueckmeldung":[{"option":1,"text":"Eine politische Ablehnung kann ein Urteil färben, nur gibt das Szenario dafür keinen Anhaltspunkt. Der Satz „Das hätte man sehen müssen!“ bewertet den Sieg nicht, er behauptet, man hätte ihn vorher erkennen können."},{"option":2,"text":"Persönlichkeit statt Umstände zu betonen ist ein bekannter Denkfehler, kommt hier aber nicht vor: Die Kollegin sagt nichts über die Gründe für As Sieg oder über A als Person. Sie bewertet, was vorher erkennbar gewesen wäre."},{"option":3,"text":"Auffällige Bilder können Einschätzungen tatsächlich verzerren. Hier ist davon aber keine Rede: Die Kollegin beruft sich weder auf Bilder noch auf Zahlen, sondern misst die damalige, offene Lage am heutigen Ergebnis."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"161–162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"41f7297f8014b433"}},{"id":"qx-b1-025","clusterId":"B","werkstueckRef":"B.7","stufe":2,"question":"Welches Vorgehen schützt am besten davor, dass das Wissen um den Ausgang die Erinnerung und das Urteil verfälscht?","scenario":"Anna wechselt den Job. Ein halbes Jahr später läuft es schlecht, und sie denkt: „Ich hab doch gleich gespürt, dass das nicht passt.“ Ihr Freund Ben erinnert sich anders: Damals war sie begeistert und hielt den Wechsel für eine große Chance. Beide wollen bei der nächsten wichtigen Entscheidung später ehrlich beurteilen können, was sie vorher wussten und wie gut sie entschieden haben.","options":["Nach dem Ergebnis in Ruhe überlegen, was man damals eigentlich geglaubt und gewusst hat.","Nach dem Ergebnis eine vertraute Person fragen, wie man sich vor der Entscheidung geäußert hat.","Das Ergebnis konsequent als Maßstab nehmen, um die Entscheidung als gut oder schlecht zu bewerten.","Gründe und Unsicherheitsgrad vorab schriftlich festhalten, bevor das Ergebnis bekannt ist."],"correctIndex":3,"explanation":"Wer vor der Entscheidung schriftlich festhält, was er weiß und wie sicher er sich ist, hat später einen Beleg, der nicht mehr durch das Ergebnis verfälscht werden kann. Die Erinnerung nach dem Ausgang ist dagegen genau das, was der Rückschaufehler verzerrt: Wir sind dann überzeugt, es „schon immer gewusst“ zu haben. Auch das Ergebnis taugt nicht als Maßstab, denn eine gute Entscheidung kann schlecht ausgehen und umgekehrt. Beurteilen lässt sich eine Entscheidung nur danach, was zum Zeitpunkt der Entscheidung bekannt und absehbar war.","coreRule":"⚡ Schreib auf, was du weißt und wie sicher du bist – bevor du das Ergebnis kennst.","beleg":"Werkstück B.7 (Verbindungen: Entscheidungs-Tagebuch; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Nur ein vorab festgehaltener Beleg bleibt vom Ausgang unberührt, denn nachträgliche Erinnerung wird vom Wissen um das Ergebnis eingefärbt. Beurteilen lässt sich eine Entscheidung nur nach dem, was damals bekannt und absehbar war.","prueffrage":"Wie sicher sind sich Anna und Ben jeweils ihrer Erinnerung, und wie ließe sich heute klären, wer recht hat?","rueckmeldung":[{"option":0,"text":"Man will tatsächlich zum damaligen Wissen zurück, nur ist das Nachdenken dafür unzuverlässig. Wer den Ausgang kennt, erinnert sich durch ihn hindurch und findet leicht, er habe es „schon gewusst“."},{"option":1,"text":"Eine Außenperspektive kann Hinweise liefern, und Bens Erinnerung ist vielleicht näher an der Wahrheit. Sie bleibt aber ebenfalls Erinnerung nach dem Ausgang und ist so kein Beleg, der sich nicht verzerren lässt."},{"option":2,"text":"Das Ergebnis liegt vor und scheint ein klares Urteil zu liefern. Doch eine gute Entscheidung kann schlecht ausgehen und umgekehrt: Bewertet wird, was zum Zeitpunkt der Entscheidung bekannt und absehbar war."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Heuer, R. J. (1999): Psychology of Intelligence Analysis, Kap. 13: Hindsight Biases in Evaluation of Intelligence Reporting. CIA","oeffentlich":true,"url":"https://www.cia.gov/resources/csi/static/Pyschology-of-Intelligence-Analysis.pdf","seite":"162","abruf":"2026-10-12"},{"typ":"doi","kurz":"Fischhoff, B. (1975): Hindsight ≠ Foresight. Journal of Experimental Psychology: Human Perception and Performance 1(3)","oeffentlich":false,"doi":"10.1037/0096-1523.1.3.288"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"2838f628086e9428"}},{"id":"qx-b1-026","clusterId":"B","werkstueckRef":"B.7","stufe":4,"question":"Wie prüfst du am besten, ob diese Strophe das Ereignis wirklich vorhergesagt hat?","scenario":"Nach einer Katastrophe zeigt dir jemand eine mehrdeutige Strophe aus einer alten Prophezeiungssammlung. Er sagt, sie habe genau dieses Ereignis „vorhergesagt“, und verweist darauf, dass sich im Text Bilder finden, die zum Geschehen passen.","options":["Du fragst, ob sich die Handschrift der Strophe sicher auf die Zeit vor der Katastrophe datieren lässt, bevor du sie mit dem Ereignis verbindest.","Du fragst, ob die Deutung der Bilder schon vor der Katastrophe festgehalten wurde und konkret genug war, um scheitern zu können.","Du fragst, ob die Bilder der Strophe korrekt übersetzt wurden, da Übersetzungen die Bedeutung mehrdeutiger Bilder verschieben können.","Du fragst, ob die Person, die die Strophe deutet, Fachwissen über die Sammlung hat und seriös auftritt, bevor du ihrer Deutung traust."],"correctIndex":1,"explanation":"Ob die Deutung schon vor der Katastrophe festgehalten wurde, ist offen; oft wird zu einer mehrdeutigen Strophe erst nachträglich ein passendes Ereignis gesucht. Wer den Ausgang kennt, findet in vagen Bildern fast immer Anknüpfungspunkte, deshalb beweisen passende Bilder nichts. Echte Vorhersagekraft zeigt nur eine Aussage, die vor dem Ereignis festgehalten wurde und so konkret war, dass sie hätte scheitern können. Fehlt das, bleibt nur Deutungskraft im Rückblick. Die anderen Prüfungen klingen sinnvoll, greifen aber zu kurz: Das Alter der Handschrift zu klären ist bei der Echtheit wichtig, aber der Text ist ja alt; das Problem ist nicht, wann er entstand, sondern ob die Deutung vorab feststand. Eine genaue Übersetzung hilft, löst aber nicht das Problem, dass die Bilder mehrdeutig bleiben. Und das Fachwissen der Deutenden macht eine Deutung nicht überprüfbar, die erst nach dem Ereignis entstand.","coreRule":"⚡ Eine Vorhersage zählt nur, wenn sie vor dem Ereignis eindeutig festgehalten wurde.","beleg":"Werkstück B.7 (Anwendung & Relevanz: In der Esoterik)","status":"entwurf","kurz":"Echte Vorhersagekraft zeigt nur, was vor dem Ereignis festgehalten wurde und so konkret war, dass es hätte scheitern können. Wer den Ausgang kennt, findet in vagen Bildern fast immer Passendes; das bleibt dann Deutung im Rückblick.","prueffrage":"Auf wie viele andere Katastrophen der letzten Jahrzehnte ließe sich dieselbe Strophe ebenso gut beziehen?","rueckmeldung":[{"option":0,"text":"Die Datierung der Handschrift ist wichtig, wenn es um die Echtheit geht. Hier ist der Text aber ohnehin alt; offen bleibt, ob die Deutung schon vor dem Ereignis feststand und scheitern konnte."},{"option":2,"text":"Eine genaue Übersetzung ist sinnvoll, löst aber das Kernproblem nicht: Auch eine korrekt übersetzte Strophe bleibt mehrdeutig, und im Rückblick passt zu vagen Bildern fast immer ein Ereignis."},{"option":3,"text":"Fachwissen und seriöses Auftreten sprechen für eine sorgfältige Deutung, machen sie aber nicht überprüfbar. Eine Deutung, die erst nach dem Ereignis entstand, wird dadurch nicht zur Vorhersage."}],"familie":"urteil-vorab-festlegen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Association for Psychological Science (2012): „I Knew It All Along … Didn't I?“ – Understanding Hindsight Bias (zu Roese & Vohs 2012)","oeffentlich":true,"url":"https://www.psychologicalscience.org/news/releases/i-knew-it-all-along-didnt-i-understanding-hindsight-bias.html","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"c5e3b45a78c2778b"}},{"id":"qx-b1-027","clusterId":"B","werkstueckRef":"B.8","stufe":1,"question":"Was ist an dieser Überlegung fehlerhaft?","options":["Du erklärst sein Verhalten mit einer dauerhaften Eigenschaft und blendest die Umstände aus, die du nicht kennst.","Du urteilst über einen Vorfall, bei dem du nicht dabei warst, und übernimmst die Schilderung, ohne sie zu prüfen.","Du lässt deinen alten Eindruck („so war der schon immer“) das Urteil bestimmen, statt den Vorfall für sich zu sehen.","Du urteilst im Kern zutreffend, denn mehrfaches Unterbrechen ist rücksichtslos; zu scharf ist nur das Wort „Egoist“."],"correctIndex":0,"explanation":"Aus einem einzelnen Verhalten wird hier auf eine stabile Eigenschaft geschlossen („Egoist“, „schon immer“), während die Situation, die du nicht kennst, gar nicht in die Erklärung eingeht. Das ist der typische Fehlschluss beim Beurteilen anderer: Die Person ist das Auffälligste, was wir sehen, ihre Umstände sind für uns unsichtbar. Der Fehler besteht in der Tendenz, die Situation zu unterschätzen, nicht darin, dass der Charakter nie eine Rolle spielt.","coreRule":"⚡ Wer ein Verhalten sofort mit dem Charakter erklärt, sieht die Umstände nicht, die er nicht kennt.","beleg":"Werkstück B.8 (Kernidee; Kontext & Tiefe, Fokus der Aufmerksamkeit; Hinweis zur Beleglage); Fn. gl-b-attribution (Ross/Anderson 1982, Kap. 9)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"786bdc5ea28ae62f","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"scenario":"Du erfährst, dass Jonas bei der Teamsitzung gestern zwei Kollegen mehrfach das Wort abgeschnitten hat. Dein Gedanke: „Der ist einfach ein rücksichtsloser Egoist, so war der schon immer.“ Über Jonas' Woche weißt du nichts. Was du nicht weißt: Er hatte kurz vorher einen Abgabetermin mit großem Zeitdruck.","kurz":"Aus einem einzelnen Verhalten wird hier auf einen festen Charakterzug geschlossen, während der Zeitdruck, den du nicht kennst, in der Erklärung fehlt. Die Person fällt auf, ihre Umstände sieht man nicht. Der Charakter spielt dabei nicht nie eine Rolle, wird aber leicht überschätzt.","prueffrage":"Wie hat sich Jonas in früheren Sitzungen verhalten, und wer hat das selbst erlebt?","rueckmeldung":[{"option":1,"text":"Eine Schilderung aus zweiter Hand ungeprüft zu übernehmen, ist tatsächlich heikel. Der Fehler im Gedanken liegt aber woanders: Selbst wenn alles stimmt, wird aus einem Vorfall ein fester Charakterzug, und die Umstände fehlen."},{"option":2,"text":"„So war der schon immer“ stützt das Urteil, das stimmt. Entscheidend ist aber der Schluss selbst: Ein einzelnes Verhalten wird mit einer dauerhaften Eigenschaft erklärt, ohne die Umstände zu bedenken. Das bliebe auch ohne den alten Eindruck ein Fehler."},{"option":3,"text":"Das Wort „Egoist“ ist wirklich zu scharf, und Unterbrechen kann rücksichtslos wirken. Aber auch das mildere Urteil erklärt das Verhalten allein durch den Charakter und lässt den unbekannten Zeitdruck außen vor. Genau das trägt nicht."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"786bdc5ea28ae62f"}},{"id":"qx-b1-028","clusterId":"B","werkstueckRef":"B.8","stufe":3,"question":"In einem Podcast heißt es: „Jeder weiß doch: Wir erklären unser eigenes Fehlverhalten mit den Umständen, das Fehlverhalten anderer aber mit deren Charakter. Das ist psychologisch erwiesen.“ Du erfährst, dass eine Auswertung von 173 Studien genau diese Behauptung geprüft hat. Welche Frage hilft dir jetzt am meisten, um die Aussage einzuordnen?","options":["Wie groß war der durchschnittliche Effekt über alle 173 Studien hinweg, und unter welchen Bedingungen zeigte er sich überhaupt?","Wie viele Versuchspersonen nahmen an den 173 Studien insgesamt teil, und wie groß war die kleinste einzelne Studie?","Wer hat die Auswertung der 173 Studien bezahlt, und hatten die Autorinnen ein Interesse an einem bestimmten Ergebnis?","Welche der 173 Studien fand den stärksten Effekt, und wie wurde dort das Verhalten der Versuchspersonen gemessen?"],"correctIndex":0,"explanation":"Wer eine Behauptung prüfen will, schaut auf die Gesamtlage der Belege statt auf Bekanntheit, Einzelfälle oder das eigene Gefühl. Tatsächlich fand die Auswertung von 173 Studien (Malle 2006) für diese Asymmetrie im Durchschnitt praktisch keinen Effekt. Sie zeigte sich nur unter bestimmten Bedingungen, vor allem bei negativem Verhalten, und auch dort nur klein; bei positivem Verhalten kehrte sie sich um. Eine Behauptung kann jahrzehntelang als gesichert gelten und der Überprüfung trotzdem nur teilweise standhalten.","coreRule":"⚡ Auch Lehrbuchwissen braucht einen Quellencheck: Frag nach der Gesamtlage der Belege (Größe und Bedingungen des Effekts), nicht nach Bekanntheit oder Einzelfällen.","beleg":"Werkstück B.8 (Hinweis zur Beleglage); Fn. gl-b-attribution (Malle 2006, Psychological Bulletin 132(6), S. 895, 902, 907)","status":"entwurf","scenario":"Du hörst den Podcast beim Kochen und möchtest die Aussage nicht einfach glauben oder abtun.","kurz":"Entscheidend ist die Gesamtlage: Im Durchschnitt aller 173 Studien zeigte sich praktisch kein Effekt, nur unter bestimmten Bedingungen ein kleiner. Wer eine „erwiesene“ Behauptung nur aus Bekanntheit übernimmt, übersieht, dass sie der Prüfung oft nur teilweise standhält.","prueffrage":"Woher weiß der Podcast, dass „jeder“ das so macht, und welche Belege nennt er dafür?","rueckmeldung":[{"option":1,"text":"Eine große Teilnehmerzahl wirkt beruhigend, weil sie die Auswertung genauer macht. Wie groß der Effekt ist und wann er auftritt, sagt sie aber nicht: Auch eine sehr genaue Auswertung kann einen winzigen Effekt zeigen."},{"option":2,"text":"Wer bezahlt hat, ist eine berechtigte Frage, denn sie hilft, mögliche Interessen zu erkennen. Sie beantwortet aber nicht, was die Daten zeigen, und genau das brauchst du, um die Aussage einzuordnen."},{"option":3,"text":"Der stärkste Einzelbefund klingt nach dem besten Beleg für die Behauptung. Ein Spitzenwert unter 173 Studien sagt aber wenig über den Durchschnitt und darüber, unter welchen Bedingungen der Effekt auftritt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis, Abstract bei PubMed","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/17073526/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6)","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895","seite":"895, 902"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"be2554486916f577"}},{"id":"qx-b1-029","clusterId":"B","werkstueckRef":"B.8","stufe":4,"question":"Wie solltest du den Schluss einschätzen, der Attributionsfehler („wir erklären das Verhalten anderer vorschnell mit ihrem Charakter“) sei ein universelles Merkmal des Menschen?","options":["Die Verallgemeinerung geht zu weit: Vergleichsstudien deuten darauf hin, dass der Effekt außerhalb des Westens schwächer ausfällt, etwa bei Ostasiaten.","Die Verallgemeinerung ist vorläufig vertretbar: Solange niemand Gegenbefunde vorlegt, darf man annehmen, dass der Effekt überall ähnlich stark wirkt.","Die Verallgemeinerung ist gedeckt, sofern die Experimente genug Versuchspersonen umfassten: Bei großen Stichproben fällt deren Herkunft kaum ins Gewicht.","Die Verallgemeinerung ist gedeckt, wenn sich das Ergebnis in vielen Wiederholungen zeigte: Ein so oft bestätigter Befund dürfte überall gelten."],"correctIndex":0,"explanation":"Eine Verallgemeinerung ist nur so gut wie die Gruppe, an der getestet wurde. Wurden die klassischen Versuche fast nur mit westlichen Versuchspersonen gemacht, sagt das wenig über „den Menschen“ insgesamt. Tatsächlich deuten Vergleichsstudien darauf hin, dass der „fundamentale“ Fehler anderswo weniger grundlegend wirkt: Ostasiaten schlossen eher als US-Amerikaner auf die Macht der Situation, besonders wenn die Umstände deutlich hervorgehoben waren; ähnliche Befunde gibt es für Russen und früher für Hindus in Indien. Die angemessene Haltung: Der Effekt ist real, aber in Stärke und Verbreitung kulturabhängig.","coreRule":"⚡ Von einer Stichprobe auf „alle Menschen“ zu schließen, ist nur erlaubt, wenn die Stichprobe die Vielfalt der Menschen abbildet.","beleg":"Werkstück B.8 (Kontext & Tiefe); Fn. gl-b-attribution-kultur (Henrich/Heine/Norenzayan 2010, RatSWD Working Paper 139, S. 25 f.)","status":"entwurf","scenario":"In einem Podcast heißt es: „Dass wir das Verhalten anderer vorschnell mit ihrem Charakter erklären und die Umstände unterschätzen, ist ein Grundzug der menschlichen Natur – das tun alle Menschen überall gleich stark, das haben Experimente gezeigt.“ Die klassischen Experimente, auf die sich die Aussage stützt, wurden ganz überwiegend mit westlichen Versuchspersonen durchgeführt.","quote":"","quoteLabel":"","kurz":"Eine Verallgemeinerung reicht nur so weit wie die getestete Gruppe. Wer fast nur Westler untersucht, sagt wenig über „den Menschen“ aus, und Vergleichsstudien deuten auf eine schwächere Wirkung anderswo hin, etwa bei Ostasiaten.","prueffrage":"An wem wurden die klassischen Experimente eigentlich durchgeführt?","rueckmeldung":[{"option":1,"text":"Fehlende Gegenbefunde klingen nach Rückendeckung, doch wer „überall gleich stark“ behauptet, muss das belegen. Bei einer fast nur westlichen Stichprobe fehlt der Beleg, und Vergleichsstudien liefern sogar schon Hinweise auf Abweichungen."},{"option":2,"text":"Dass die Herkunft bei großen Stichproben kaum ins Gewicht fällt, wirkt plausibel, denn Größe macht Ergebnisse zuverlässiger. Sie gleicht aber keine einseitige Auswahl aus: Viele westliche Versuchspersonen bleiben eben westlich."},{"option":3,"text":"Viele Wiederholungen sprechen dafür, dass der Effekt in der untersuchten Gruppe real ist. Sie zeigen aber nicht, dass er überall gilt: Werden immer wieder ähnliche Versuchspersonen getestet, wiederholt sich auch dieselbe Einschränkung."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The Weirdest People in the World? RatSWD Working Paper 139 (KonsortSWD)","oeffentlich":true,"url":"https://www.konsortswd.de/wp-content/uploads/RatSWD_WP_139.pdf","abruf":"2026-10-12"},{"typ":"doi","kurz":"Henrich, J.; Heine, S. J.; Norenzayan, A. (2010): The weirdest people in the world? Behavioral and Brain Sciences 33(2–3)","oeffentlich":false,"doi":"10.1017/S0140525X0999152X"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"838aba3c81c10e59"}},{"id":"qx-b1-030","clusterId":"B","werkstueckRef":"B.8","stufe":2,"question":"Welche Frage prüft ihre Erklärung am besten?","scenario":"Eine Kollegin sagt über Menschen, die auf Heilkristalle schwören: „Die sind halt naiv und ungebildet.“ Du willst ihre Erklärung prüfen, bevor du sie übernimmst.","options":["Gibt es kontrollierte Studien, die zeigen, ob Heilkristalle über den Placebo-Effekt hinaus wirken?","Welche Hersteller verdienen an Heilkristallen, und wie stark bewerben sie ihre Produkte gegenüber Kunden?","Welche Umstände, etwa Kontrollbedürfnis oder enttäuschende Erfahrungen, machen den Glauben für sie attraktiv?","Wie viele Menschen kaufen Heilkristalle, und wie hat sich diese Zahl in den letzten Jahren entwickelt?"],"correctIndex":2,"explanation":"Die Kollegin führt das Verhalten anderer auf einen stabilen Charakterzug zurück: Sie seien „halt naiv und ungebildet“. Die Situation der Betroffenen blendet sie aus. Diese Verzerrung heißt fundamentaler Attributionsfehler: Wir unterschätzen bei anderen die Macht der Umstände und überschätzen ihre Eigenschaften. Bei Glaubensüberzeugungen können ganz verschiedene Umstände eine Rolle spielen, etwa ein Bedürfnis nach Kontrolle, schlechte Erfahrungen mit der Schulmedizin oder starker sozialer Einfluss im Umfeld. Wer nach ihnen fragt, prüft die Charaktererklärung an der Wirklichkeit. Das ist keine Rechtfertigung des Glaubens, sondern eine bessere Erklärung. Die anderen Fragen sind in anderer Lage sinnvoll, klären hier aber nichts: Ob Heilkristalle wirken, sagt nichts darüber, warum Menschen daran glauben. Wer am Geschäft verdient, erklärt das Angebot, nicht die Nachfrage. Und wie verbreitet der Glaube ist, zeigt nur seine Größe, nicht seine Gründe.","coreRule":"⚡ Frag nach den Umständen, bevor du über den Charakter urteilst.","beleg":"Werkstück B.8 (Anwendung & Relevanz: Bei Aberglaube & Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer fragt, in welcher Lage Menschen so etwas glauben, prüft die Charaktererklärung an der Wirklichkeit. „Naiv und ungebildet“ blendet die Umstände aus: Wir überschätzen bei anderen Eigenschaften und unterschätzen, was Situationen bewirken können.","prueffrage":"Was weiß die Kollegin über diese Menschen, außer dass sie an Heilkristalle glauben?","rueckmeldung":[{"option":0,"text":"Ob Heilkristalle wirken, lässt sich über Studien klären und ist eine berechtigte Frage. Warum Menschen daran glauben, beantwortet sie nicht: Auch Wirkungslosigkeit sagt nichts über die Gründe der Gläubigen."},{"option":1,"text":"Dass Hersteller werben und verdienen, erklärt vor allem das Angebot. Warum Kundinnen und Kunden darauf eingehen, bleibt offen, und gerade das müsstest du klären, um die Erklärung der Kollegin zu prüfen."},{"option":3,"text":"Die Zahl der Käufer und ihr Verlauf zeigen, wie verbreitet der Glaube ist. Warum Menschen so entscheiden, verraten sie nicht, und eine bloße Größe prüft keine Erklärung, die auf Eigenschaften der Käufer zielt."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1) (Kopie auf der Harvard-Seite von D. Gilbert)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ross, L.; Anderson, C. A. (1982): Shortcomings in the attribution process. In: Kahneman, D.; Slovic, P.; Tversky, A. (Hg.): Judgment under Uncertainty. Cambridge University Press, Kap. 9","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"202568560ebb7134"}},{"id":"qx-b1-031","clusterId":"B","werkstueckRef":"B.9","stufe":1,"question":"Drei Szenen: Jemand erkennt in einer Wolke ein Tiergesicht. Jemand setzt nach fünfmal Schwarz beim Roulette auf Rot, weil „jetzt Rot dran ist“. Jemand deutet eine zufällige Häufung von Krankheitsfällen in einer Stadt als Zeichen einer Ursache, obwohl die Verteilung statistisch normal ist. Was haben die drei Szenen gemeinsam?","options":["In allen dreien sieht jemand im bloßen Zufall eine Ordnung, die es dort nicht gibt: im Gesicht, in der Serie, in der Häufung.","In allen dreien wird ein bloßer Zusammenhang als Ursache und Wirkung gedeutet: Gesicht, Serie und Häufung haben angeblich einen Grund.","In allen dreien beachtet jemand nur die Treffer, die zu seiner Erwartung passen, und übersieht Gegenbeispiele: Gesicht, Rot, Krankheitsfälle.","In allen dreien wird dem Zufall eine Absicht unterstellt, als steuere jemand die Wolke, die Roulette-Serie und die Krankheitsfälle."],"correctIndex":0,"explanation":"Wolke, Roulette-Serie und Krankheitshäufung haben eine gemeinsame Wurzel: Das Gehirn sucht Ordnung und findet sie auch im reinen Zufall. Im ersten Fall ist es ein vermeintliches Gesicht, im zweiten eine scheinbare Gesetzmäßigkeit, nach der die nächste Runde die Serie ausgleichen müsse, obwohl jede Drehung unabhängig von den vorigen ist, im dritten eine zufällige Ballung, der eine besondere Ursache zugeschrieben wird. Die Neigung, Muster zu sehen, wo nur Rauschen ist, heißt Apophenie; der Roulette-Fall wird meist eigens als Spielerfehlschluss bezeichnet und beruht vor allem auf einem falschen Bild von unabhängigen Zufallsereignissen. Die Muster sind dabei nicht echt, sondern entstehen im Kopf des Betrachters; Apophenie ist eine allgemein menschliche Tendenz, die auch in der Allgemeinbevölkerung regelmäßig vorkommt (Blain u. a. 2020). Die anderen Deutungen klingen sinnvoll, passen aber nicht zu allen drei Szenen: Eine Ursache wird nur in der dritten Szene gesucht, Wolke und Roulette-Serie handeln nicht von Ursache und Wirkung. Ein Bestätigungsfehler setzt eine vorgefasste Erwartung voraus, von der bei Wolke und Roulette nichts zu sehen ist. Und dass jemand die Ereignisse steuert, nimmt in keiner der drei Szenen jemand an; es geht um Muster, nicht um einen Urheber.","coreRule":"⚡ Das Gehirn sieht Muster, auch wo keine sind: in Wolken, Serien und Ballungen.","beleg":"Werkstück B.9 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Alle drei Szenen zeigen, wie das Gehirn auch im reinen Zufall Ordnung findet, die dort nicht ist. Naheliegend ist, überall Ursache, Erwartung oder Absicht zu vermuten, doch die Muster entstehen im Kopf des Betrachters.","prueffrage":"Wie oft fällt beim Roulette fünfmal hintereinander dieselbe Farbe, wenn man über viele Abende hinweg zählt?","rueckmeldung":[{"option":1,"text":"Bei der Krankheitshäufung wird tatsächlich eine Ursache gesucht. Wolke und Roulette-Serie handeln aber nicht von Ursache und Wirkung, deshalb trifft diese Deutung nur eine der drei Szenen."},{"option":2,"text":"Selektives Beachten von Treffern gibt es im Alltag oft. Dafür bräuchte es aber eine vorgefasste Erwartung, die bei Wolke und Roulette nirgends zu sehen ist; auch beim Roulette liegt der Fehler im Bild vom Zufall selbst."},{"option":3,"text":"Hinter Zufallsserien einen Urheber zu vermuten, kommt vor. In diesen drei Szenen nimmt aber niemand an, dass jemand Wolke, Kugel oder Krankheitsfälle steuert; es geht allein um ein Muster, das gesehen wird."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives. Journal of Abnormal Psychology 129(3) (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives, Verlagsfassung","oeffentlich":false,"doi":"10.1037/abn0000504"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"be8e7f221b495955"}},{"id":"qx-b1-032","clusterId":"B","werkstueckRef":"B.9","stufe":3,"question":"Welche Schlussfolgerung ist aus diesem Studienergebnis am besten gerechtfertigt?","options":["Der Zusammenhang ist mäßig; ob das Mustersehen den Glauben verursacht, lässt sich aus der Korrelation in dieser Studie allein nicht ableiten.","Der Zusammenhang ist mäßig; wahrscheinlich löst der Glaube das Mustersehen aus, weil Gläubige auch Münzfolgen nach Absicht absuchen.","Der Zusammenhang ist mäßig; vermutlich steckt ein dritter Faktor dahinter, sodass das Mustersehen selbst den Glauben gar nicht beeinflusst.","Der Zusammenhang ist mäßig; da beide im Schnitt zusammenhängen, lässt sich bei Einzelnen vom Mustersehen verlässlich auf den Glauben schließen."],"correctIndex":0,"explanation":"Ein Wert von r = 0,3 liegt weit unter 1: Das Mustersehen erklärt nur einen kleinen Teil der Unterschiede im Verschwörungsglauben, aber ganz ohne Zusammenhang ist es auch nicht. Außerdem sagt eine Korrelation nichts über die Richtung: Vielleicht macht Mustersehen anfällig für Verschwörungen, vielleicht prägt ein verschwörungsnahes Weltbild auch den Blick auf Zufallsdaten, oder ein dritter Faktor wirkt auf beides. Tatsächlich zeigte eine Reihe von Studien (van Prooijen u. a. 2018) Zusammenhänge meist um r = 0,2 bis 0,4. In Versuchen, in denen ein verschwörungsnaher Text das Mustersehen verstärkte, wirkten die Bedingungen teils nur über das Mustersehen auf den Glauben; die Autoren schließen daher starke Schlüsse über Ursache und Wirkung aus. Eine frühere Studie fand keinen solchen Zusammenhang; die Autoren erklären das unter anderem damit, dass er sich bei Hochgebildeten womöglich nicht zeigt. Eine Schlagzeile mit „macht anfällig“ behauptet mehr, als die Zahlen tragen.","coreRule":"⚡ Mäßige Korrelation heißt: ein Zusammenhang, aber weder vollständige Erklärung noch bewiesene Ursache.","beleg":"Werkstück B.9 (Anwendung & Relevanz: Bei Verschwörungsmythen); Fn. gl-b-prooijen (van Prooijen u. a. 2018, EJSP 48(3), S. 323–324 und 331–332)","status":"entwurf","scenario":"Eine Forschungsgruppe lässt Versuchspersonen Münzwurf-Folgen betrachten und fragt, ob sie darin Muster erkennen. Außerdem erfasst sie, wie sehr die Personen an Verschwörungstheorien glauben. Ergebnis: Wer in den zufälligen Folgen eher Muster sah, glaubte im Schnitt etwas häufiger an Verschwörungen. Der Zusammenhang liegt bei r = 0,3 (zur Orientierung: r = 0 bedeutet kein Zusammenhang, r = 1 ein perfekter). Eine Schlagzeile dazu lautet: „Mustersehen macht anfällig für Verschwörungsglauben!“","quote":"","quoteLabel":"","kurz":"Bei r = 0,3 gibt es einen mäßigen Zusammenhang, aber eine Korrelation verrät nicht die Richtung: Mustersehen könnte den Glauben fördern, der Glaube den Blick prägen, oder ein dritter Faktor wirkt auf beides. „Macht anfällig“ behauptet zu viel.","prueffrage":"Liegt r = 0,3 näher an 0 oder an 1, und hat die Forschungsgruppe das Mustersehen gezielt verändert oder nur gemessen?","rueckmeldung":[{"option":1,"text":"Dass ein verschwörungsnahes Weltbild den Blick auf Zufallsdaten prägt, ist denkbar und von der Schlagzeile nur umgedreht. Gezeigt ist es hier aber genauso wenig: Beides wurde nur gemessen, und „wahrscheinlich“ trägt die Studie für keine der beiden Richtungen."},{"option":2,"text":"Ein dritter Faktor ist möglich, doch ein mäßiger Zusammenhang belegt ihn nicht. Vor allem schließt er eine Wirkung des Mustersehens nicht aus: Dass es gar keinen Einfluss hat, kann aus diesen Daten nicht folgen."},{"option":3,"text":"Dass der Zusammenhang nicht null ist, stimmt. Er gilt aber für den Durchschnitt der Gruppe; bei r = 0,3 erklärt das Mustersehen nur einen kleinen Teil der Unterschiede, und für einzelne Personen lässt sich daraus kaum etwas verlässlich vorhersagen."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots: Illusory pattern perception predicts belief in conspiracies and the supernatural. European Journal of Social Psychology 48(3) (PMC, CC BY 4.0)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5900972","abruf":"2026-10-12"},{"typ":"doi","kurz":"van Prooijen, J.-W.; Douglas, K. M.; De Inocencio, C. (2018): Connecting the dots, Verlagsfassung","oeffentlich":true,"doi":"10.1002/ejsp.2331","seite":"331–332"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"898da56a363a281d"}},{"id":"qx-b1-033","clusterId":"B","werkstueckRef":"B.9","stufe":4,"question":"Was ist der erste sinnvolle Prüfschritt?","scenario":"In einem Viertel deiner Gemeinde sind innerhalb eines Jahres auffällig viele Fälle derselben Erkrankung gemeldet worden. Im Ort wird über eine gemeinsame Ursache spekuliert: Manche vermuten das Trinkwasser, andere den Mobilfunkmast am Ortsrand.","options":["Die Wohnorte der Erkrankten kartieren und prüfen, ob sie näher am Mast oder an den Wasserleitungen liegen, um die Ursache einzugrenzen.","Wasserproben aus dem Viertel nehmen und die Strahlung am Mast messen, um beide Vermutungen im Ort anhand von Grenzwerten zu prüfen.","Prüfen, ob die Fallzahl im Viertel über das zufällig zu Erwartende hinausgeht, bevor man nach Wasser, Mast oder anderen Ursachen sucht.","Die Erkrankten befragen, was sie trinken und wie nah sie dem Mast wohnen, und die häufigste Gemeinsamkeit als Ursache prüfen."],"correctIndex":2,"explanation":"Die Clustering-Illusion beschreibt die Tendenz, in zufälligen Verteilungen „Ballungen“ zu sehen und ihnen eine besondere Bedeutung beizumessen; vermeintliche „Krebscluster“ in einer Stadt erweisen sich bei genauer Prüfung oft als statistisch unauffällig. Der erste Schritt ist deshalb die Frage, ob ein solches Muster auch in rein zufälligen Daten ähnlich wahrscheinlich wäre; erst wenn die Häufung über das zufällig zu Erwartende hinausgeht, lohnt die Suche nach einer Ursache. Die Karte der Wohnorte wirkt anschaulich, legt aber das Ziel erst um die vorhandenen Fälle und findet bei wenigen Punkten fast immer ein Muster, auch bei Zufall. Wasserproben und Strahlungsmessung klingen gründlich, sagen aber nur etwas über Grenzwerte und nichts darüber, ob die Häufung überhaupt mehr als Zufall ist. Die Befragung der Erkrankten wirkt naheliegend, doch gemeinsame Gewohnheiten gibt es in jeder Gruppe, ohne Kontrolle taugt die häufigste nicht als Ursache.","coreRule":"⚡ Bevor du ein Muster erklärst, prüfe, ob der Zufall es auch erzeugen könnte.","quote":"„Das kann doch kein Zufall sein!“","quoteLabel":"Typische Aussage:","beleg":"Werkstück B.9 (Kontext & Tiefe: Clustering-Illusion; Red Flags; Das Anti-Denkmuster)","status":"entwurf","kurz":"Zuerst gilt es zu klären, ob die Häufung überhaupt über das Zufällige hinausgeht. Wir sehen in Zufallsdaten leicht „Ballungen“ und suchen dann nach Gründen, die es vielleicht gar nicht braucht; erst eine echte Auffälligkeit rechtfertigt die Ursachensuche.","prueffrage":"Wie viele andere Viertel, Jahre und Krankheiten hätte man ebenso betrachten können, und wie oft fiele dabei irgendwo eine Häufung auf?","rueckmeldung":[{"option":0,"text":"Eine Karte macht Muster sichtbar, und das ist das Problem: Legt man das Ziel erst um die vorhandenen Fälle, findet man bei wenigen Punkten fast immer eine Nähe zu irgendetwas, auch wenn nur Zufall im Spiel ist."},{"option":1,"text":"Messungen wirken gründlich, vergleichen aber nur mit Grenzwerten. Ob die Häufung überhaupt mehr als Zufall ist, sagen sie nicht, und die Suche nach einer Ursache wäre dann verfrüht."},{"option":3,"text":"Gemeinsame Gewohnheiten gibt es in jeder Gruppe, etwa dasselbe Wasser oder denselben Weg zur Arbeit. Ohne Vergleich mit Gesunden sagt die häufigste Gemeinsamkeit wenig über eine Ursache."}],"familie":"muster-im-zufall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"National Cancer Institute: Cancer Clusters Fact Sheet","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/risk/substances/cancer-clusters-fact-sheet","abruf":"2026-10-12"},{"typ":"url","kurz":"Blain, S. D. u. a. (2020): Apophenia as the Disposition to False Positives (PMC, Autorenmanuskript)","oeffentlich":true,"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7112154/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"8c43ceeb52c81765"}},{"id":"qx-b1-034","clusterId":"B","werkstueckRef":"B.10","stufe":1,"question":"Du bekommst eine „persönliche Analyse“ und findest dich fast komplett darin wieder. Welche Frage prüft am besten, ob sie wirklich auf dich zugeschnitten ist?","options":["Würden sich auch viele andere Menschen in genau diesen Sätzen über Anerkennung und Zurückhaltung wiedererkennen?","Trifft jeder einzelne Satz der Analyse, auch der über die ungenutzten Fähigkeiten, wirklich auf mein eigenes Verhalten zu?","Wurde der Fragebogen von ausgebildeten Psychologen entwickelt, und ist seine Auswertung wissenschaftlich geprüft worden?","Wie viele Fragen enthielt der kurze Fragebogen, und reichen so wenige Antworten für eine Aussage über meine Persönlichkeit?"],"correctIndex":0,"explanation":"Die Sätze sind so allgemein, dass sie auf fast jeden zutreffen: Fast jeder ist mal gesellig, mal zurückhaltend, fast jeder ist sich selbst gegenüber manchmal kritisch. Sie schmeicheln dem Selbstbild („ungenutzte Fähigkeiten“) und enthalten nur einen Hauch harmloser Kritik, das wirkt echt. Dazu kommt, dass unser Gedächtnis sofort passende Situationen abruft und die unpassenden übergeht. Dass die Aussage auf dich passt, ist deshalb kein Beweis, dass sie für dich gemacht wurde. Entscheidend ist, ob sie auch auf viele andere passen würde. Im Klassenexperiment von Forer (1948) bewerteten Studierende denselben, aus Horoskopen zusammengestellten Text im Schnitt mit 4,26 von 5 als treffend. Satz für Satz auf dich zu prüfen klingt gründlich, ist aber genau das, was der Effekt täuscht, denn das Gefühl der Passung entsteht auch bei Standardtext. Die Ausbildung der Entwickler und die Prüfung des Fragebogens sind berechtigte Fragen, sagen aber nicht, ob dieser Text für dich geschrieben wurde. Und die Länge des Bogens entscheidet das nicht: Auch ein langer Bogen kann denselben Standardtext liefern.","coreRule":"⚡ Wenn eine „persönliche“ Beschreibung auf fast jeden passt, sagt sie nichts über dich.","beleg":"Werkstück B.10 (Kontext & Tiefe)","status":"entwurf","scenario":"Eine App wertet einen kurzen Fragebogen aus und schreibt dir: „Du hast ein großes Bedürfnis nach Anerkennung. Manchmal bist du gesellig, manchmal zurückhaltend. Du bist dir selbst gegenüber oft kritisch und hast Fähigkeiten, die du noch nicht voll nutzt.“ Du denkst: „Das bin genau ich!“","quote":"","quoteLabel":"","kurz":"Entscheidend ist, ob die Sätze auch auf viele andere passen würden, denn das Gefühl „Das bin ich!“ entsteht auch bei Standardtext. Der naheliegende Fehler ist, die Passung bei sich selbst für den Beweis einer Zuschneidung zu halten.","prueffrage":"Steht in den Sätzen irgendetwas Konkretes, etwa ein Ereignis, ein Name oder eine Vorliebe, das nur in deinem Leben vorkommt?","rueckmeldung":[{"option":1,"text":"Satz für Satz bei sich nachzuschauen wirkt gründlich. Das Gedächtnis liefert aber sofort passende Situationen und übergeht die unpassenden, sodass die Prüfung fast immer „stimmt“ ergibt, auch bei Text, der gar nicht für dich entstanden ist."},{"option":2,"text":"Wie der Fragebogen entwickelt und geprüft wurde, ist eine berechtigte Frage. Sie sagt aber nichts darüber, ob gerade dieser Text für dich geschrieben wurde, denn auch ein sauber entwickelter Bogen kann Standardsätze ausgeben."},{"option":3,"text":"Die Zahl der Fragen sagt etwas über die Aussagekraft eines Tests. Hier entscheidet sie die Sache aber nicht, denn auch ein langer Bogen kann am Ende denselben allgemeinen Text liefern, der auf fast jeden passt."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"1722461c68af1c1c"}},{"id":"qx-b1-035","clusterId":"B","werkstueckRef":"B.10","stufe":2,"question":"Was ist an der Schlussfolgerung deiner Freundin am ehesten fehlerhaft?","scenario":"Nach einer Sitzung bei einem Medium sagt eine Freundin begeistert: „Es hat mir gesagt, dass ich mir Sorgen um Geld mache und eine Kiste mit alten Fotos habe, die ich nicht wegwerfen kann. Beides stimmt! Das Medium muss echte Fähigkeiten haben.“ Auf Nachfrage räumt sie ein, dass es auch noch einiges andere gesagt hat, das nicht gepasst hat, daran erinnert sie sich aber kaum noch.","options":["Sie zählt die erinnerten Treffer bei Geldsorgen und Fotokiste und übergeht die Fehlschüsse, obwohl solche Aussagen auf viele Menschen passen.","Sie schließt nachvollziehbar, denn zwei so konkrete Treffer wie Geldsorgen und eine Fotokiste lassen sich durch bloßes Raten kaum erklären.","Sie stützt sich auf eine einzige Sitzung, obwohl sich echte Fähigkeiten erst über viele Sitzungen mit verschiedenen Menschen zeigen würden.","Sie lässt sich von ihrer Begeisterung über die Sitzung mitreißen und urteilt noch im Hochgefühl, statt mit etwas Abstand darüber nachzudenken."],"correctIndex":0,"explanation":"Die Freundin zählt nur die Treffer und blendet die Fehlschüsse aus. „Du machst dir Sorgen um Geld“ und „Du hast eine Kiste mit alten Fotos, die du nicht wegwerfen kannst“ sind typische Barnum-Aussagen aus dem Cold Reading. Ein Cold Reader feuert viele solche Aussagen ab und beobachtet die Reaktion seines Gegenübers. Die Treffer werden vom Klienten bestätigt und ausgebaut, die Fehlschüsse werden ignoriert. So entsteht der Eindruck großer Treffsicherheit, obwohl nur Allgemeines gesagt wurde.","coreRule":"⚡ Wer nur die Treffer zählt und die Fehlschüsse vergisst, hält Allgemeinplätze für Treffsicherheit.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei Wahrsagern, Hellsehern & Cold Reading)","status":"entwurf","kurz":"Sie zählt nur die erinnerten Treffer und blendet die Fehlschüsse aus. Aussagen wie Geldsorgen oder eine Fotokiste passen auf viele Menschen, und so wirkt etwas Allgemeines wie große Treffsicherheit.","prueffrage":"Wie viele andere Aussagen hat das Medium gemacht, und wie viele davon haben tatsächlich gepasst?","rueckmeldung":[{"option":1,"text":"Konkret klingen die beiden Aussagen schon, sie treffen aber auf sehr viele Menschen zu. Das lässt sich ohne besondere Fähigkeiten erklären, zumal die Fehlschüsse nicht mitgezählt wurden."},{"option":2,"text":"Eine einzelne Sitzung ist tatsächlich eine dünne Grundlage. Der Kern liegt aber anderswo: Auch mit vielen Sitzungen bliebe der Fehler bestehen, solange nur die Treffer zählen und die Fehlschüsse vergessen werden."},{"option":3,"text":"Begeisterung kann ein Urteil tatsächlich färben, und mehr Abstand schadet nicht. Der Mangel in der Schlussfolgerung bliebe mit Abstand aber bestehen, solange nur die Treffer zählen und die Fehlschüsse ausgeblendet werden."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3229cad9cf04d8c7"}},{"id":"qx-b1-036","clusterId":"B","werkstueckRef":"B.10","stufe":3,"question":"Wie viel von dieser Namensgeschichte darfst du als gesichert ansehen?","options":["Dass Barnum auf ein breites Publikum zielte, gilt als gesichert, weil sein Geschäft gut belegt ist; ob er den Satz sagte, bleibt ohne Quelle offen.","Dass Barnum den Satz sagte, gilt als gesichert, weil der Artikel ihn wörtlich zitiert und das kaum ohne Grundlage täte; offen ist nur, bei welchem Anlass.","Dass der Effekt auf Barnum zurückgeht, gilt als gesichert, weil der Artikel es so sagt und der Name dazu passt; offen ist nur, ob er den Satz sagte.","Dass Barnum etwas in dieser Art sagte, gilt als gesichert, weil der Satz gut zu seinem Ruf als Schausteller passt; offen ist nur der genaue Wortlaut."],"correctIndex":0,"explanation":"Hier gilt es, zweierlei zu trennen: Barnums Ruf und den angeblichen Wortlaut. Real ist sein Ruf als Schausteller, der sein Programm bewusst auf ein möglichst breites Publikum zuschnitt. Der Satz „Wir haben für jeden etwas dabei“ ist ihm dagegen nur populär zugeschrieben, ohne Beleg. Ein Zitat wird nicht dadurch belegt, dass es oft wiederholt wird oder gut zur Person passt. Auch das noch bekanntere „Alle naslang wird ein Dummkopf geboren“ ist nicht verifiziert. Und der Name „Barnum-Effekt“ stammt nicht von Barnum selbst: Er wurde 1956 vom Psychologen Paul E. Meehl geprägt, der ihn nach Barnums Ruf benannte. Der Effekt geht also nicht auf Barnum zurück, nur sein Name wurde geliehen. Wer einem Zitat oder einer Namensgebung vertrauen will, fragt deshalb nach der Quelle, nicht nach der Bekanntheit.","coreRule":"⚡ Ein oft wiederholtes Zitat ist noch kein belegtes Zitat: Frag nach der Quelle.","beleg":"Werkstück B.10 (Kontext & Tiefe); Fn. gl-b-barnum","status":"entwurf","scenario":"In einem Artikel über Persönlichkeitstests steht: „Der Barnum-Effekt geht auf den Zirkusmann P. T. Barnum zurück, der einst sagte: ‚Wir haben für jeden etwas dabei.‘“ Ein Beleg für den Satz wird nicht genannt, der Artikel verweist nur auf Barnums Ruf als Schausteller.","kurz":"Gesichert ist nur Barnums Ruf, sein Programm auf ein breites Publikum zuzuschneiden. Dass ein Satz zu einer Person passt oder oft wiederholt wird, belegt ihn nicht; ohne Quelle bleibt offen, ob er ihn je sagte.","prueffrage":"Wann bekam der Effekt seinen Namen, und lebte Barnum da noch?","rueckmeldung":[{"option":1,"text":"Ein wörtlich zitierter Satz wirkt, als stünde eine Quelle dahinter. Der Artikel nennt aber keine, und Zitate werden oft nur abgeschrieben. Auch die Frage nach dem Anlass setzt schon voraus, dass der Satz je gefallen ist."},{"option":2,"text":"Dass ein Name gut passt, verführt dazu, die Herkunft des Effekts bei dieser Person zu vermuten. Der Name wurde jedoch 1956 vom Psychologen Paul E. Meehl geprägt, der ihn nach Barnums Ruf benannte; der Effekt geht nicht auf Barnum zurück."},{"option":3,"text":"Ein Satz, der zum Ruf einer Person passt, wirkt glaubwürdig. Passung ist aber kein Beleg: Auch eine Aussage „in dieser Art“ ist ohne Quelle nur zugeschrieben. Gesichert ist Barnums Ruf, nicht, dass er so etwas sagte."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Barnum effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/barnum.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meehl, P. E. (1956): Wanted—a good cook-book. American Psychologist 11(6), 263–272","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"d48c52a12f50d7f0"}},{"id":"qx-b1-037","clusterId":"B","werkstueckRef":"B.10","stufe":4,"question":"Was folgt aus dem Treffer für die Frage, ob der Dienst dich persönlich „durchschaut“?","scenario":"Dein Streamingdienst schlägt dir einen Song vor, der genau zu deiner Stimmung passt, und du denkst: „Der kennt mich besser als meine Freunde.“ Du weißt, dass der Dienst seine Vorschläge aus den Hörgewohnheiten sehr vieler Nutzer ableitet.","options":["Er zeigt nichts Sicheres, denn ein auf breite Muster gestützter Vorschlag kann sich persönlich anfühlen, ohne dich persönlich zu erfassen.","Er spricht dafür, dass der Dienst dich gut kennt, denn ein so genauer Treffer zu deiner Stimmung entsteht aus bloßen Massendaten kaum.","Er spricht eher gegen ein Durchschauen, denn aus den Gewohnheiten sehr vieler Nutzer entsteht nur ein Durchschnitt, kein Bild von dir.","Er spricht dafür, dass dein Eindruck stimmt, denn das Gefühl, besser verstanden zu werden als von Freunden, stützt sich auf einen echten Treffer."],"correctIndex":0,"explanation":"Das gute Gefühl allein sagt wenig darüber, wie der Vorschlag zustande kam. Algorithmen stützen sich oft auf breite statistische Muster, die auf Millionen von Menschen zutreffen, sich für den Einzelnen aber ganz persönlich anfühlen. Das ist ein digitaler Barnum-Effekt: Bereits 1948 gab der Psychologe Bertram Forer seinen Studenten allen denselben, aus Horoskopen zusammengestückelten Text. Sie bewerteten ihn im Mittel mit 4,26 auf einer Skala von 0 bis 5, obwohl er für niemanden maßgeschneidert war. Die gefühlte Treffsicherheit ist deshalb kein Beleg für tiefes Verstehen. Der Schluss vom Treffer auf gutes Kennen geht vom Gefühl auf die Ursache, obwohl breite Muster einen solchen Treffer ebenso erzeugen können.","coreRule":"⚡ Gefühlte Treffsicherheit ist kein Beweis für echtes Verstehen.","beleg":"Werkstück B.10 (Anwendung & Relevanz: Bei algorithmischer Personalisierung)","status":"entwurf","kurz":"Ein Treffer fühlt sich persönlich an, auch wenn er aus breiten Mustern vieler Nutzer stammt. Das Gefühl, durchschaut zu werden, sagt wenig über die Entstehung des Vorschlags; es von da auf gutes Kennen zu schließen, überspringt diese Lücke.","prueffrage":"Woraus leitet der Dienst seine Vorschläge ab, und was davon betrifft nur dich?","rueckmeldung":[{"option":1,"text":"Ein genauer Treffer wirkt wie Beweis für genaues Kennen. Breite Muster liefern solche Treffer aber ebenfalls, weil viele Menschen in ähnlicher Stimmung Ähnliches hören. Die Genauigkeit allein verrät daher nicht, wie der Vorschlag entstand."},{"option":2,"text":"Dass Massendaten oft zugrunde liegen, stimmt. Daraus folgt aber nicht, dass der Dienst dich nicht kennt: Auch eigene Hördaten könnten einfließen. Der Treffer spricht weder dafür noch dagegen, er lässt die Frage offen."},{"option":3,"text":"Der Song kann dir tatsächlich gut gefallen. Das Gefühl, besser verstanden zu werden als von Freunden, ist aber nur dein Eindruck, kein Maß für das Verstehen. Derselbe Eindruck entsteht auch bei Aussagen, die für viele Menschen gleichermaßen passen."}],"familie":"passt-auf-jeden","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Carroll, R. T.: Forer effect. The Skeptic's Dictionary","oeffentlich":true,"url":"https://skepdic.com/forer.html","abruf":"2026-10-12"},{"typ":"doi","kurz":"Forer, B. R. (1949): The Fallacy of Personal Validation. Journal of Abnormal and Social Psychology 44(1), 118–123","oeffentlich":false,"doi":"10.1037/h0059240"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"c31996675de039e5"}},{"id":"qx-b1-038","clusterId":"B","werkstueckRef":"B.11","stufe":1,"question":"Welche Schlussfolgerung ist aus der Beobachtung gerechtfertigt?","scenario":"Du siehst nachts ein Licht, das schnell fliegt, plötzlich stehen bleibt und abrupt die Richtung ändert. Dein Freund sagt: „Ich kenne kein Flugzeug und keinen Satelliten, die das können – also muss es ein außerirdisches Raumschiff sein!“","options":["Es war ein außerirdisches Raumschiff, denn kein bekanntes Flugzeug und kein Satellit kann sich so bewegen.","Es war ein Flugzeug oder eine Drohne, denn die meisten gemeldeten Himmelslichter erweisen sich als gewöhnliche Objekte.","Es war eine optische Täuschung, denn ein Licht ohne Bezugspunkte am Nachthimmel scheint sich oft sprunghaft zu bewegen.","Es war ein unidentifiziertes Flugobjekt im wörtlichen Sinn, denn ich weiß schlicht nicht, was es war."],"correctIndex":3,"explanation":"Die Beobachtung zeigt nur, dass dein Freund keine Erklärung kennt. Das ist eine Aussage über den Stand seines Wissens, nicht über die Ursache des Lichts. Aus „mir fällt keine natürliche Erklärung ein“ folgt nicht, dass die Lieblingserklärung stimmt, und ebenso wenig, dass das Phänomen nicht stattgefunden hat oder doch ein gewöhnliches Objekt war. Eine Wissenslücke ist kein Beweis für irgendeine bestimmte Erklärung. Gerechtfertigt ist nur die ehrliche Feststellung, dass das Licht unidentifiziert bleibt. Sinnvoll ist dann, die Lücke zu untersuchen, statt sie mit einer bevorzugten Erklärung zu füllen. Dass die meisten gemeldeten Lichter gewöhnlich sind, spricht für eine Vermutung, entscheidet diesen Einzelfall aber nicht. Eine optische Täuschung ist als Möglichkeit denkbar, aber hier nicht gezeigt. Und was ein Mensch nicht kennt, sagt nichts darüber, was möglich ist.","coreRule":"⚡ „Ich weiß es nicht“ ist eine vollständige und ehrliche Antwort: Eine Wissenslücke beweist keine bestimmte Erklärung.","beleg":"Werkstück B.11 (Das Licht am Nachthimmel; Kontext & Tiefe)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"164445a31f34dd88","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Aus „mir fällt keine Erklärung ein“ folgt keine bestimmte Erklärung, denn das beschreibt nur das Wissen deines Freundes, nicht das Licht. Ehrlich gerechtfertigt ist nur: Es bleibt unidentifiziert, und diese Lücke lässt sich untersuchen.","prueffrage":"Was lässt sich bei einem Licht am Nachthimmel mit bloßem Auge über seine Entfernung, Größe und Geschwindigkeit sicher sagen?","rueckmeldung":[{"option":0,"text":"Dass deinem Freund nichts Bekanntes einfällt, stimmt vermutlich. Es beschreibt aber nur seinen Kenntnisstand, nicht das Licht. Die Lücke in seinem Wissen belegt keine Ursache, schon gar keine so besondere."},{"option":1,"text":"Dass die meisten gemeldeten Himmelslichter gewöhnlich sind, spricht für eine Vermutung. Für diesen einen Fall entscheidet es aber nichts. Auch hier würde die Lücke mit einer bevorzugten Erklärung gefüllt, nur in die andere Richtung."},{"option":2,"text":"Ohne Bezugspunkte scheinen Lichter am Nachthimmel tatsächlich oft zu springen, als Möglichkeit ist das denkbar. Im Szenario zeigt aber nichts, dass hier eine Täuschung vorlag; als Feststellung wäre es wieder eine ungeprüfte Lückenfüllung."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"164445a31f34dd88"}},{"id":"qx-b1-039","clusterId":"B","werkstueckRef":"B.11","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Dein Onkel sagt: „Es gibt keinen einzigen Beweis, dass es Leben auf anderen Planeten gibt – also gibt es keins.“","options":["Er folgert aus dem fehlenden Beweis für Leben, dass es keins gibt, obwohl ein fehlender Beweis allein noch nicht zeigt, dass etwas nicht existiert.","Er übersieht, dass auch niemand beweisen kann, dass es kein Leben gibt, und dass deshalb insgesamt mehr für Leben auf anderen Planeten spricht.","Er formuliert nur zu schroff, denn ohne jeden Beleg ist „kein Leben“ die vernünftigste Ausgangsannahme, er sollte sie bloß vorsichtiger äußern.","Er macht keinen Fehler, denn wer etwas behauptet, muss es beweisen, und solange der Beweis für Leben fehlt, gilt diese Behauptung als widerlegt."],"correctIndex":0,"explanation":"Der Onkel schließt von „nicht bewiesen“ auf „falsch“. Das ist das Argument aus Unwissenheit: Ein fehlender Beweis allein zeigt nicht, dass etwas nicht existiert, sondern zunächst nur, dass wir es nicht wissen. Gewicht bekommt das Fehlen eines Belegs erst, wenn gründlich dort gesucht wurde, wo ein Beleg zu erwarten wäre; über die allermeisten Planeten wissen wir dafür noch viel zu wenig. Der Fehler liegt also im Übergang von der Wissenslücke zur festen Aussage. Zulässig wäre: „Ich kenne keinen Beleg und halte die Frage deshalb für offen.“","coreRule":"⚡ Kein Beweis dafür heißt nicht „falsch“, kein Beweis dagegen nicht „wahr“.","beleg":"Werkstück B.11 (Kontext & Tiefe: Negative Form)","status":"entwurf","kurz":"Aus „nicht bewiesen“ folgt nicht „falsch“: Ein fehlender Beweis zeigt zunächst nur, dass wir es nicht wissen. Gewicht bekäme er erst nach gründlicher Suche, und über die meisten Planeten wissen wir dafür viel zu wenig.","prueffrage":"Was genau wurde bisher untersucht, und was würde man finden, wenn es dort doch etwas gäbe?","rueckmeldung":[{"option":1,"text":"Dass sich auch das Gegenteil nicht beweisen lässt, stimmt. Daraus folgt aber kein Übergewicht für Leben, sondern ein offener Stand. Der Fehler wird so nur gespiegelt: ein fehlender Beweis wird zur Aussage über die Wirklichkeit gemacht."},{"option":2,"text":"Eine vorsichtigere Formulierung wäre besser, doch am Ton liegt es nicht. „Kein Leben“ ist ohne Belege auch keine vernünftige Ausgangsannahme, denn nach allem, was wir wissen, ist die Frage schlicht offen."},{"option":3,"text":"Wer etwas behauptet, muss es belegen, das stimmt. Fehlt der Beleg, ist die Behauptung aber nicht widerlegt, sondern unbelegt. Der Onkel behauptet zudem selbst etwas („gibt keins“), und diese Behauptung bräuchte ebenfalls Gründe."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"8ac6bdb424abc8d9"}},{"id":"qx-b1-040","clusterId":"B","werkstueckRef":"B.11","stufe":4,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"In einer Debatte heißt es: „Die Wissenschaft kann bisher nicht bis ins letzte Detail erklären, wie das erste Leben aus unbelebter Materie entstand. Also muss es erschaffen worden sein.“","options":["Der Schluss ist fehlerhaft, weil er eine naturwissenschaftliche Frage mit einer Antwort von außerhalb der Naturforschung beantwortet; das sind verschiedene Arten von Fragen.","Der Schluss ist fehlerhaft, weil er zu früh kommt; erst wenn die Forschung auf Dauer keine Erklärung findet, wäre eine Erschaffung die naheliegende Folgerung.","Der Schluss ist fehlerhaft, weil aus einer Lücke im Wissen über das erste Leben keine bestimmte Erklärung folgt; sie zeigt nur, dass etwas noch offen ist.","Der Schluss ist fehlerhaft, weil sich eine Erschaffung nicht wissenschaftlich prüfen lässt; eine unprüfbare Behauptung taugt in dieser Debatte nicht als Antwort."],"correctIndex":2,"explanation":"Eine Wissenslücke ist selbst kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine bevorzugte Antwort“. Dieser Fehlschluss heißt Argument aus Unwissenheit, in religiösen Zusammenhängen auch „Gott der Lücken“: Eine aktuelle Lücke im wissenschaftlichen Verständnis wird als Beweis für die eigene Position ausgegeben. Dabei wird die Lücke willkürlich mit einer bevorzugten, unbewiesenen Erklärung gefüllt. Die ehrliche Antwort auf eine Lücke lautet: „Das wissen wir (noch) nicht.“ Eine Verallgemeinerung wäre sinnvoll zu rügen, doch hier wird aus der Lücke nicht auf das Versagen der Wissenschaft, sondern auf eine bestimmte Erklärung geschlossen. Ein Zirkelschluss klingt naheliegend, weil die Erschaffung das Ergebnis ist, aber die Begründung ist allein die Lücke und nicht die Erschaffung selbst. Ein Strohmann läge vor, wenn die Forschung verzerrt dargestellt würde; der Stand wird hier jedoch zutreffend wiedergegeben.","coreRule":"⚡ Eine Wissenslücke ist eine Frage, keine Antwort.","beleg":"Werkstück B.11 (Anwendung & Relevanz: Im Kreationismus & „Intelligent Design“; Der Kipppunkt)","status":"entwurf","kurz":"Eine Lücke im Wissen ist kein Beleg für eine bestimmte Erklärung. Aus „Das wissen wir noch nicht“ folgt nicht „Also gilt meine Antwort“; die ehrliche Antwort auf eine offene Frage bleibt: noch offen.","prueffrage":"Welche Beobachtung nennt die Aussage, die für sich genommen auf eine Erschaffung hindeutet?","rueckmeldung":[{"option":0,"text":"Dass die Antwort nicht aus der Forschung stammt, fällt tatsächlich auf. Der Fehler liegt aber eine Ebene davor: Aus einer Lücke folgt auch aus anderer Richtung keine bestimmte Erklärung, egal welcher Art die Antwort ist."},{"option":1,"text":"Zu früh geschlossen wurde hier tatsächlich. Auch nach langer erfolgloser Suche bliebe der Schluss aber unbegründet: Eine Lücke, ob kurz oder lang, belegt keine bestimmte Erklärung, sie bleibt eine offene Frage."},{"option":3,"text":"Ob sich eine Erschaffung prüfen lässt, ist eine berechtigte Frage. Der Schluss scheitert aber schon früher: Selbst eine prüfbare Alternative wäre durch bloßes Nichtwissen auf der anderen Seite nicht belegt."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Appeal to Ignorance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"87451e7ddc883f11"}},{"id":"qx-b1-041","clusterId":"B","werkstueckRef":"B.12","stufe":1,"question":"Welcher Denkfehler steckt in der Schlussfolgerung der Zuschauerin, und woran liegt er?","scenario":"Ein Nachrichtenmagazin kündigt eine Sondersendung an: „Die Form der Erde: Gibt es eine Kontroverse?“ Eine Astrophysikerin und ein YouTuber, der die Erde für eine Scheibe hält, bekommen exakt gleich viel Redezeit. Der Moderator schließt: „Eine faszinierende Diskussion mit vielen offenen Fragen. Bilden Sie sich Ihre eigene Meinung.“ Eine Zuschauerin sagt danach: „Dann scheint sich die Wissenschaft ja nicht einig zu sein.“","options":["Sie schließt von der gleichen Redezeit zweier Gäste auf eine gleich starke Beweislage, obwohl die Sendung nichts über die Verteilung der Expertenmeinungen sagt.","Sie schließt aus dem Schlusswort des Moderators auf offene Fachfragen, obwohl ein Moderator keine Fachautorität ist und sein Urteil über die Form der Erde wenig zählt.","Sie schließt aus dem Titel der Sendung, der nach einer Kontroverse fragt, auf echten Streit, obwohl eine als Frage formulierte Ankündigung noch nichts behauptet.","Sie schließt aus dem Streitgespräch zweier Gäste auf echte Uneinigkeit, obwohl sie erst hätte prüfen müssen, wer von beiden die besseren Argumente vorgetragen hat."],"correctIndex":0,"explanation":"Wie viel Bühne und Redezeit jemand bekommt, sagt nichts darüber, wie viele Fachleute seine Position teilen oder wie gut sie belegt ist. Bei der Form der Erde stützen Satellitendaten, Flugrouten, Erdkrümmung und astronomische Beobachtungen eine Seite erdrückend, die andere hat dem nichts Vergleichbares entgegenzusetzen. Die Sendung formt trotzdem den Eindruck einer 50/50-Kontroverse unter Experten, und die Zuschauerin übernimmt ihn. Bei politischen Meinungsfragen ist es sinnvoll, beide Seiten anzuhören. Bei Fragen mit erdrückender Beweislage verzerrt dasselbe Prinzip die Realität. Die richtige Prüffrage lautet daher nicht „Wurden beide gehört?“, sondern „Wie verteilen sich Belege und Fachmeinungen tatsächlich?“. Dass der Moderator beide Positionen als gleichwertig behandelt und die Beweislage nicht einordnet, überlässt die Wahrheitsfindung dem Publikum und erzeugt den falschen Eindruck einer Kontroverse.","coreRule":"⚡ Gleiche Redezeit ist keine gleiche Beweislage.","beleg":"Werkstück B.12 (Die Debatte über die Form der Erde; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Gleiche Redezeit sagt nichts über Beweislage und Fachmeinungen: Bei der Form der Erde stützt die Evidenz erdrückend eine Seite. Die Sendung erzeugt den Eindruck einer 50/50-Kontroverse, und die Zuschauerin übernimmt ihn als Stand der Wissenschaft.","prueffrage":"Was weißt du über die Form der Erde aus anderen Quellen, etwa von Satellitenbildern oder Flugrouten, und passt das zu einer offenen Streitfrage?","rueckmeldung":[{"option":1,"text":"Dass ein Moderator keine Fachautorität ist, stimmt. Der Eindruck entsteht aber nicht erst durch sein Schlusswort, sondern dadurch, dass beide Gäste gleich behandelt werden. Maßgeblich bleibt, wie sich Belege und Fachmeinungen tatsächlich verteilen."},{"option":2,"text":"Eine Frage im Titel behauptet tatsächlich noch nichts. Den Eindruck eines echten Streits erzeugt aber vor allem der Ablauf: gleiche Redezeit und keine Einordnung der Beweislage. Der Titel allein würde die Zuschauerin kaum zu ihrem Schluss führen."},{"option":3,"text":"Argumente zu vergleichen ist sinnvoll, greift hier aber zu kurz. Ein Streitgespräch zeigt nur zwei Auftritte, nicht, wie die Fachwelt urteilt und wie gut jede Position belegt ist. Bei Meinungsfragen ist es vernünftig, beide Seiten zu hören; bei erdrückender Beweislage verzerrt das die Wirklichkeit."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016, Journal of Experimental Psychology: Applied)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"5d347c1c69e2210d"}},{"id":"qx-b1-042","clusterId":"B","werkstueckRef":"B.12","stufe":2,"question":"Welche Frage deckt am besten auf, dass diese Gleichbehandlung das Bild verzerren könnte?","scenario":"Du siehst eine Talkrunde zu einem Gesundheitsthema: links eine Epidemiologin, die den breiten Befund der Fachliteratur vertritt, rechts ein Gast mit eigener Theorie, die kaum ein Fachmensch teilt. Beide bekommen gleich viel Redezeit, und der Moderator schließt mit: „Eine spannende Kontroverse, bilden Sie sich Ihre eigene Meinung.“","options":["Haben die Gäste ein finanzielles Interesse am Ausgang der Debatte, das ihre Aussagen färben könnte?","Entspricht die Verteilung der Gäste der tatsächlichen Verteilung der Expertenmeinungen im Fachgebiet?","Wurden beiden Gästen dieselben Fragen gestellt, und durften sie auf die Einwände des anderen antworten?","Lassen sich die Quellen, auf die sich beide Gäste berufen, für Zuschauer öffentlich einsehen und überprüfen?"],"correctIndex":1,"explanation":"Ob eine Debatte das Bild der Wirklichkeit wiedergibt, hängt nicht davon ab, wie fair die Bühne gebaut ist, sondern davon, wie die Beweislage tatsächlich verteilt ist. Wenn nahezu alle Fachleute eine Position teilen und nur eine Handvoll die andere, erzeugen zwei gleich große Redeanteile beim Publikum den falschen Eindruck eines 50/50-Streits unter Experten. Wer das prüfen will, vergleicht die Verteilung der Gäste mit der Verteilung der Expertenmeinungen im Feld.","coreRule":"⚡ Frag nicht nach der Fairness der Bühne, sondern nach dem Gewicht der Belege.","beleg":"Werkstück B.12 (Das Anti-Denkmuster; Red Flags)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"85be3e2728feacfb","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Entscheidend ist, wie viele Fachleute hinter welcher Position stehen. Gleiche Redezeit täuscht bei einer Handvoll Abweichler einen 50/50-Streit unter Experten vor, obwohl die Bühne fair wirkt.","prueffrage":"Woran hättest du als Zuschauer in der Sendung erkennen können, dass der zweite Gast mit seiner Theorie in der Fachwelt fast allein steht?","rueckmeldung":[{"option":0,"text":"Ein Eigeninteresse kann Aussagen färben, und das zu prüfen ist sinnvoll. Es betrifft aber nur, wie glaubwürdig ein einzelner Gast ist, nicht, wie viele Fachleute welche Position teilen."},{"option":2,"text":"Gleiche Fragen und Erwiderungsrechte sprechen für einen fairen Ablauf. Gerade dieser faire Rahmen kann aber den Eindruck eines Gleichstands noch verstärken, statt die Verzerrung aufzudecken."},{"option":3,"text":"Nachprüfbare Quellen sind wünschenswert. Sie zeigen aber nicht, welches Gewicht eine Position im Fach hat: Auch eine Außenseitertheorie kann offen belegt sein."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v5","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"ok","pruefsumme":"85be3e2728feacfb"}},{"id":"qx-b1-043","clusterId":"B","werkstueckRef":"B.12","stufe":3,"question":"Ein Nachrichtenmagazin plant zwei Beiträge. Beitrag 1: Ist die Erde eine Kugel? Beitrag 2: Bei der Behandlung einer seltenen Krankheit gehen zwei Forschungsgruppen mit jeweils guter Datenlage von unterschiedlichen Wirkmechanismen aus, und die Fachwelt ist gespalten. Wie sollte die Redaktion die beiden Beiträge anlegen?","options":["In beiden Beiträgen sollten beide Gäste gleich lang reden, weil gleiche Redezeit das Kennzeichen fairer Berichterstattung ist.","Nur im ersten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort eine verbreitete Fehlvorstellung auszuräumen ist.","Nur im zweiten Beitrag sollten beide Seiten ausführlich zu Wort kommen, weil nur dort die Fachwelt wirklich gespalten ist.","Im zweiten Beitrag sollte nur eine Forschungsgruppe auftreten, weil Zuschauer bei einer Krankheit klare Auskunft statt Streit brauchen."],"correctIndex":2,"explanation":"Zwei Seiten gleichwertig darzustellen ist nur sinnvoll, wenn die Frage wirklich offen ist. Bei der seltenen Krankheit stützen beide Positionen belastbare Daten, und die Fachwelt ist tatsächlich gespalten; hier bildet eine Debatte die Lage korrekt ab. Bei der Kugelgestalt der Erde gibt es keine legitime wissenschaftliche Kontroverse mehr; die Frage gilt als längst entschiedene Kernfrage der Wissenschaft. Eine Debatte mit gleicher Redezeit erzeugt beim Publikum den falschen Eindruck einer 50/50-Kontroverse unter Experten und verzerrt die Realität. Gleiche Redezeit ist kein Maß für Fairness: Entscheidend ist, ob die Verteilung der Positionen im Beitrag der tatsächlichen Verteilung der Expertenmeinungen und der Beweislage entspricht. Die anderen Gedanken klingen vertretbar, scheitern aber an der Lage: Gleiche Redezeit in beiden Beiträgen wirkt fair, täuscht beim Beitrag zur Erde aber einen Streit unter Fachleuten vor. Eine Fehlvorstellung im Gespräch zu entkräften wirkt aufklärerisch, ließe aber im zweiten Beitrag die tatsächlich gespaltene Fachwelt ohne Stimme. Nur eine Forschungsgruppe auftreten zu lassen wirkt übersichtlich, verschweigt aber, dass beide Gruppen eine gute Datenlage haben.","coreRule":"⚡ Zwei Seiten gehören dorthin, wo die Frage wirklich offen ist. Gewichte Positionen nach Beweislage, nicht nach Redezeit.","beleg":"Werkstück B.12 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","scenario":"Die Redaktion möchte „fair und ausgewogen“ berichten und überlegt, in beiden Beiträgen jeweils zwei Gäste mit gleicher Redezeit auftreten zu lassen.","kurz":"Zwei Positionen gleichwertig zu zeigen, ist nur dort sinnvoll, wo die Fachwelt wirklich gespalten ist, also beim Beitrag zur Krankheit. Gleiche Redezeit allein macht nicht fair: Beim Thema Erde würde sie einen Expertenstreit vortäuschen, den es nicht gibt.","prueffrage":"Was unterscheidet die Datenlage hinter den Positionen beim ersten Thema von der beim zweiten?","rueckmeldung":[{"option":0,"text":"Für den zweiten Beitrag passt das, denn dort steht tatsächlich Position gegen Position. Beim Thema Erde würde gleiche Redezeit aber einen Streit unter Fachleuten vortäuschen, den es nicht gibt. Fairness misst sich am Gewicht der Belege, nicht an der Stoppuhr."},{"option":1,"text":"Fehlvorstellungen zu klären ist ein gutes Ziel, doch dafür braucht es keine gleichberechtigte Debatte, die eine offene Frage nahelegt. Und der zweite Beitrag, in dem die Fachwelt wirklich gespalten ist, bliebe ohne beide Stimmen."},{"option":3,"text":"Klare Auskunft ist ein berechtigter Wunsch, aber hier würde sie nur durch Weglassen entstehen. Beide Gruppen haben eine gute Datenlage, die Fachwelt ist gespalten. Zeigt man nur eine Gruppe, wirkt die Lage entschiedener, als sie ist."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „False Balance“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v4","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"2ab872e4bc04852f"}},{"id":"qx-b1-044","clusterId":"B","werkstueckRef":"B.12","stufe":4,"question":"Welche Wirkung hat dieses Format auf Zuschauer, die das Thema nicht aus eigener Sachkenntnis beurteilen können?","scenario":"Ein Fernsehsender plant eine Sondersendung zum Klimawandel. Im Studio sitzen zwei Gäste: eine Klimaforscherin, deren Aussagen dem Stand der Fachliteratur entsprechen, und ein Redner, der die menschengemachte Erwärmung bestreitet und mit seiner Haltung unter Fachleuten kaum Rückhalt hat. Der Moderator gibt beiden exakt gleich viel Redezeit und schließt mit den Worten: „Eine spannende Debatte mit offenem Ausgang. Bilden Sie sich Ihre eigene Meinung.“","options":["Sie gewinnen den Eindruck, unter Fachleuten sei die Frage noch offen, obwohl die Fachwelt weitgehend einig ist.","Sie erhalten ein ausgewogenes Bild, weil beide Seiten gleich lange sprechen und jeder die Argumente selbst abwägen kann.","Sie trauen sich danach ein eigenes Urteil zu, weil sie beide Seiten aus erster Hand gehört haben und vergleichen konnten.","Sie folgen der Seite, die überzeugender auftritt, weil sie die Inhalte nicht prüfen können und aufs Auftreten achten."],"correctIndex":0,"explanation":"Wer nicht selbst beurteilen kann, wie verbreitet eine Position unter Fachleuten ist, schließt aus der Bühne auf das Gewicht: Gleiche Redezeit und ein offenes Schlusswort legen nahe, dass sich zwei etwa gleich starke Lager gegenüberstehen. Tatsächlich bejahen über 99 % der einschlägigen Fachartikel eine menschengemachte Erwärmung; die Beweislage ist also keineswegs 50 zu 50. Gleiche Bühnenzeit bildet nicht die Beweislage ab, sondern verzerrt sie (falsche Ausgewogenheit). Eine bloße Gegenüberstellung ersetzt außerdem keine Einordnung: Die Bewertung der Beweiskraft wird dem unvorbereiteten Zuschauer überlassen.","coreRule":"⚡ Eine 50:50-Bühne kann eine 99:1-Fachwelt als Streit erscheinen lassen.","beleg":"Werkstück B.12 (Anwendung & Relevanz: Bei der Leugnung des Klimawandels; Verweis auf Band VI)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"675f1af9c1debd30","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Gleiche Redezeit und ein offenes Schlusswort wirken wie ein Patt zwischen zwei starken Lagern. Wer die Fachlage nicht kennt, schließt von der Bühne auf das Gewicht der Positionen, obwohl die Beweislage keineswegs 50 zu 50 ist.","prueffrage":"Woran könnte jemand ohne Sachkenntnis in dieser Sendung erkennen, welche der beiden Positionen in der Fachwelt Rückhalt hat?","rueckmeldung":[{"option":1,"text":"Gleich lange Redezeit sieht fair aus, bildet aber nicht ab, wie die Belege tatsächlich verteilt sind. Und wer das Thema nicht beurteilen kann, kann die Argumente auch nicht sinnvoll abwägen."},{"option":2,"text":"Beide Seiten gehört zu haben, fühlt sich nach Urteilsfähigkeit an. Ohne Vorwissen lässt sich aber nicht einschätzen, wie viel jede Position wiegt. Eine Gegenüberstellung ersetzt die Einordnung nicht, sie überlässt sie den Zuschauern."},{"option":3,"text":"Dass Laien eher auf Auftreten als auf Inhalte achten, ist gut möglich. Hier liegt das Problem aber früher: Schon die gleiche Bühnenzeit erzeugt den Eindruck, beide Lager stünden etwa gleich stark da, egal wer überzeugender wirkt."}],"familie":"gewicht-statt-redezeit","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Cornell Chronicle (2021): More than 99.9% of studies agree: Humans caused climate change","oeffentlich":true,"url":"https://news.cornell.edu/stories/2021/10/more-999-studies-agree-humans-caused-climate-change","abruf":"2026-10-12"},{"typ":"doi","kurz":"Lynas, M.; Houlton, B. Z.; Perry, S. (2021): Greater than 99% Consensus on Human Caused Climate Change in the Peer-Reviewed Scientific Literature. Environmental Research Letters 16(11), 114005","oeffentlich":true,"doi":"10.1088/1748-9326/ac2966"},{"typ":"url","kurz":"University of Waterloo, Department of Psychology: Why People Are Confused About What Experts Really Think (zu Koehler 2016)","oeffentlich":true,"url":"https://uwaterloo.ca/psychology/news/why-people-are-confused-about-what-experts-really-think","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"675f1af9c1debd30"}},{"id":"qx-b1-045","clusterId":"B","werkstueckRef":"B.13","stufe":1,"question":"Welche Rückfrage trifft den Kern des Fehlers in diesem Gespräch?","scenario":"Im Chat schreibt eine Kollegin: „Wie soll ein winziger Anteil eines unsichtbaren Gases wie CO2 das ganze Klima der Erde verändern? Das kann ich mir beim besten Willen nicht vorstellen, also ist die Sache Unsinn.“ Du willst ihr antworten.","options":["Beweist dein fehlendes Vorstellungsvermögen etwas über die Sache, oder zeigt es nur, wo dein Wissen gerade endet?","Hast du nachgesehen, wie groß der CO2-Anteil tatsächlich ist, oder schätzt du nur, dass er so winzig ist?","Meinst du nicht, dass die Fachleute, die das erforschen, mehr davon verstehen als wir beide hier im Chat?","Kann etwas Unsichtbares nicht trotzdem wirken, so wie man auch Viren nicht sieht und sie doch krank machen?"],"correctIndex":0,"explanation":"Die Kollegin schließt von „Ich kann mir nicht vorstellen, wie X wahr sein könnte“ auf „X ist nicht wahr“. Das ist ein Fehlschluss, denn die Grenzen der eigenen Vorstellungskraft sind kein Beleg gegen eine Behauptung. Unsere Intuition ist für Alltagsdinge in mittlerer Größe und bei mittlerer Geschwindigkeit geeignet. Bei Rückkopplungen im Klimasystem, in der Quantenphysik oder bei der Entwicklung des Auges versagt sie regelmäßig, und die Wirklichkeit hat keine Pflicht, unserem Bauchgefühl zu entsprechen. Auch die Verwandlung einer Raupe in einen Schmetterling, bei der in der Puppe große Teile des Körpers abgebaut und neu aufgebaut werden, klingt unvorstellbar und ist trotzdem real. Die richtige Rückfrage trennt deshalb sauber zwischen dem eigenen Unglauben und der Frage, was für oder gegen die Behauptung spricht.","coreRule":"⚡ Was ich mir nicht vorstellen kann, ist deshalb nicht unmöglich.","quote":"Ich kann es mir nicht vorstellen, also kann es nicht wahr sein.","quoteLabel":"Merksatz:","beleg":"Werkstück B.13 (Die unmögliche Raupe; Kernidee; Kontext & Tiefe; Anwendung & Relevanz)","status":"entwurf","kurz":"Fehlende Vorstellungskraft sagt etwas über den Stand unseres Wissens, nicht über die Sache. Der Fehler liegt darin, aus „kann ich mir nicht vorstellen“ ein „ist nicht wahr“ zu machen, obwohl die Intuition bei Rückkopplungen oft versagt.","prueffrage":"Welche Gründe nennt die Kollegin dafür, dass die Sache Unsinn ist?","rueckmeldung":[{"option":1,"text":"Die Zahl nachzusehen ist sinnvoll, und tatsächlich ist der CO2-Anteil klein. Der Fehler liegt aber nicht in der Zahl, sondern darin, dass sie aus ihrem Unglauben auf Unsinn schließt. Das bliebe auch bei richtiger Zahl bestehen."},{"option":2,"text":"Expertenwissen ist ein gutes Indiz, doch hier ersetzt der Verweis darauf die Auseinandersetzung. Die Rückfrage soll klären, was ihr Unglauben überhaupt beweist, und nicht, wer mehr weiß."},{"option":3,"text":"Das Beispiel trifft zu: Unsichtbares kann wirken, Viren zeigen es. Damit räumst du aber nur diesen einen Einwand aus. Ihr Maßstab „ich kann es mir nicht vorstellen“ bleibt stehen und würde beim nächsten Einwand wiederkehren."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Jabr, F. (2012): How Does a Caterpillar Turn into a Butterfly? Scientific American","oeffentlich":true,"url":"https://www.scientificamerican.com/article/caterpillar-butterfly-metamorphosis-explainer/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"6f7ea78111e9e373"}},{"id":"qx-b1-046","clusterId":"B","werkstueckRef":"B.13","stufe":2,"question":"Warum ist die Intuition in diesem Fall ein schlechter Maßstab, obwohl dasselbe Bauchgefühl bei dubiosen Verkaufsangeboten gut schützt?","scenario":"Ein Kollege sagt über ein neues Medikament: „Wie soll ein winziger Wirkstoff den ganzen Körper beeinflussen? Das kann ich mir nicht vorstellen, also wirkt es nicht.“ Die Zulassungsstudien liegen offen vor, er hat sie nicht gelesen. Zu gut klingende Angebote kennst du selbst als Fall, in dem dich ein Bauchgefühl zu Recht zum genaueren Hinsehen bringt.","options":["Weil sie hier als letztes Wort dient und verhindert, dass er die offen vorliegenden Belege überhaupt prüft.","Weil bei Medikamenten mehr auf dem Spiel steht als bei einem Kauf und ein falsches Gefühl hier schwerere Folgen hat.","Weil sie sich hier gegen ein neues Mittel richtet, und Neues erscheint dem Bauchgefühl oft unglaubwürdiger, als es ist.","Weil ihm hier anders als bei einem Kaufangebot die Fachkenntnis fehlt, mit der er sein Gefühl überprüfen könnte."],"correctIndex":0,"explanation":"Ein Bauchgefühl ist ein brauchbarer erster Filter: Es lässt uns bei Angeboten, die zu gut klingen, genauer hinsehen und schützt so vor vielen Betrügereien. Zum Problem wird es, wenn es zur unanfechtbaren Endinstanz wird. „Ich kann mir das nicht vorstellen“ sagt etwas über die Grenzen der eigenen Vorstellungskraft und des eigenen Wissens, nicht über die Wirklichkeit. Die Intuition ist für Alltagssituationen mit mittleren Größen und Geschwindigkeiten geeicht, bei komplexen wissenschaftlichen Themen weit außerhalb der Alltagserfahrung führt sie in die Irre. Wer seine Intuition hier über die vorliegenden Studien stellt, schaltet die Prüfung der Belege ab, die sie herausfordern könnten. Die Intuition ist nicht grundsätzlich unzuverlässig, sondern nur als finale Urteilsinstanz problematisch.","coreRule":"⚡ Die Intuition darf den Anfang der Prüfung machen, aber nicht das letzte Wort haben.","beleg":"Werkstück B.13 (Das Adaptive Talent; Der Kipppunkt)","status":"entwurf","kurz":"Das Bauchgefühl taugt als Erstfilter, aber „Ich kann mir das nicht vorstellen“ beschreibt nur die Grenzen seiner Vorstellungskraft, nicht die Wirklichkeit. Zum Fehler wird es, wenn es als letztes Wort die offen vorliegenden Studien aussticht.","prueffrage":"Wie oft konnte der Kollege sein Gefühl über Arzneiwirkungen schon an echten Ergebnissen überprüfen, verglichen mit deinem Gefühl bei Verkaufsangeboten?","rueckmeldung":[{"option":1,"text":"Dass bei Medikamenten mehr auf dem Spiel steht, ist richtig, erklärt aber den Unterschied nicht: Auch ein Betrug kann teuer werden. Entscheidend ist, dass das Gefühl hier das letzte Wort behält und die vorliegenden Belege nie geprüft werden."},{"option":2,"text":"Skepsis gegenüber Neuem ist verständlich, doch die Neuheit ist nicht der Kern. Auch bei einem Verkaufsangebot würdest du dem Gefühl nachgehen. Der Fehler beginnt dort, wo es sich über Studien stellt, die man einsehen könnte."},{"option":3,"text":"Fehlendes Fachwissen und begrenzte Vorstellungskraft spielen mit hinein. Aber die Studien liegen offen, und mit etwas Mühe lassen sie sich prüfen. Der Fehler ist nicht die Wissenslücke, sondern dass das Gefühl trotzdem als Endurteil dient."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"},{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"59f3ef46150c0a77"}},{"id":"qx-b1-047","clusterId":"B","werkstueckRef":"B.13","stufe":4,"question":"Was ist an dieser Aussage als Argument gegen die Evolution des Auges ihr eigentliches Problem?","scenario":"Jemand sagt: „Ich kann mir einfach nicht vorstellen, wie sich aus zufälligen Mutationen und natürlicher Selektion etwas so Komplexes wie ein menschliches Auge entwickeln konnte. Das ist doch unmöglich!“","options":["Sie hält für unmöglich, was höchstens unwahrscheinlich wirkt, obwohl ein seltener Verlauf deshalb noch lange nicht ausgeschlossen ist.","Sie macht die Grenze der eigenen Vorstellungskraft zum Maßstab für die Wirklichkeit, obwohl daraus nichts über die Entstehung des Auges folgt.","Sie ist berechtigte Skepsis, weil bei einem so komplexen Organ wie dem Auge Zweifel an einer schrittweisen Entstehung durchaus angebracht sind.","Sie greift nur im Ausdruck daneben, weil Zweifel erlaubt sind, „unmöglich“ aber ein zu starkes Wort ist, solange die Frage nicht ganz geklärt ist."],"correctIndex":1,"explanation":"Der Satz „Ich kann mir nicht vorstellen, wie …“ beschreibt nur, was in einem Kopf möglich ist, nicht was in der Natur möglich ist. Aus fehlender Vorstellungskraft folgt nichts über die Wirklichkeit: Vieles, was sich als wahr herausgestellt hat, widerspricht der Alltagsintuition, etwa dass Uhren in schneller Bewegung langsamer gehen oder dass riesige Kontinente langsam über den Globus driften. Der Einwand ist also kein Argument, sondern ein Bekenntnis zur eigenen Wissenslücke, etwa über die kleinen Zwischenschritte, in denen komplexe Strukturen entstehen können. Hilfreich ist die Frage, ob der Mangel an Vorstellungskraft ein Beweis gegen die Behauptung oder nur ein Beweis für die Grenzen des eigenen Wissens ist.","coreRule":"⚡ Wenn du es dir nicht vorstellen kannst, such eine Erklärung oder Analogie, statt es abzulehnen.","beleg":"Werkstück B.13 (Kontext & Tiefe; Anwendung & Relevanz: Bei der Evolutionstheorie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Aus „Ich kann mir das nicht vorstellen“ folgt nichts über die Natur, nur etwas über den Wissensstand der Person. Vieles Wahre, etwa die Kontinentaldrift, widerspricht der Intuition. Die Lücke liegt im Kopf, nicht im Beweis.","prueffrage":"Welche einfacheren Augen gibt es heute bei anderen Tieren, und was zeigen sie über mögliche Zwischenstufen?","rueckmeldung":[{"option":0,"text":"„Unmöglich“ ist tatsächlich zu stark gewählt. Der Kern liegt aber woanders: Ob etwas wahrscheinlich ist, sagt der Satz gar nicht, er misst nur, was sich eine Person vorstellen kann, und das ist kein Maßstab für die Natur."},{"option":2,"text":"Fragen zu stellen und Lücken zu benennen ist sinnvoll. Als Einwand taugt der Satz aber nicht, denn dass jemand die kleinen Zwischenschritte nicht kennt, spricht nicht dagegen, dass es sie gibt."},{"option":3,"text":"Das Wort „unmöglich“ ist zu stark, das stimmt. Der Fehler liegt aber im Schluss selbst: Auch in vorsichtigerer Fassung würde die eigene Vorstellungskraft als Beleg dienen, und das trägt nicht."}],"familie":"vorstellung-ist-kein-massstab","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Darwin, C. (1859): On the Origin of Species, Kap. VI „Organs of extreme perfection“ (Darwin Online)","oeffentlich":true,"url":"https://darwin-online.org.uk/content/contentblock?basepage=1&itemID=F373&hitpage=186&viewtype=text","seite":"186 f.","abruf":"2026-10-12"},{"typ":"url","kurz":"Bebbington, D.: I Don't Believe It! Philosophy Now, Heft 142","oeffentlich":true,"url":"https://ftp.philosophynow.org/issues/142/I_Dont_Believe_It","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"0871d8652e185f71"}},{"id":"qx-b1-048","clusterId":"B","werkstueckRef":"B.14","stufe":1,"question":"Welcher Denkfehler steckt in dem Satz „Das ist rein natürlich, die Natur weiß am besten, was gut für uns ist“?","scenario":"In der Drogerie rät dir jemand zu einem pflanzlichen Erkältungsmittel: „Das ist rein natürlich, ohne all die aggressive Chemie. Die Natur weiß am besten, was gut für uns ist.“","options":["Er lässt nur die gute Natur oder die schädliche Chemie als Möglichkeit gelten (falsches Dilemma).","Er beruft sich auf die Natur wie auf eine Instanz, die man nicht hinterfragt (Autoritätsargument).","Er wertet die Alternative mit dem Reizwort „aggressive Chemie“ ab, das Angst weckt (Appell an die Furcht).","Er schließt von der Herkunft eines Stoffs auf dessen Sicherheit und Wirkung (Appell an die Natur)."],"correctIndex":3,"explanation":"Der Satz setzt „natürlich“ mit „gut, sicher, überlegen“ gleich. Das ist ein Fehlschluss, denn die Herkunft eines Stoffs sagt nichts über Sicherheit oder Wirkung. Die Natur ist gleichgültig gegenüber unserem Wohlbefinden: Sie bringt Heilendes hervor, aber auch Tödliches wie Botulinumtoxin, Schlangengift oder Knollenblätterpilze. Ob ein Mittel hilft oder schadet, zeigen Reinheit, Dosierbarkeit und getestete Wirkung. Der Fehler liegt also nicht in einer angeblichen Schwäche natürlicher Stoffe, sondern darin, dass von der Herkunft auf Sicherheit und Wirkung geschlossen wird. Der Satz bewertet einen Stoff nach seiner Herkunft statt nach geprüfter Evidenz.","coreRule":"⚡ „Natürlich“ ist ein Herkunftsetikett, kein Gütesiegel.","beleg":"Werkstück B.14 (Das Gespräch in der Drogerie; Kernidee; Kontext & Tiefe)","status":"entwurf","kurz":"Ob ein Mittel hilft oder schadet, hängt von Reinheit, Dosis und geprüfter Wirkung ab, nicht von seiner Herkunft. Der Fehler ist der Schluss von „natürlich“ auf „sicher und wirksam“, obwohl die Natur auch Tödliches wie Knollenblätterpilze hervorbringt.","prueffrage":"Was steht auf der Packung über die Menge der Inhaltsstoffe und über Studien zur Wirkung?","rueckmeldung":[{"option":0,"text":"Natur und Chemie werden hier zwar gegeneinandergestellt, doch der Satz nennt keine zwei einzigen Möglichkeiten. Sein Kern ist der Schluss von der Herkunft auf Güte und Sicherheit, und auch Pflanzenstoffe bestehen aus Chemie."},{"option":1,"text":"„Die Natur weiß es am besten“ klingt nach einer höchsten Instanz. Eine Autorität stützt sich aber auf Fachwissen, und die Natur hat weder Wissen noch Absichten. Der Satz bewertet einfach den Ursprung eines Stoffs als gut."},{"option":2,"text":"„Aggressive Chemie“ ist tatsächlich ein abwertendes, angstnahes Wort. Doch auch ohne dieses Wort bliebe der Fehler bestehen: Es wird von „natürlich“ auf „sicher und wirksam“ geschlossen, und das trägt nicht."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"2098fe103efc0f6a"}},{"id":"qx-b1-049","clusterId":"B","werkstueckRef":"B.14","stufe":2,"question":"Was spricht an dieser Argumentation am ehesten gegen den Schluss, der Rindenextrakt sei dem Laborprodukt überlegen?","options":["Die Rinde enthält viele weitere Substanzen, und ihr Wirkstoffgehalt schwankt mit Baum und Jahreszeit. Die Herkunft sagt also nichts über Reinheit und Dosis aus.","Ihr Schluss folgt eher aus ihrer Abneigung gegen Tabletten als aus einem Vergleich. Sie müsste also beide Mittel selbst ausprobieren, um das zu beurteilen.","Wo ein Wirkstoff zuerst gefunden wurde, ist ein Zufall der Entdeckung. Ob ein Mittel besser hilft, zeigt also erst, wie viele damit gute Erfahrungen machen.","Menschen sprechen auf dasselbe Mittel unterschiedlich gut an. Der Extrakt kann also für sie passen, ohne deshalb allgemein dem Aspirin überlegen zu sein."],"correctIndex":0,"explanation":"Die Freundin schließt von der Herkunft auf die Qualität. Das ist ein Fehlschluss, denn entscheidend sind Reinheit, Dosierbarkeit und geprüfte Wirkung. Weidenrinde enthält neben dem Vorläuferstoff Salicin hunderte andere Substanzen, von denen manche die Wirkung abschwächen oder Nebenwirkungen haben können. Außerdem schwankt der Wirkstoffgehalt je nach Baum, Jahreszeit und Standort, sodass sich kaum genau dosieren lässt. Eine Aspirin-Tablette enthält dagegen eine festgelegte Menge reiner Acetylsalicylsäure, deren Vorläufer in der Weidenrinde vorkommt. Das macht Synthetisches nicht automatisch besser, es zeigt nur, dass „natürlich“ kein Qualitätsmerkmal ist.","coreRule":"⚡ Die Herkunft eines Stoffes sagt nichts über seine Qualität. Reinheit, Dosis und getestete Wirkung entscheiden.","beleg":"Werkstück B.14 (Kontext & Tiefe: Der entscheidende Vorteil des „Künstlichen“)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"6013234a0abdf36d","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"scenario":"Eine Freundin hat Kopfschmerzen und will keine Tabletten nehmen. Sie sagt: „Ich nehme lieber Weidenrinden-Extrakt statt Aspirin. Der Wirkstoff kommt ja ursprünglich aus der Rinde, also ist das Original natürlich besser als die Kopie aus dem Labor.“","kurz":"Die Herkunft aus der Rinde sagt nichts über Qualität: Der Extrakt enthält viele weitere Stoffe und schwankt im Gehalt, die Tablette ist rein und genau dosiert. „Natürlich“ ist also kein Qualitätsmerkmal.","prueffrage":"In welcher Beziehung steht der Wirkstoff der Weidenrinde zu dem der Aspirin-Tablette?","rueckmeldung":[{"option":1,"text":"Dass Abneigung gegen Tabletten ihre Haltung antreibt, ist gut möglich. Das klärt aber nicht, ob der Extrakt besser ist, und ein einzelner Selbstversuch bei Kopfschmerzen sagt darüber wenig, weil Beschwerden von selbst schwanken."},{"option":2,"text":"Der Fundort des Wirkstoffs sagt tatsächlich wenig über seine Wirkung. Gute Erfahrungen vieler Menschen sind aber noch kein Maßstab, denn sie lassen sich leicht verzerrt wahrnehmen. Entscheidend sind Reinheit, Dosierung und geprüfte Wirkung."},{"option":3,"text":"Dass Menschen unterschiedlich ansprechen, trifft zu, und dem Extrakt kann man eine Wirkung nicht absprechen. Das beantwortet aber nicht ihr Argument: Gefragt ist, ob „natürlich“ ein Zeichen von Qualität ist, nicht, ob er ihr persönlich nützen kann."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Vlachojannis u. a. (2011), Verlagsfassung","oeffentlich":false,"doi":"10.1002/ptr.3386"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"6013234a0abdf36d"}},{"id":"qx-b1-050","clusterId":"B","werkstueckRef":"B.14","stufe":3,"question":"Eine Bekannte erzählt dir, sie esse am liebsten unverarbeitete Lebensmittel, gehe oft in den Wald und setze bei leichten Erkältungen auf Kräutertee. Ihr Bruder lehnt dagegen die vom Arzt empfohlene Behandlung seiner Erkrankung ab und nimmt stattdessen nur noch „rein natürliche“ Präparate, weil „die Natur am besten weiß, was gut für uns ist“. Woran erkennst du, dass beim Bruder der Appell an die Natur zum gefährlichen Fehlschluss wird?","options":["Er ersetzt eine geprüft wirksame und sichere Behandlung durch Mittel, deren Wirkung und Dosierung ungeprüft sind, und riskiert dadurch schwere Folgen.","Er setzt bei einer behandlungsbedürftigen Erkrankung auf natürliche Mittel, die als sanfte Mittel eher für leichte Beschwerden wie Erkältungen taugen.","Er begründet seine Wahl mit dem Satz, die Natur wisse am besten, was gut für uns ist, und schon in dieser Begründung liegt der eigentliche Fehlschluss.","Er folgt nicht der Behandlung, die sein Arzt empfohlen hat, und weicht damit vom Rat der Person ab, die seine Erkrankung fachlich beurteilen kann."],"correctIndex":0,"explanation":"Eine Vorliebe für Natürliches ist für sich genommen harmlos und oft sogar gesund: Wer unverarbeitete Lebensmittel mag, im Wald spazieren geht oder bei einer leichten Erkältung Kräutertee trinkt, trifft keine riskante Entscheidung. Der Fehlschluss wird erst gefährlich, wenn er zu einer Entscheidung mit Folgen wird. Das ist der Fall, wenn eine nachweislich wirksame und sichere Behandlung durch Mittel ersetzt wird, deren Wirkung nie geprüft wurde und deren Dosis schwankt. Dann entscheidet die Herkunft über die Behandlung statt die belegte Wirkung. Ein Beispiel: Wer eine Chemotherapie zugunsten von Aprikosenkernen ablehnt, setzt sich einem Gift aus (sie enthalten Amygdalin, aus dem im Körper giftige Blausäure entstehen kann), statt die Krankheit zu behandeln. Die Herkunft sagt weder etwas über Sicherheit noch über Wirksamkeit. Die richtige Frage lautet immer: Was zeigen die besten Belege über Sicherheit, Reinheit, Dosierbarkeit und Wirksamkeit genau dieses Mittels? Die Überzeugung, dass Natürliches besser ist, teilt in milder Form auch seine Schwester, ohne sich zu gefährden.","coreRule":"⚡ Natürliche Vorlieben sind harmlos – gefährlich wird erst der Ersatz geprüfter Lösungen durch ungeprüfte.","beleg":"Werkstück B.14 (Der Kipppunkt)","status":"entwurf","scenario":"","kurz":"Der Appell an die Natur wird gefährlich, wenn er eine belegt wirksame, sichere Behandlung gegen ungeprüfte Mittel mit schwankender Dosis tauscht. Dann entscheidet die Herkunft statt der belegten Wirkung, und die Gesundheit steht auf dem Spiel.","prueffrage":"Bei welchen Beschwerden setzt die Bekannte auf Natürliches, und bei welchen ihr Bruder?","rueckmeldung":[{"option":1,"text":"Dass Kräutertee bei einer leichten Erkältung gut passt, stimmt. Der Maßstab ist aber nicht, ob ein Mittel sanft wirkt, sondern was über seine Sicherheit und Wirkung belegt ist; Natürliches ist nicht automatisch mild oder harmlos."},{"option":2,"text":"Der Satz „Die Natur weiß es am besten“ ist tatsächlich ein Fehlschluss. Als bloße Überzeugung bleibt er aber oft harmlos, die Schwester teilt ihn in milder Form ohne Risiko. Gefährlich wird er erst durch die Folge: den Verzicht auf eine wirksame Behandlung."},{"option":3,"text":"Von einer Empfehlung abzuweichen, ist für sich noch kein Fehler. Auch ärztlicher Rat darf hinterfragt werden. Entscheidend ist, wodurch die Behandlung ersetzt wird: hier durch Mittel ohne geprüfte Wirkung und Dosierung, nicht durch eine belegte Alternative."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Milazzo, S.; Horneber, M. (2015): Laetrile treatment for cancer. Cochrane Database of Systematic Reviews, CD005476 (Volltext frei in PMC6513327)","oeffentlich":true,"doi":"10.1002/14651858.CD005476.pub4","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3e3e07ee08497cb3"}},{"id":"qx-b1-051","clusterId":"B","werkstueckRef":"B.14","stufe":4,"question":"Wie ist diese Behauptung am treffendsten zu beurteilen?","scenario":"Ein Verkäufer behauptet: „Dieser Stoff aus der Pflanze ist dem im Labor hergestellten überlegen, obwohl beide chemisch exakt identisch sind. Denn der natürliche trägt eine Lebenskraft in sich.“","options":["Sie ist vertretbar, weil „chemisch identisch“ nur die Zusammensetzung meint und die Herkunft eines Stoffes darüber hinaus für seine Wirkung eine Rolle spielen kann.","Sie ist ein Widerspruch in sich, weil der Verkäufer beide Stoffe exakt identisch nennt und dem einen im selben Atemzug dennoch einen Vorrang vor dem anderen gibt.","Sie ist eine Glaubensfrage, weil sich eine Lebenskraft mit naturwissenschaftlichen Mitteln weder bestätigen noch ausschließen lässt, und bleibt damit Privatsache.","Sie ist eine unbelegte Zusatzannahme, weil bei identischen Molekülen kein Unterschied gezeigt wird und Wirkung und Sicherheit durch Tests geprüft werden müssen."],"correctIndex":3,"explanation":"Die Behauptung gibt zu, dass beide Stoffe chemisch identisch sind, und setzt dann einen Vorteil des „natürlichen“ obendrauf, die „Lebenskraft“. Diese behauptete Überlegenheit ist unbewiesen, und sie lässt sich auch nicht an den Molekülen festmachen, die ja gleich sind. Die Herkunft sagt weder etwas über Wirksamkeit noch über Sicherheit: Der Knollenblätterpilz ist ebenso natürlich wie Arsen. Was zählt, sind Reinheit, Dosierbarkeit, Wirksamkeit und Sicherheit, und die muss man durch Tests belegen.","coreRule":"⚡ Bei identischen Molekülen bleibt „Lebenskraft“ eine Behauptung, kein Befund.","beleg":"Werkstück B.14 (Anwendung & Relevanz: In der Pseudomedizin & Wellness-Industrie; Das Anti-Denkmuster)","status":"entwurf","kurz":"Der Verkäufer gibt die chemische Gleichheit zu und setzt dann einen Vorteil obendrauf, den er nicht belegt. Natürliche Herkunft ersetzt keinen Nachweis: Wirksamkeit und Sicherheit müssen durch Tests gezeigt werden.","prueffrage":"Welcher messbare Unterschied zwischen den beiden Stoffen wird in der Aussage tatsächlich genannt?","rueckmeldung":[{"option":0,"text":"Die Herkunft kann zwar Begleitstoffe oder Reinheit verändern. Hier sind die Stoffe aber als identisch gesetzt, und dass die Herkunft allein etwas an Wirkung oder Sicherheit ändert, ist unbelegt. Es wäre erst durch Tests zu zeigen."},{"option":1,"text":"Dass der Verkäufer die Gleichheit zugibt und trotzdem einen Vorrang behauptet, fällt auf. Ein logischer Widerspruch liegt aber nicht vor, sondern eine zusätzliche Behauptung. Sie ist unbelegt, und genau daran liegt das Problem."},{"option":2,"text":"Eine „Lebenskraft“ ist schwer zu prüfen, das stimmt. Der angebliche Vorteil in Wirkung und Sicherheit aber lässt sich durch Tests sehr wohl prüfen. Wer ihn als Überlegenheit verkauft, muss ihn belegen, das ist keine Privatsache."}],"familie":"natuerlich-kein-guetesiegel","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO: Botulism. Fact sheet","oeffentlich":true,"url":"https://www.who.int/news-room/fact-sheets/detail/botulism","abruf":"2026-10-12"},{"typ":"url","kurz":"Vlachojannis, J.; Magora, F.; Chrubasik, S. (2011): Willow species and aspirin: different mechanism of actions. Phytotherapy Research 25(7), 1102–1104 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/21226125/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"a1aea2970cf94b39"}},{"id":"qx-b1-052","clusterId":"B","werkstueckRef":"B.15","stufe":1,"question":"Was ist an diesem Schluss fehlerhaft, und welche Information würde ihn am ehesten prüfen?","scenario":"In einem Ratgeber-Artikel steht: „Zwei bekannte Tech-Gründer haben ihr Studium abgebrochen und sind Milliardäre geworden. Also ist ein Studienabbruch ein guter Weg zum Erfolg.“","options":["Der Schluss stützt sich nur auf die Erfolgreichen; entscheidend wäre, wie es den übrigen erging, die ebenfalls abgebrochen haben.","Der Schluss stützt sich auf nur zwei Fälle; entscheidend wäre, ob sich noch mehr Milliardäre finden, die ihr Studium abgebrochen haben.","Der Schluss verwechselt Abfolge und Ursache; entscheidend wäre, ob die beiden auch mit einem Abschluss so erfolgreich geworden wären.","Der Schluss setzt Erfolg mit Reichtum gleich; entscheidend wäre, ob die beiden in Beruf und Leben auch sonst zufrieden geworden sind."],"correctIndex":0,"explanation":"Hier werden nur diejenigen betrachtet, die einen Auswahlprozess erfolgreich durchlaufen haben. Die vielen Menschen, die ebenfalls abgebrochen haben und gescheitert sind, tauchen in keiner Erfolgsgeschichte auf, wären für den Schluss aber entscheidend. Erst der Vergleich zeigt, ob Abbrechen die Erfolgschance erhöht oder ob Glück, Timing und andere Faktoren die Hauptrolle spielen. Ähnlich ist es bei Gewohnheiten wie „früh aufstehen“: Auch viele Gescheiterte können sie gehabt haben.","coreRule":"⚡ Wenn nur Gewinner gezeigt werden, frag nach denen, die dasselbe getan haben und trotzdem gescheitert sind.","beleg":"Werkstück B.15 (Kernidee; Anwendung & Relevanz: In der Business- & Self-Help-Industrie)","status":"entwurf","kurz":"Der Schluss kennt nur die, die trotz Abbruchs reich wurden. Wer ebenfalls abbrach und scheiterte, taucht in keiner Erfolgsgeschichte auf, wäre aber nötig, um zu sehen, ob Abbrechen die Chancen wirklich erhöht oder ob Glück und Timing entscheiden.","prueffrage":"Woher kennt der Artikel gerade diese zwei Gründer, und warum wird über sie überhaupt geschrieben?","rueckmeldung":[{"option":1,"text":"Zwei Fälle sind tatsächlich dünn. Aber auch hundert weitere Milliardäre mit Abbruch würden nur die Gruppe der Erfolgreichen vergrößern; über die vielen Abbrecher ohne Erfolg sagte das weiterhin nichts."},{"option":2,"text":"Ob die beiden mit Abschluss ebenso erfolgreich geworden wären, lässt sich bei Einzelpersonen gar nicht beobachten. Der Schluss scheitert zudem früher: Er kennt nur die Gewinner und lässt alle aus, die ebenfalls abbrachen und scheiterten."},{"option":3,"text":"Reichtum ist tatsächlich nur ein enges Maß für ein gutes Leben. Auch mit einem weiteren Erfolgsbegriff blieben aber dieselben Fälle im Blick, und die Gescheiterten, die ebenfalls abbrachen, kämen weiterhin nicht vor."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v7","modell":"claude-sonnet-5-5","datum":"2026-10-14","urteil":"korrigieren","pruefsumme":"cc34edbfafab0c9c"}},{"id":"qx-b1-053","clusterId":"B","werkstueckRef":"B.15","stufe":2,"question":"Welche Frage prüft die Schlussfolgerung des Lesers am besten?","scenario":"In einer Zeitung wird ein Medium gefeiert, weil es ein Ereignis angeblich korrekt vorhergesagt hat. Berichtet wird nur über diese eine Vorhersage. Ein Leser schreibt: „Das kann kein Zufall sein, das Medium hat offenbar echte Fähigkeiten.“","options":["Wie viel Geld und Ansehen gewinnt die Zeitung, wenn sie das Medium für diese Vorhersage feiert?","Wie viele andere Vorhersagen dieses und anderer Medien lagen daneben und wurden nie erwähnt?","Wie gründlich haben anerkannte Stellen die behaupteten Fähigkeiten dieses Mediums geprüft?","Wie unwahrscheinlich war das Ereignis, sodass ein bloß zufälliger Treffer kaum zu erwarten war?"],"correctIndex":1,"explanation":"Bei diesem Medium hörst Du nichts von den vielen Vorhersagen desselben Mediums (und aller anderen), die danebenlagen. Die Treffer überleben in der öffentlichen Erinnerung, die Fehlschüsse verschwinden. Der eine berichtete Treffer ist also eine nach Erfolg gefilterte Auswahl. Ob er etwas über echte Fähigkeiten aussagt, lässt sich erst beurteilen, wenn Du auch die verfehlten Vorhersagen kennst.","coreRule":"⚡ Zeig mir nicht nur die Treffer, sondern alle Versuche.","quote":"Aber wo ist der Friedhof? Welche unsichtbaren Daten der Gescheiterten fehlen in diesem Bild?","quoteLabel":"Prüffrage:","beleg":"Werkstück B.15 (Anwendung & Relevanz: In der Esoterik; Das Anti-Denkmuster)","status":"entwurf","kurz":"Ein einzelner berichteter Treffer sagt wenig, solange du nicht weißt, wie viele Vorhersagen danebenlagen. Die Fehlschüsse verschwinden, die Treffer bleiben: Du siehst nur eine nach Erfolg gefilterte Auswahl.","prueffrage":"Warum berichtet die Zeitung gerade über diese Vorhersage, und worüber hätte sie geschrieben, wenn sie nicht eingetroffen wäre?","rueckmeldung":[{"option":0,"text":"Ein Eigeninteresse der Zeitung kann die Auswahl der Berichte färben. Es sagt aber nicht, wie oft das Medium danebenlag. Ohne diese Zahl bleibt unklar, ob der eine Treffer etwas über Fähigkeiten verrät."},{"option":2,"text":"Eine Überprüfung der behaupteten Fähigkeiten durch anerkannte Stellen wäre durchaus nützlich. Das Szenario nennt sie aber nicht, und sie ersetzt nicht den Blick darauf, welche Fehlschüsse im Bericht unterschlagen werden."},{"option":3,"text":"Ein unwahrscheinlicher Treffer beeindruckt, und das zählt durchaus. Wurden aber viele Vorhersagen gemacht, ist irgendwann auch ein seltenes Ereignis durch Zufall dabei. Erst die Zahl der Fehlschüsse macht den Treffer einschätzbar."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"url","kurz":"Dowden, B.: Fallacies, Eintrag „Selective Attention“. Internet Encyclopedia of Philosophy","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"7effe5fa60ed5a87"}},{"id":"qx-b1-054","clusterId":"B","werkstueckRef":"B.15","stufe":3,"question":"Du liest in einem Wirtschaftsmagazin, wie ein Mathematiker im Zweiten Weltkrieg den Generälen mit einem einzigen Satz widerspricht: „Meine Herren, Sie liegen komplett falsch.“ Wie gehst du mit der Szene um?","options":["Ich halte den Kerngedanken für prüfbar, die wörtliche Szene aber für ungesichert, weil anschauliche Details ohne Quelle leicht dazugedichtet sind.","Ich prüfe, ob es den Mathematiker wirklich gab, und halte den Wortlaut dann für bestätigt, weil die Szene von einer belegten Person handelt.","Ich prüfe, ob andere Artikel die Szene genauso erzählen, und halte sie dann für gesichert, weil sie offenbar auf eine gemeinsame Quelle zurückgeht.","Ich übernehme den Satz des Mathematikers vorerst, weil sein Kerngedanke stimmt und eine so treffende Szene wohl auch im Wortlaut stimmt."],"correctIndex":0,"explanation":"Anschauliche Details wie wörtliche Dialoge sind kein Beleg, sondern oft das Ergebnis dramatisierenden Nacherzählens. Real ist Walds Arbeit für die Statistical Research Group der Columbia University, für die er 1943 Memoranden verfasste, die aus den Treffern zurückgekehrter Flugzeuge die Verwundbarkeit einzelner Flugzeugteile schätzen. Eine ausdrückliche Empfehlung, wo gepanzert werden soll, enthalten sie nicht, und der Dialog selbst ist nicht dokumentiert. Auch die Rahmung vom einsamen Außenseiter greift zu kurz, denn das US-Militär wertete Kampfschäden bereits systematisch aus. Die vernünftige Haltung trennt also zwischen dem prüfbaren Kern (der Idee der Auswahlverzerrung: Die Daten der Zurückgekehrten verzerren das Bild) und der ungesicherten Ausschmückung.","coreRule":"⚡ Eine gute Lehrgeschichte ist noch keine Quelle – prüfe, was davon belegt ist.","beleg":"Werkstück B.15 (Die unsichtbaren Einschusslöcher); Fn. gl-b-wald (Mangel/Samaniego 1984, JASA 79(386), S. 259–267)","status":"entwurf","scenario":"Der Artikel erzählt eine mitreißende Geschichte über Abraham Wald und die Panzerung von Bombern. Wörtliche Dialoge, genaue Trefferverteilungen und ein einsamer Held, der die ahnungslosen Militärs belehrt, machen die Erzählung sehr anschaulich. Eine Quelle für diese Details nennt der Artikel nicht.","kurz":"Der Kerngedanke, dass die Daten der Zurückgekehrten das Bild verzerren, ist prüfbar. Der wörtliche Dialog ist es nicht: Anschauliche Details ohne Quelle sind kein Beleg, sondern oft dramatisierende Ausschmückung.","prueffrage":"Woher könnte ein Magazin heute den genauen Wortlaut eines Satzes kennen, der vor über 80 Jahren in einer Besprechung gefallen sein soll?","rueckmeldung":[{"option":1,"text":"Dass es Wald gab, lässt sich belegen, und das spricht für den Kern. Ob er aber genau diese Worte gesagt hat, folgt daraus nicht, denn auch um reale Personen werden Szenen frei ausgeschmückt."},{"option":2,"text":"Der Vergleich mit anderen Artikeln ist ein guter Reflex. Übereinstimmende Erzählungen können aber voneinander abgeschrieben sein oder auf dieselbe unbelegte Fassung zurückgehen. Wiederholung ersetzt keine Quelle."},{"option":3,"text":"Der Kerngedanke stimmt, doch er sagt nichts über den Wortlaut. Dass die Szene so treffend wirkt, spricht eher für sorgfältiges Erzählen als für Echtheit. Ungesichertes gilt so lange nicht als belegt, bis eine Quelle es trägt."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"},{"typ":"doi","kurz":"Mangel, M.; Samaniego, F. J. (1984): Abraham Wald's Work on Aircraft Survivability. Journal of the American Statistical Association 79(386), 259–267","oeffentlich":false,"doi":"10.1080/01621459.1984.10478038"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4b418c5692dfc56d"}},{"id":"qx-b1-055","clusterId":"B","werkstueckRef":"B.15","stufe":4,"question":"Welche Frage prüft die Behauptung des Architekten am besten?","scenario":"Ein Architekt behauptet: „Früher hat man besser gebaut. Sieh dir die alten Häuser an, die noch heute stehen!“","options":["Wie viele der damals gebauten Häuser sind inzwischen abgerissen oder eingestürzt?","Wie gut ist der Zustand der alten Häuser, die heute noch stehen, nach so vielen Jahren?","Wie viele der heute gebauten Häuser zeigen schon nach wenigen Jahren erste Bauschäden?","Welche Baustoffe haben die alten Häuser, die heute noch stehen, so lange halten lassen?"],"correctIndex":0,"explanation":"Die Behauptung stützt sich nur auf Gebäude, die einen langen Auswahlprozess überstanden haben: Was baufällig war, wurde abgerissen, umgebaut oder ist eingestürzt. Dass die übrig gebliebenen Häuser solide sind, folgt daraus fast zwangsläufig und sagt wenig über die Bauweise einer ganzen Epoche. Erst der Blick auf die verschwundenen Häuser zeigt, ob früher tatsächlich besser gebaut wurde.","coreRule":"⚡ Was heute noch steht, ist eine Auswahl – nicht die Gesamtheit dessen, was einmal gebaut wurde.","beleg":"Werkstück B.15 (Red Flags; Anwendung & Relevanz)","status":"freigegeben","freigabe":{"datum":"2026-10-15","pruefsumme":"cfe308e1a172babd","vermerk":"Prüfpult (Sturm, erste Charge nach den neuen falschen Optionen)"},"kurz":"Entscheidend ist, wie viele der damals gebauten Häuser verschwunden sind. Die alten Häuser, die noch stehen, sind schon die Auswahl der soliden; dass sie solide sind, folgt fast zwangsläufig und sagt wenig über die ganze Epoche.","prueffrage":"Wer hat im Lauf der Zeit entschieden, welche Häuser stehen bleiben, und nach welchen Gesichtspunkten?","rueckmeldung":[{"option":1,"text":"Der Zustand der alten Häuser lässt sich gut beobachten, und er ist meist gut. Gerade das ist aber schon durch die Auswahl der Übriggebliebenen bedingt; über die verschwundenen Häuser sagt er nichts."},{"option":2,"text":"Heutige Bauschäden zu betrachten, ist in anderem Zusammenhang sinnvoll. Hier vergleicht es aber wenige Jahre alte Neubauten mit Häusern, die schon Jahrzehnte überstanden haben, und lässt die Verluste von damals außen vor."},{"option":3,"text":"Die Frage nach den Baustoffen setzt schon voraus, dass die Bauweise der Grund für die Haltbarkeit ist, also was erst zu prüfen wäre. Auch Lage, Nutzung oder Pflege können mitspielen, und solide Überlebende folgen fast von selbst."}],"familie":"fehlende-faelle-suchen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Casselman, B. (2016): The Legend of Abraham Wald. AMS Feature Column","oeffentlich":true,"url":"https://www.ams.org/publicoutreach/feature-column/fc-2016-06","abruf":"2026-10-04"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"ok","pruefsumme":"cfe308e1a172babd"}},{"id":"qx-b1-056","clusterId":"B","werkstueckRef":"B.16","stufe":1,"question":"Was passiert sprachlich, wenn Menschen im Netz als „Bots“ oder „NPCs“ abgetan werden, und was ist daran problematisch?","options":["Die Menschen werden pauschal über einen Kamm geschoren, sodass Unterschiede zwischen ihren Meinungen nicht mehr wahrgenommen werden.","Die Menschen werden als gefühllose Automaten ohne eigenes Denken dargestellt, sodass ihre Gründe nicht mehr geprüft werden müssen.","Die Menschen werden mit einem Spottwort aus der Spielewelt belegt, sodass vor allem der herabsetzende Ton die Diskussion verschärft.","Die Menschen werden als fremde Gegengruppe ausgegrenzt, sodass vor allem die Diskussion in ein starres Wir gegen die anderen zerfällt."],"correctIndex":1,"explanation":"Wer Menschen als „NPCs“ oder „Bots“ bezeichnet, stellt sie als kalte, gefühllose Automaten dar und beraubt sie damit ihrer Wärme, Individualität und Empathie. Das ist die mechanistische Form der Entmenschlichung: Sie werden wie seelenlose Instrumente behandelt, die nur Skripte abspielen. Die Folge: Wer ein Gegenüber so einordnet, hat keinen Anlass mehr, dessen Gründe ernst zu nehmen, denn bei einem Automaten gibt es keine eigenen Gründe. Entscheidend ist also, ob dem Gegenüber das eigene Denken und Fühlen abgesprochen wird oder ob nur seine Position kritisiert wird. Die Kritik an einer Position ist legitim, die Aberkennung des Menschseins ist es nicht.","coreRule":"⚡ Wer anderen das eigene Denken und Fühlen abspricht, muss ihre Gründe nicht mehr prüfen.","beleg":"Werkstück B.16 (Kontext & Tiefe: Zwei Mechanismen; Anwendung & Relevanz: In der politischen Propaganda)","status":"entwurf","scenario":"In einem Kommentarbereich schreibt jemand unter eine Diskussion: „Mit denen brauchst du gar nicht zu reden. Das sind doch alles NPCs, die immer dieselben Sätze runterbeten.“ Die Angesprochenen sind echte Menschen mit eigenen Gründen für ihre Meinung.","kurz":"Wer Menschen „NPCs“ nennt, stellt sie als Automaten dar, die nur Skripte abspielen. Dann gibt es scheinbar keine eigenen Gründe mehr, die man prüfen müsste. Kritik an einer Position ist legitim, aber das Menschsein abzusprechen ist es nicht.","prueffrage":"Worauf bezieht sich die Aussage: auf das, was die Leute vorbringen, oder auf die Leute selbst?","rueckmeldung":[{"option":0,"text":"Dass hier alle über einen Kamm geschoren werden, stimmt, und das blendet Unterschiede aus. Pauschalisieren geht aber auch ohne dieses Wort. Das Besondere ist, dass den Menschen das eigene Denken abgesprochen wird, sodass ihre Gründe niemand mehr prüft."},{"option":2,"text":"„NPC“ ist tatsächlich ein Spottwort aus der Spielewelt, und Spott kann eine Diskussion anheizen. Der Kern liegt aber nicht im Ton: Auch ein freundlich gemeinter Satz, der anderen das eigene Denken und Fühlen abspricht, hätte dieselbe Wirkung."},{"option":3,"text":"Ein „Wir gegen die“ kann aus solchen Etiketten entstehen. Das Bild vom Automaten geht aber weiter, als jemanden zur fremden Gruppe zu erklären: Einem Gegner kann man Gründe zugestehen, einem Automaten gar nicht. Genau das macht die Bezeichnung problematisch."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Haslam (2006), Verlagsfassung","oeffentlich":false,"doi":"10.1207/s15327957pspr1003_4"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"3df0a258609fe51c"}},{"id":"qx-b1-057","clusterId":"B","werkstueckRef":"B.16","stufe":2,"question":"Ein Kommentator behauptet: „Der Völkermord in Ruanda 1994 ist allein den Hetzsendungen eines Radiosenders zuzuschreiben. Ohne dieses Radio wäre nichts passiert.“ Wie beurteilst du diese Behauptung am besten?","options":["Die Behauptung überschätzt das Radio: Hetzsprache kann Hemmungen senken und das Töten erleichtern, aber andere Faktoren wirkten daneben mit.","Die Behauptung trifft im Kern zu: Wer monatelang „Kakerlaken“ und „Ungeziefer“ hört, verliert Hemmungen, und ohne das wäre das Töten kaum geschehen.","Die Behauptung bleibt offen: Wie viel Radio, Hetzblätter und Behörden jeweils bewirkt haben, lässt sich im Nachhinein kaum auseinanderhalten.","Die Behauptung überschätzt die Sprache: Angst vor dem Krieg und die Mobilisierung durch Behörden erklären das Töten, die Hetze war nur Begleitmusik."],"correctIndex":0,"explanation":"Die Behauptung macht aus einem Faktor die einzige Ursache. Wer Nachbarn monatelang als „Ungeziefer“ bezeichnet, löst moralische Hemmungen und macht das Töten sprachlich leichter. Zugleich gab es weitere Treiber: die Angst vor dem Krieg, Hetzblätter und die Mobilisierung durch Behörden und Bürgermeister. Ein Ereignis mit mehreren zusammenwirkenden Ursachen auf eine einzige zu verkürzen, ist ein typischer Denkfehler. Auch das Gegenteil, Sprache habe gar keine Wirkung, wäre falsch, denn Ursachen können sich verstärken.","coreRule":"⚡ Sprache kann Hemmungen lösen, erklärt aber nie allein die Tat.","beleg":"Werkstück B.16 (Die Kakerlaken im Radio); Fn. gl-b-rtlm (Human Rights Watch 1999, „Leave None to Tell the Story“)","status":"entwurf","scenario":"Der Sender sprach über die Tutsi nicht als Nachbarn, sondern über Monate hinweg als „Kakerlaken“ und „Ungeziefer“. Zur gleichen Zeit herrschten Angst vor dem Krieg, es kursierten Hetzblätter, und Behörden und Bürgermeister mobilisierten die Bevölkerung.","quote":"","quoteLabel":"","kurz":"„Allein“ und „ohne Radio nichts“ machen aus einem Faktor die einzige Ursache. Monatelange Entmenschlichung senkte Hemmungen, doch Kriegsangst, Hetzblätter und Behörden wirkten mit. Mehrere zusammenwirkende Ursachen auf eine zu verkürzen, ist der Denkfehler.","prueffrage":"Welche anderen Umstände gab es zur gleichen Zeit, und was hätten sie allein bewirken können?","rueckmeldung":[{"option":1,"text":"Dass monatelanges „Ungeziefer“-Gerede Hemmungen senkt, stimmt. Der Schluss, ohne diese Sendungen wäre kaum etwas geschehen, macht das Radio aber zur einzigen Ursache und übergeht Kriegsangst, Hetzblätter und die Mobilisierung durch Behörden."},{"option":2,"text":"Wie groß der Anteil jedes Faktors war, lässt sich wohl kaum genau sagen. Um „allein“ zurückzuweisen, braucht man das aber nicht: Dass mehrere Treiber zusammenwirkten, reicht, und genau das entzieht der Behauptung den Boden."},{"option":3,"text":"Kriegsangst und die Mobilisierung durch Behörden waren tatsächlich wichtige Treiber. Die Hetze deshalb zur bloßen Begleitmusik zu erklären, kippt ins Gegenteil, denn monatelange Entmenschlichung senkt moralische Hemmungen, und Ursachen können sich verstärken."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v9","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"fb43e64075cacb21"}},{"id":"qx-b1-058","clusterId":"B","werkstueckRef":"B.16","stufe":3,"question":"Eine Politikerin sagt in einer Talkshow: „Menschen, die ihre Gegner als ‚Ungeziefer‘ bezeichnen, tun das, weil sie sie töten wollen, denn Entmenschlichung ist die Ursache jeder Gewalt.“ Was folgt aus diesen Befunden für ihre Behauptung?","options":["Sie wird bestätigt, denn bei Gewalt aus Nutzen ging stärkere Entmenschlichung tatsächlich mit mehr Gewaltbereitschaft einher.","Sie geht zu weit, denn bei Gewalt, die als gerecht empfunden wird, fehlte der Zusammenhang, und damit trifft „jede Gewalt“ nicht zu.","Sie wird gestützt, denn wer andere entmenschlichte, war eher zu Gewalt bereit, und genau das tut, wer Gegner „Ungeziefer“ nennt.","Sie wird im Kern bestätigt, denn Entmenschlichung hing mit Gewaltbereitschaft zusammen; gerecht empfundene Gewalt ist eine Ausnahme."],"correctIndex":1,"explanation":"Die Behauptung verallgemeinert: Aus „Entmenschlichung kommt bei manchen Gewalttaten vor“ wird „sie erklärt jede Gewalt“. Gegen eine solche Allaussage genügt eine Gewaltart ohne den Zusammenhang, und die zeigte sich hier: Bei Gewalt, die als gerecht empfunden wird, ging Entmenschlichung nicht mit mehr Bereitschaft einher, bei Gewalt aus Nutzen dagegen schon. Zwei Grenzen gehören dazu: Gemessen wurden Einstellungen und gedachte Szenarien, keine Taten, und Entmenschlichung nur als abgesprochenes Denken und Fühlen, nicht als Tiervergleich wie „Ungeziefer“. „Jede Gewalt“ ist also zu stark, „keine Gewalt“ wäre es ebenfalls.","coreRule":"⚡ Wer „jede“ oder „immer“ behauptet, braucht nur einen gut belegten Gegenfall zu fürchten: Entmenschlichung erklärt nicht jede Gewalt, denn wer „gerecht“ bestrafen will, braucht einen vollen Menschen als Ziel.","beleg":"Werkstück B.16 (Hinweis zur Beleglage); Fn. gl-b-rai (Rai/Valdesolo/Graham 2017, PNAS 114(32), S. 8511–8516); Fn. gl-b-kteily-folter (Kteily u. a. 2015, JPSP 109(5), S. 901–931)","status":"entwurf","scenario":"In Experimenten und Befragungen mit Online-Teilnehmern (Einstellungsfragen und gedachte Szenarien, keine echten Täter) wurde die Bereitschaft zu zwei Arten von Gewalt erhoben: Gewalt aus Nutzen (etwa einem Fremden für Geld schaden) und Gewalt, die als gerecht empfunden wird (etwa Strafe für ein Fehlverhalten). Entmenschlichung wurde dabei als abgesprochene Fähigkeit zu denken und zu fühlen gemessen. Ergebnis: Wer ein Opfer stärker entmenschlichte, war eher zu Gewalt aus Nutzen bereit. Bei Gewalt, die als gerecht empfunden wird, zeigte sich dieser Zusammenhang nicht; wer sich vorstellte, einen Fremden für sein Fehlverhalten zu bestrafen, hielt ihn sogar für menschlicher.","kurz":"Die Behauptung macht aus „kommt bei mancher Gewalt vor“ ein „erklärt jede Gewalt“. Schon eine Gewaltart ohne den Zusammenhang widerlegt eine solche Allaussage, und bei gerecht empfundener Gewalt fehlte er hier. „Keine Gewalt“ wäre allerdings ebenso zu stark.","prueffrage":"Wie wurden Gewaltbereitschaft und Entmenschlichung in den Studien gemessen, und wie nah ist das an dem, wovon die Politikerin spricht?","rueckmeldung":[{"option":0,"text":"Bei Gewalt aus Nutzen stimmt der Zusammenhang tatsächlich. Die Politikerin spricht aber von „jeder Gewalt“, und bei gerecht empfundener Gewalt fehlte er. Außerdem wurden nur Einstellungen und gedachte Szenarien erhoben, daher ist von einer Ursache keine Rede."},{"option":2,"text":"Ein Zusammenhang bei einer Gewaltart trägt keine Aussage über jede Gewalt, und bei gerecht empfundener Gewalt fehlte er. Gemessen wurde zudem abgesprochenes Denken und Fühlen, nicht der Tiervergleich „Ungeziefer“. Ein „weil sie töten wollen“ lässt sich daraus nicht ableiten."},{"option":3,"text":"Der Zusammenhang bei Gewalt aus Nutzen ist richtig beschrieben. Bei einer Allaussage ist die gerecht empfundene Gewalt aber keine Randnotiz, sondern der Gegenfall: Dort fehlte der Zusammenhang, und das Opfer wurde sogar als menschlicher eingeschätzt. Daher bleibt nur eine eingeschränkte Aussage."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Rai, T. S.; Valdesolo, P.; Graham, J. (2017): Dehumanization increases instrumental violence, but not moral violence. PNAS 114(32), 8511–8516 (frei in PMC5559031)","oeffentlich":true,"doi":"10.1073/pnas.1705238114","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"4401653615fe24ea"}},{"id":"qx-b1-059","clusterId":"B","werkstueckRef":"B.16","stufe":4,"question":"Welche Beurteilung wird dieser Sprache am besten gerecht?","scenario":"In einem Forum lest ihr Kommentare, die eine Gruppe von Menschen durchgehend „Ungeziefer“ und „Seuche“ nennen und von der „Säuberung“ der Gesellschaft sprechen. Zu Gewalt wird nirgends ausdrücklich aufgerufen. Eine Mitleserin meint: „Das ist doch nur Wut, das darf man nicht so ernst nehmen.“","options":["Es ist wohl eher Frust, denn solange kein ausdrücklicher Aufruf zu Gewalt fällt, deutet „Ungeziefer“ in einem Forum meist auf Wut hin.","Es ist vor allem eine schwere Beleidigung, denn Wörter wie „Seuche“ und „Säuberung“ verletzen die Würde der beschriebenen Gruppe.","Es ist ein Warnsignal, denn die Gleichsetzung einer ganzen Gruppe mit Ungeziefer senkt die Hemmung vor Gewalt, auch ohne offenen Aufruf.","Es sagt vor allem etwas über die Schreibenden aus, denn wer eine ganze Gruppe „Ungeziefer“ nennt, zeigt damit in erster Linie seine Haltung."],"correctIndex":2,"explanation":"Entscheidend ist, was die Sprache bewirkt, nicht ob sie einen ausdrücklichen Aufruf enthält. Ein einzelner Spruch wie „fauler Hund“ ist nur die mildeste Form der Entmenschlichung. Wird dagegen eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt, als Seuche beschrieben und ihre Beseitigung als „Säuberung“ gerahmt, ist das etwas anderes: Sie wird aus dem Kreis derer herausgenommen, denen man moralische Rücksicht schuldet. Das kann Gewalt erleichtern, weil die Hemmung, Menschen zu schaden, bei „Ungeziefer“ weniger greift; nicht jede Gewalt erklärt sich allerdings so. In Ruanda 1994 gingen Monate der Hetze gegen „Kakerlaken“ dem Völkermord voraus. Die Sprache allein erklärt solche Taten nicht, denn Angst, Krieg und organisierte Mobilisierung kamen hinzu, aber sie lieferte die Wörter, die das Töten leichter machten. Die Einordnung als Warnsignal beurteilt die Sprache, nicht die Person, die sie benutzt. Dass kein ausdrücklicher Aufruf vorliegt, stimmt, hilft aber nicht weiter, denn die Vorbereitung geschieht meist unterhalb des Aufrufs.","coreRule":"⚡ Wird eine ganze Gruppe durchgehend mit Ungeziefer gleichgesetzt und ihre Beseitigung als „Säuberung“ gerahmt, ist das ein Warnsignal, auch wenn kein offener Gewaltaufruf fällt.","beleg":"Werkstück B.16 (Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Entscheidend ist, was solche Sprache bewirkt, nicht ob sie ausdrücklich zu Gewalt aufruft. Wer eine ganze Gruppe durchgehend als Ungeziefer und Seuche beschreibt, nimmt sie aus dem Kreis derer heraus, denen man Rücksicht schuldet, und kann so Gewalt erleichtern.","prueffrage":"Gegen wen richten sich die scharfen Wörter: gegen Meinungen und Handlungen oder gegen Menschen allein wegen ihrer Zugehörigkeit?","rueckmeldung":[{"option":0,"text":"Dass kein ausdrücklicher Aufruf fällt, stimmt, und Wut ist in Foren häufig. Daraus folgt aber keine Entwarnung: Die Vorbereitung geschieht meist unterhalb des Aufrufs, und hier wird die Gruppe durchgehend entmenschlicht, nicht nur beschimpft."},{"option":1,"text":"Dass die Wörter die Würde der Gruppe verletzen, trifft zu. Als bloße Beleidigung greift die Einordnung aber zu kurz, denn Gleichsetzung mit Ungeziefer und „Säuberung“ nehmen die Gruppe aus dem Kreis moralischer Rücksicht heraus und können so Gewalt erleichtern."},{"option":3,"text":"Solche Sprache lässt sich als Haltung lesen, doch gefragt ist nach der Sprache selbst: Was bewirken diese Wörter? Über die Schreibenden weißt du aus ein paar Kommentaren wenig, über die Wirkung der Wörter dagegen viel."}],"familie":"wir-und-die-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Human Rights Watch (1999): Leave None to Tell the Story: Genocide in Rwanda, Kap. „Propaganda and Practice“","oeffentlich":true,"url":"https://www.hrw.org/reports/1999/rwanda/Geno1-3-10.htm","abruf":"2026-10-12"},{"typ":"url","kurz":"Haslam, N. (2006): Dehumanization: An Integrative Review. Personality and Social Psychology Review 10(3), 252–264 (PubMed-Abstract)","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/16859440/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Over, H. (2021): Seven Challenges for the Dehumanization Hypothesis. Perspectives on Psychological Science 16(1), 3–13 (frei in PMC7809340)","oeffentlich":true,"doi":"10.1177/1745691620902133","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v8","modell":"claude-sonnet-5-5","datum":"2026-10-15","urteil":"korrigieren","pruefsumme":"b4434ccc0eee1d6f"}}]`);export{t as n,n as t};